    //#region 🔖️MediaPort
    /// 🎞️ `MediaWireFormat` backs `MediaArtifactDescriptor::wire` (see `🔖️DocumentContract`
    /// below) — the plugin ABI's `consume-media`/`produce-media` payload framing, separate from
    /// `MediaPayload` above (which pairs with `Media`'s per-port `MediaType` projection).
    /// The legacy format enum was retired in ticket 26/08/11/
    /// SEMIO-ARTIFACT-UNIFIED-IMPORT-EXPORT-AND-MEDIA-FORMAT-RETIREMENT W6 — `MediaWireFormat::
    /// Binary` now carries a plain format kind id string.
    pub use semio_framework::MediaWireFormat;
    /// 🎞️ The `Media`/`MediaPayload`/`MediaFingerprint`/`MediaError` value vocabulary backing
    /// `ArtifactApp::{media_ports, export_media, import_media, media_fingerprint}` — re-exported so
    /// implementers never need a direct `semio-framework-core` dependency just to satisfy this trait.
    pub use semio_framework::{Media, MediaError, MediaFingerprint, MediaPayload};
    /// 🧬️ `MediaClass`/`MediaType` also live in `semio-framework-core` — re-exported so callers can build
    /// `ArtifactKindSpec.media_type` and `AppBuilder::media_input(...)`/`media_output(...)` port specs
    /// without a direct `semio-framework-core` dependency.
    pub use semio_framework::{MediaClass, MediaType};
    //#endregion 🔖️MediaPort

    //#region 🔖️Dialect
    /// ⚠️ IO error alias from the framework media stack.
    pub use semio_framework::IoError;

    /// 🏅️🪆️🎯️ Standards/subsets dialect vocabulary (ticket 26/08/10/STDIO-ARTIFACTS-AND-IO phase
    /// 2). Defined in `semio_framework` so plugins and the OS product
    /// share one definition without an inverted dependency; re-exported here verbatim.
    pub use semio_framework::{
        io_compose_via, io_dialects_for, io_dispatch, io_keys_for, io_resolve, list_composer_entries, register_composer_entries, register_subset_validator, resolve_ready, set_io_fallback_dispatcher, subset_validator_entry_of, wire_artifact_compose,
        wire_decode_composed_artifact, wire_list_composer_entries, Analysis, AnalyzeSource, ArtifactDialect, AsyncComposeFn, ComposeError, ComposeFuture, ComposeSource, ComposedArtifact, ComposerEntry, Composition, Dialect, ErasedComposeSource, IoConfidence,
        IoDirection, IoFallback, IoFallbackDispatcher, IoKey, IoPayload, IoResolveError, StandardId, SubsetId, SubsetValidator, SubsetValidatorEntry, WireComposeSource, WireComposedArtifact,
    };

    /// 🧵️ Directed snapshot conversion out of this dialect into a foreign dialect. One unit
    /// struct per `🚪️io/📤️export/🧵️serializers/…` leaf.
    pub trait ArtifactSerializer {
        type From;
        type Into;
        const FROM: Dialect;
        const INTO: Dialect;
        /// 🌀️ `io-async-signatures`: async signature, behaviourally unchanged body — every
        /// existing leaf's `serialize` never truly awaits, so its future resolves the moment it
        /// is first polled (see `resolve_ready` in the framework io module).
        /// 🌊️ O1/S4 (sdk-dedyn): plain AFIT, NOT `-> impl Future<..> + Send` — the latter is exactly
        /// the double-future shape R1 bans (a future whose OWN output is a second future); every
        /// real leaf already implements the corrected single-future signature below.
        async fn serialize(from: &Self::From) -> Result<Self::Into, store::PackError>;
    }

    /// 🧩️ Directed snapshot conversion from a foreign dialect into this dialect. One unit struct
    /// per `🚪️io/📥️import/🧩️deserializers/…` leaf.
    pub trait ArtifactDeserializer {
        type From;
        type Into;
        const FROM: Dialect;
        const INTO: Dialect;
        /// 🌀️ `io-async-signatures`: async signature, behaviourally unchanged body — see
        /// `ArtifactSerializer::serialize`'s doc comment for the ready-future guarantee.
        /// 🌊️ O1/S4 (sdk-dedyn): plain AFIT — see `ArtifactSerializer::serialize`'s doc for why.
        async fn deserialize(from: &Self::From) -> Result<Self::Into, store::PackError>;
    }

    /// 🎹️ Subset-level composer: analyze foreign/native sources, build one snapshot in `WRITES`.
    /// Standard- and artifact-level (final) composers aggregate `ComposerEntry` rows value-level
    /// (see `ComposerEntry::of` convention on the framework side) rather than via this trait.
    pub trait ArtifactComposer: Sized {
        type Snapshot;
        const WRITES: Dialect;
        async fn reads() -> &'static [Dialect];
        /// 🌀️ `io-async-signatures`: async signature, behaviourally unchanged body — see
        /// `ArtifactSerializer::serialize`'s doc comment for the ready-future guarantee.
        /// 🌊️ O1/S4 (sdk-dedyn): plain AFIT — see `ArtifactSerializer::serialize`'s doc for why.
        async fn compose(sources: &[ComposeSource<'_>]) -> Result<Composition<Self::Snapshot>, ComposeError>;
    }

    /// 🎹️ Erases a typed `ArtifactComposer` into a `ComposerEntry` row for `register_composer_entries`.
    /// Lives here (not in `semio_framework_io`) because it needs the `ArtifactComposer` trait, which
    /// the lower-layer io module can't see. Erasure round-trips the snapshot through the same
    /// `store::ArtifactPack` binary codec `ArtifactBuilder::from_binary` already uses.
    // 🚫️async: E1 pure struct-builder consumed by `std::sync::Once::call_once`'s fixed sync closure
    // (the `subset!` macro's `__subset_registration::register`) — see R9. The erased `compose` field
    // it installs stays a real async boundary; only the OUTER registration-row builder is sync.
    pub fn composer_entry_of<C: ArtifactComposer>() -> ComposerEntry
    where
        C::Snapshot: ArtifactPack,
    {
        // 🚫️async: E4 fn-pointer slot — `ComposerEntry.compose: AsyncComposeFn` is a bare fn pointer;
        // an `async fn` item's pointer type is unnameable, so the erasure itself must be a plain `fn`
        // returning the already-boxed future.
        fn erased_compose<C: ArtifactComposer>(sources: &[ErasedComposeSource]) -> ComposeFuture<'_>
        where
            C::Snapshot: ArtifactPack,
        {
            Box::pin(async move {
                let typed_sources: Vec<ComposeSource<'_>> = sources
                    .iter()
                    .map(|s| ComposeSource {
                        dialect: s.dialect,
                        payload: match &s.payload {
                            IoPayload::Text(t) => AnalyzeSource::Text(t.as_str()),
                            IoPayload::Binary(b) => AnalyzeSource::Binary(b.as_slice()),
                        },
                    })
                    .collect();
                let composed = C::compose(&typed_sources).await?;
                let bytes = ArtifactPack::encode_pack(&composed.snapshot);
                Ok(ComposedArtifact { dialect: C::WRITES, payload: IoPayload::Binary(bytes.await), diagnostics: composed.diagnostics, confidence: composed.confidence })
            })
        }
        ComposerEntry { writes: C::WRITES, reads: resolve_ready(C::reads()), compose: erased_compose::<C> }
    }

    /// 🧩️ Erases a typed `ArtifactDeserializer` into a `ComposerEntry` row, same shape as
    /// `composer_entry_of` but single-read (exactly one source — unlike a composer's multi-source
    /// union, a directed conversion has exactly one origin dialect) and via `Dialect`-typed
    /// snapshots rather than raw text/binary: the source payload is decoded as `D::From` (its own
    /// `store::ArtifactPack` codec), `D::deserialize` runs the typed conversion, and the result is
    /// re-packed as `D::Into` the same way `composer_entry_of` re-packs its `Composition::snapshot`.
    /// Registered through a subset composer's `register()` into the same `IoKey → ComposerEntry`
    /// registry composer entries already use.
    // 🚫️async: E1 pure struct-builder — see `composer_entry_of`'s doc for why this must be sync.
    pub fn deserializer_entry_of<D: ArtifactDeserializer>() -> ComposerEntry
    where
        D::From: ArtifactPack + Send,
        D::Into: ArtifactPack,
    {
        // 🚫️async: E4 fn-pointer slot — see `composer_entry_of`'s inner `erased_compose` doc.
        fn erased_compose<D: ArtifactDeserializer>(sources: &[ErasedComposeSource]) -> ComposeFuture<'_>
        where
            D::From: ArtifactPack + Send,
            D::Into: ArtifactPack,
        {
            Box::pin(async move {
                let source = match sources {
                    [one] => one,
                    other => {
                        return Err(ComposeError { message: format!("deserializer {}->{} needs exactly 1 source, got {}", D::FROM.artifact_kind, D::INTO.artifact_kind, other.len()), diagnostics: Vec::new() });
                    }
                };
                let bytes = match &source.payload {
                    IoPayload::Binary(b) => b.as_slice(),
                    IoPayload::Text(_) => {
                        return Err(ComposeError { message: format!("deserializer {}->{} source must be Binary (ArtifactPack-encoded)", D::FROM.artifact_kind, D::INTO.artifact_kind), diagnostics: Vec::new() });
                    }
                };
                let from =
                    <D::From as ArtifactPack>::decode_pack(bytes).await.map_err(|e| ComposeError { message: format!("deserializer {}->{} failed to decode source: {e:?}", D::FROM.artifact_kind, D::INTO.artifact_kind), diagnostics: Vec::new() })?;
                let into = D::deserialize(&from).await.map_err(|e| ComposeError { message: format!("deserializer {}->{} failed: {e:?}", D::FROM.artifact_kind, D::INTO.artifact_kind), diagnostics: Vec::new() })?;
                let bytes = <D::Into as ArtifactPack>::encode_pack(&into);
                Ok(ComposedArtifact { dialect: D::INTO, payload: IoPayload::Binary(bytes.await), diagnostics: Vec::new(), confidence: IoConfidence::High })
            })
        }
        ComposerEntry { writes: D::INTO, reads: &[D::FROM], compose: erased_compose::<D> }
    }

    /// 🧵️ Erases a typed `ArtifactSerializer` into a `ComposerEntry` row — mirror image of
    /// `deserializer_entry_of`: writes `S::INTO`, reads exactly `[S::FROM]`, decodes the single
    /// source as `S::From`, runs `S::serialize`, re-packs the result as `S::Into`.
    // 🚫️async: E1 pure struct-builder — see `composer_entry_of`'s doc for why this must be sync.
    pub fn serializer_entry_of<S: ArtifactSerializer>() -> ComposerEntry
    where
        S::From: ArtifactPack + Send,
        S::Into: ArtifactPack,
    {
        // 🚫️async: E4 fn-pointer slot — see `composer_entry_of`'s inner `erased_compose` doc.
        fn erased_compose<S: ArtifactSerializer>(sources: &[ErasedComposeSource]) -> ComposeFuture<'_>
        where
            S::From: ArtifactPack + Send,
            S::Into: ArtifactPack,
        {
            Box::pin(async move {
                let source = match sources {
                    [one] => one,
                    other => {
                        return Err(ComposeError { message: format!("serializer {}->{} needs exactly 1 source, got {}", S::FROM.artifact_kind, S::INTO.artifact_kind, other.len()), diagnostics: Vec::new() });
                    }
                };
                let bytes = match &source.payload {
                    IoPayload::Binary(b) => b.as_slice(),
                    IoPayload::Text(_) => {
                        return Err(ComposeError { message: format!("serializer {}->{} source must be Binary (ArtifactPack-encoded)", S::FROM.artifact_kind, S::INTO.artifact_kind), diagnostics: Vec::new() });
                    }
                };
                let from = <S::From as ArtifactPack>::decode_pack(bytes).await.map_err(|e| ComposeError { message: format!("serializer {}->{} failed to decode source: {e:?}", S::FROM.artifact_kind, S::INTO.artifact_kind), diagnostics: Vec::new() })?;
                let into = S::serialize(&from).await.map_err(|e| ComposeError { message: format!("serializer {}->{} failed: {e:?}", S::FROM.artifact_kind, S::INTO.artifact_kind), diagnostics: Vec::new() })?;
                let bytes = <S::Into as ArtifactPack>::encode_pack(&into);
                Ok(ComposedArtifact { dialect: S::INTO, payload: IoPayload::Binary(bytes.await), diagnostics: Vec::new(), confidence: IoConfidence::High })
            })
        }
        ComposerEntry { writes: S::INTO, reads: &[S::FROM], compose: erased_compose::<S> }
    }
    //#endregion 🔖️Dialect

    //#region 🔖️ArtifactBuilder
    /// 🏗️ Incremental artifact materializer — snapshot/text/binary in, soft `Diagnostic`s out.
    /// `mutate` returns the authoritative mutation outcome alongside the mutated builder. The
    /// builder applies `outcome.diff()` once and returns that outcome intact, preserving every
    /// diagnostic message without a second semantics computation. Persisted diffs cross the
    /// fallible `absorb` boundary so malformed input cannot become an unchanged snapshot.
    pub trait ArtifactBuilder: Sized {
        type Snapshot;
        type Mutation: Mutation<Self::Snapshot, Diff = Self::Diff>;
        type Diff;
        async fn empty() -> Self;
        async fn from_snapshot(snapshot: Self::Snapshot) -> Self;
        async fn from_text(text: &str) -> Result<Self, store::TextError>;
        async fn from_binary(bytes: &[u8]) -> Result<Self, store::PackError>;
        async fn mutate(self, mutation: Self::Mutation) -> (Self, protocol::MutationOutcome<Self::Diff>);
        async fn absorb(self, diff: Self::Diff) -> protocol::MutationApplyResult<Self>;
        async fn build(self) -> Result<Self::Snapshot, Vec<dsl::Diagnostic>>;
    }

    /// 🎚 Soft confidence for partial decomposition success.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Confidence {
        High,
        Medium,
        Low,
    }

    /// 📥 One decomposition source blob.
    #[derive(Clone, Debug)]
    pub enum DecomposeSource<'a> {
        Text(&'a str),
        Binary(&'a [u8]),
    }

    /// 📦 Decomposition result carrying soft diagnostics (never `Fault` for partial success).
    #[derive(Clone, Debug)]
    pub struct Decomposition<T> {
        pub parts: T,
        pub confidence: Confidence,
        pub diagnostics: Vec<dsl::Diagnostic>,
    }

    /// 📑️ Splits heterogeneous sources into typed parts with soft diagnostics.
    pub trait ArtifactDecomposer: Sized {
        type Snapshot;
        type Parts;
        async fn decompose(sources: &[DecomposeSource<'_>]) -> Decomposition<Self::Parts>;
    }

    /// 🧐️ Standards/subsets successor to `ArtifactDecomposer` (ticket 26/08/10/STDIO-ARTIFACTS-AND-IO
    /// phase 2): read-only analysis that also reports which `Dialect` it recognized, so aggregate
    /// composers can route a payload to the right standard (e.g. GIF87a vs GIF89a, `%PDF-1.x`).
    /// New artifacts implement this directly; migrated artifacts keep `ArtifactDecomposer` until
    /// their own migration wave swaps it -- both traits coexist until the global W16 strict flip.
    pub trait ArtifactAnalyzer: Sized {
        type Parts;
        const DIALECT: Dialect;
        /// 👃️ Cheap recognizability probe -- no allocation, no full parse.
        async fn sniff(source: &AnalyzeSource<'_>) -> IoConfidence;
        async fn analyze(sources: &[AnalyzeSource<'_>]) -> Analysis<Self::Parts>;
    }

    //#region 🧬️DerivedArtifactFacets
    /// 🧐️ Schema-owned analysis hook used by the derived analyzer.
    pub trait ArtifactAnalysis: 'static {
        type Parts;

        const DIALECT: Dialect;

        async fn sniff(source: &AnalyzeSource<'_>) -> IoConfidence;

        async fn analyze(sources: &[AnalyzeSource<'_>]) -> Analysis<Self::Parts>;
    }

    /// 🎹️ IO-owned composition hook used by the derived composer.
    pub trait ArtifactComposition: 'static {
        type Snapshot;

        const WRITES: Dialect;

        async fn reads() -> &'static [Dialect];

        async fn compose(sources: &[ComposeSource<'_>]) -> Result<Composition<Self::Snapshot>, ComposeError>;
    }

    /// 🧩️ UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM (C1, Task 5): schema-owned child-composition hook —
    /// the derived analogue of `ArtifactComposition` for an artifact whose snapshot is assembled
    /// from OTHER artifacts' packs via declared `#[child(kind = "…")]` slots
    /// (`semio_framework_schema::ArtifactCompositionFields`), rather than only foreign-dialect IO
    /// sources. `Snapshot` deliberately repeats `DerivedArtifactSpec::Snapshot` instead of being
    /// read off it — a bare `type Children: ArtifactChildren` on `DerivedArtifactSpec` cannot itself
    /// constrain `Children::Snapshot == Self::Snapshot` without a where-clause at every use site, so
    /// `DerivedArtifactSpec::Children`'s own bound (below) restates the equality once, centrally.
    pub trait ArtifactChildren {
        type Snapshot;
        /// 🪆️ This artifact's declared child slots — `&[]` for a leaf with no `#[child(...)]`
        /// fields (see `NoChildren`).
        async fn slots() -> &'static [::semio_framework_schema::ChildSlotSpec];
        /// 🏗️ Assembles `Self::Snapshot` from resolver-supplied child packs, one `(dialect, pack
        /// bytes)` pair per slot instance (`many` slots contribute more than one pair for the SAME
        /// `ChildSlotSpec.kind`) — the composition-side counterpart to `decompose_to_children`.
        async fn compose_from_children(parts: &[(ArtifactDialect, Vec<u8>)]) -> Result<Self::Snapshot, ComposeError>;
        /// 📤️ Inverse of `compose_from_children`: the child packs `Self::Snapshot` currently owns,
        /// keyed by their own dialect — the seam `ArtifactChildren`'s own decompose side of the
        /// contract needs so a child's pack can be re-derived/re-exported without re-deriving the
        /// whole parent.
        async fn decompose_to_children(snapshot: &Self::Snapshot) -> Vec<(ArtifactDialect, Vec<u8>)>;
    }

    /// 🍃️ `DerivedArtifactSpec::Children` default for a leaf artifact with zero composition slots —
    /// `slots()` is empty, `decompose_to_children` is always empty, and `compose_from_children`
    /// unconditionally errors (a leaf has nothing to compose FROM children; the derived composer
    /// below never even calls it when `slots()` is empty — see `DerivedArtifactComposer::compose`).
    pub struct NoChildren<S>(std::marker::PhantomData<S>);

    impl<S> ArtifactChildren for NoChildren<S> {
        type Snapshot = S;

        async fn slots() -> &'static [::semio_framework_schema::ChildSlotSpec] {
            &[]
        }

        async fn compose_from_children(_parts: &[(ArtifactDialect, Vec<u8>)]) -> Result<Self::Snapshot, ComposeError> {
            Err(ComposeError { message: "this artifact declares no #[child(...)] slots — NoChildren::compose_from_children is unreachable via the derived composer".into(), diagnostics: Vec::new() })
        }

        async fn decompose_to_children(_snapshot: &Self::Snapshot) -> Vec<(ArtifactDialect, Vec<u8>)> {
            Vec::new()
        }
    }

    /// 🧬️ Hook bundle from which all public artifact lifecycle types are derived.
    pub trait DerivedArtifactSpec: Sized + 'static {
        type Snapshot;
        type Mutation: Mutation<Self::Snapshot, Diff = Self::Diff>;
        type Diff: MutationDiff<Self::Snapshot>;
        type Construction: ArtifactBuilder<Snapshot = Self::Snapshot, Mutation = Self::Mutation, Diff = Self::Diff>;
        type Analysis: ArtifactAnalysis;
        type Composition: ArtifactComposition<Snapshot = Self::Snapshot>;
        /// 🧩️ UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM (C1, Task 5): defaults to `NoChildren<Self::Snapshot>`
        /// for every spec built through `derive_artifact_facets!` without a `children: $ty` arm — see
        /// that macro's own doc comment. Stable Rust has no language-level default associated type, so
        /// the "default" lives at the MACRO level (it always emits a concrete `type Children = …;`),
        /// not here; a hand-written `impl DerivedArtifactSpec` must supply one explicitly.
        type Children: ArtifactChildren<Snapshot = Self::Snapshot>;
    }

    /// 📦️ Analyzer output derived from the artifact snapshot codec.
    #[derive(Clone, Debug, Default)]
    pub struct DerivedArtifactParts<Snapshot> {
        pub snapshot: Option<Snapshot>,
    }

    /// 🏗️ Generic materializer derived from a snapshot, semantic mutation, diff, and optional
    /// subset validation hook.
    pub struct DerivedArtifactBuilder<Spec: DerivedArtifactSpec> {
        construction: Spec::Construction,
    }

    impl<Spec: DerivedArtifactSpec> Clone for DerivedArtifactBuilder<Spec>
    where
        Spec::Construction: Clone,
    {
        fn clone(&self) -> Self {
            Self { construction: self.construction.clone() }
        }
    }

    impl<Spec: DerivedArtifactSpec> std::fmt::Debug for DerivedArtifactBuilder<Spec>
    where
        Spec::Construction: std::fmt::Debug,
    {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter.debug_tuple("DerivedArtifactBuilder").field(&self.construction).finish()
        }
    }

    impl<Spec: DerivedArtifactSpec> Default for DerivedArtifactBuilder<Spec> {
        // 🚫️async: E1 impl of externally-declared `Default` — bridged via `resolve_ready`
        // (`empty()`'s own chain has no real suspension; io-async-signatures).
        fn default() -> Self {
            resolve_ready(Self::empty())
        }
    }

    impl<Spec: DerivedArtifactSpec> ArtifactBuilder for DerivedArtifactBuilder<Spec> {
        type Snapshot = Spec::Snapshot;
        type Mutation = Spec::Mutation;
        type Diff = Spec::Diff;

        async fn empty() -> Self {
            Self { construction: Spec::Construction::empty().await }
        }

        async fn from_snapshot(snapshot: Self::Snapshot) -> Self {
            Self { construction: Spec::Construction::from_snapshot(snapshot).await }
        }

        async fn from_text(text: &str) -> Result<Self, store::TextError> {
            Ok(Self { construction: Spec::Construction::from_text(text).await? })
        }

        async fn from_binary(bytes: &[u8]) -> Result<Self, store::PackError> {
            Ok(Self { construction: Spec::Construction::from_binary(bytes).await? })
        }

        async fn mutate(self, mutation: Self::Mutation) -> (Self, protocol::MutationOutcome<Self::Diff>) {
            let (construction, outcome) = self.construction.mutate(mutation).await;
            (Self { construction }, outcome)
        }

        async fn absorb(self, diff: Self::Diff) -> protocol::MutationApplyResult<Self> {
            self.construction.absorb(diff).await.map(|construction| Self { construction })
        }

        async fn build(self) -> Result<Self::Snapshot, Vec<dsl::Diagnostic>> {
            self.construction.build().await
        }
    }

    impl<Spec: DerivedArtifactSpec> std::ops::Deref for DerivedArtifactBuilder<Spec> {
        type Target = Spec::Construction;

        fn deref(&self) -> &Self::Target {
            &self.construction
        }
    }

    impl<Spec: DerivedArtifactSpec> std::ops::DerefMut for DerivedArtifactBuilder<Spec> {
        fn deref_mut(&mut self) -> &mut Self::Target {
            &mut self.construction
        }
    }

    /// 🧐️ Codec-backed analyzer derived from the artifact snapshot and dialect coordinate.
    pub struct DerivedArtifactAnalyzer<Spec: DerivedArtifactSpec>(std::marker::PhantomData<Spec>);

    impl<Spec: DerivedArtifactSpec> ArtifactAnalyzer for DerivedArtifactAnalyzer<Spec> {
        type Parts = <Spec::Analysis as ArtifactAnalysis>::Parts;
        const DIALECT: Dialect = <Spec::Analysis as ArtifactAnalysis>::DIALECT;

        async fn sniff(source: &AnalyzeSource<'_>) -> IoConfidence {
            <Spec::Analysis as ArtifactAnalysis>::sniff(source).await
        }

        async fn analyze(sources: &[AnalyzeSource<'_>]) -> Analysis<Self::Parts> {
            <Spec::Analysis as ArtifactAnalysis>::analyze(sources).await
        }
    }

    /// 🎹️ Composer derived from native snapshot codecs plus directed foreign IO hooks — and, when
    /// `Spec::Children` declares real slots (UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM C1, Task 5), from
    /// this artifact's own composed children too. Living HERE (rather than duplicated per macro arm
    /// in `derive_artifact_facets!`) means every `DerivedArtifactSpec` — hand-written or
    /// macro-generated — gets child-slot-aware `reads()`/`compose()` automatically, for free, the
    /// moment its `Children` associated type names real slots.
    pub struct DerivedArtifactComposer<Spec: DerivedArtifactSpec>(std::marker::PhantomData<Spec>);

    impl<Spec: DerivedArtifactSpec> ArtifactComposer for DerivedArtifactComposer<Spec> {
        type Snapshot = Spec::Snapshot;
        const WRITES: Dialect = <Spec::Composition as ArtifactComposition>::WRITES;

        /// 🪆️ `Spec::Composition`'s own native/foreign reads, UNION each child slot's kind as an
        /// unconstrained-standard/unconstrained-subset `Dialect` (`StandardId("*")`/`SubsetId::ANY`
        /// — a child slot names only a `kind`, per `ChildSlotSpec.kind: &'static str`, never a
        /// specific standard/subset, so "any standard, any subset of this kind" is the literal
        /// reading of "this slot accepts the kind's dialect family").
        ///
        /// `ArtifactComposer::reads()`'s signature is fixed to `&'static [Dialect]` by the
        /// pre-existing (non-composition) trait, while `Spec::Children::slots()` is only knowable at
        /// runtime (a trait associated fn call, not a `const`) — so the union must be computed once
        /// and leaked into a `'static` lifetime rather than built as a `const`.
        ///
        /// ⚠️ Memoized in a `TypeId`-keyed table, NOT in a function-local `static`: a `static`
        /// declared inside a generic function is NOT monomorphized per type parameter — Rust gives
        /// every instantiation of `reads()` the SAME storage. With a plain `OnceLock` there, the
        /// first artifact kind to call `reads()` anywhere in the process would win and hand its
        /// answer to every other artifact kind forever (a composing artifact silently reporting a
        /// leaf's empty reads, or vice versa, depending purely on call order).
        ///
        /// A leaf `Spec::Children = NoChildren<_>` (`slots()` = `&[]`) still degrades to exactly
        /// `Spec::Composition::reads()`.
        async fn reads() -> &'static [Dialect] {
            static UNIONS: std::sync::OnceLock<std::sync::Mutex<HashMap<std::any::TypeId, &'static [Dialect]>>> = std::sync::OnceLock::new();
            let unions = UNIONS.get_or_init(|| std::sync::Mutex::new(HashMap::new()));
            let key = std::any::TypeId::of::<Spec>();
            let composition_reads = <Spec::Composition as ArtifactComposition>::reads().await;
            let child_slots = <Spec::Children as ArtifactChildren>::slots().await;
            let mut unions = unions.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
            *unions.entry(key).or_insert_with(|| {
                let mut reads: Vec<Dialect> = composition_reads.to_vec();
                for slot in child_slots {
                    reads.push(Dialect { artifact_kind: slot.kind, standard: StandardId("*"), subset: SubsetId::ANY });
                }
                // 🎯️ Leaked deliberately: one small `Vec` per artifact-kind monomorphization, minted
                // once for the process lifetime — the `&'static [Dialect]` return type admits no
                // other option, and the count is bounded by the number of artifact kinds.
                Box::leak(reads.into_boxed_slice()) as &'static [Dialect]
            })
        }

        /// 🪆️ Routes through `Spec::Children::compose_from_children` when `Spec::Children` declares
        /// real slots AND every source's dialect kind matches one of them (never for a leaf artifact
        /// — `slots()` empty short-circuits straight to the unchanged `Spec::Composition::compose`
        /// path, so nothing about a non-composing artifact's behavior changes); falls through to
        /// `Spec::Composition::compose` otherwise (a mixed/foreign-dialect source set, or no
        /// declared slots at all).
        /// 🌀️ `io-async-signatures`: async signature — behaviourally unchanged; the composition it
        /// delegates to (`ArtifactComposition::compose`, `ArtifactChildren::compose_from_children`)
        /// stays synchronous by design (see the framework io module's `resolve_ready` doc comment).
        async fn compose(sources: &[ComposeSource<'_>]) -> Result<Composition<Self::Snapshot>, ComposeError> {
            let slots = <Spec::Children as ArtifactChildren>::slots().await;
            let all_child_sources = !slots.is_empty() && !sources.is_empty() && sources.iter().all(|source| slots.iter().any(|slot| slot.kind == source.dialect.artifact_kind));
            if all_child_sources {
                let parts: Vec<(ArtifactDialect, Vec<u8>)> = sources
                    .iter()
                    .map(|source| {
                        let bytes = match &source.payload {
                            AnalyzeSource::Binary(bytes) => bytes.to_vec(),
                            AnalyzeSource::Text(text) => text.as_bytes().to_vec(),
                        };
                        (ArtifactDialect::from(source.dialect), bytes)
                    })
                    .collect();
                let snapshot = <Spec::Children as ArtifactChildren>::compose_from_children(&parts).await?;
                return Ok(Composition { snapshot, confidence: IoConfidence::High, diagnostics: Vec::new() });
            }
            <Spec::Composition as ArtifactComposition>::compose(sources).await
        }
    }
    //#endregion 🧬️DerivedArtifactFacets

    /// 💡️ Read-side inference surface — one per artifact standard, sibling of `ArtifactAnalyzer`
    /// (not a widening of `ArtifactBuilder`: inference is read-only and cache-aware, unlike the
    /// authoring lifecycle `ArtifactBuilder` models). `infer`/`infer_cached` must stay
    /// observationally equal — `infer_cached`'s default is an honest passthrough for artifacts
    /// with no `InferredField`s yet (ticket 26/08/12/INTRODUCE-INFERENCE-SCHEMA-FAMILY-WITH-DEPENDENCY-AWARE-CACHING).
    pub trait ArtifactInferrer: Sized {
        type Snapshot;
        type Inference: protocol::Inference<Self::Snapshot>;

        async fn infer(snapshot: &Self::Snapshot) -> Self::Inference {
            <Self::Inference as protocol::Inference<Self::Snapshot>>::infer(snapshot).await
        }

        /// 🧠️ Cache-aware variant; the default passthrough ignores `cache`/`session` and just calls
        /// `infer` — override once the standard registers real `InferredField`s.
        async fn infer_cached(snapshot: &Self::Snapshot, cache: &mut store::InferenceCache, session: &mut store::InferenceSession) -> Self::Inference {
            let _ = (cache, session);
            Self::infer(snapshot).await
        }
    }
    //#endregion 🔖️ArtifactBuilder

    //#region 💡️ArtifactInferenceService
    /// 🪪️ Stable native identity and version contract for one executable artifact inference.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    pub struct ArtifactInferenceServiceMetadata {
        pub owner: &'static str,
        pub artifact_kind: &'static str,
        pub artifact_schema: &'static str,
        pub artifact_schema_version: u32,
        pub document_schema: &'static str,
        pub document_schema_version: u32,
        pub inference_schema: &'static str,
        pub inference_schema_version: u32,
        pub algorithm_version: u32,
        pub policy_version: u32,
    }

    /// ⚠️ Structured failure returned by a type-erased inference execution boundary.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct ArtifactInferenceExecutionError {
        pub code: &'static str,
        pub message: String,
    }

    // 🚫️async: E1 pure error constructor consumed pervasively by sync closures
    // (`.map_err`/`.ok_or_else`) — see R9.
    impl ArtifactInferenceExecutionError {
        pub fn new(code: &'static str, message: impl Into<String>) -> Self {
            Self { code, message: message.into() }
        }
    }

    impl std::fmt::Display for ArtifactInferenceExecutionError {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(formatter, "{}: {}", self.code, self.message)
        }
    }

    impl std::error::Error for ArtifactInferenceExecutionError {}

    /// 💡️ Complete, bounded native inference invocation.
    pub struct ArtifactInferenceExecutionRequest<'a> {
        pub policy: &'a [u8],
        pub budgets: &'a WireArtifactInferenceBudget,
        pub cancellation_id: &'a str,
        pub previous_state: Option<&'a [u8]>,
        pub requested_cache_mode: WireArtifactInferenceCacheMode,
        pub canonical_payload: &'a [u8],
        pub dependencies: &'a [(String, Vec<u8>)],
    }

    /// 💡️ Native inference facts that the wire boundary must preserve exactly.
    pub struct ArtifactInferenceExecution {
        pub canonical_payload: Vec<u8>,
        pub diagnostics: Vec<WireArtifactInferenceDiagnostic>,
        pub validity: String,
        pub quality: String,
        pub complete: bool,
        pub actual_cache_mode: WireArtifactInferenceCacheMode,
    }

    /// 💡️ Non-capturing bounded inference implementation.
    pub type ArtifactInference = for<'a> fn(&ArtifactInferenceExecutionRequest<'a>) -> Result<ArtifactInferenceExecution, ArtifactInferenceExecutionError>;

    /// 🧰️ Native type-erased bounded inference entry.
    #[derive(Clone, Copy)]
    pub struct ArtifactInferenceService {
        metadata: ArtifactInferenceServiceMetadata,
        infer: ArtifactInference,
    }

    impl std::fmt::Debug for ArtifactInferenceService {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter.debug_struct("ArtifactInferenceService").field("metadata", &self.metadata).finish_non_exhaustive()
        }
    }

    impl ArtifactInferenceService {
        pub const fn new(metadata: ArtifactInferenceServiceMetadata, infer: ArtifactInference) -> Self {
            Self { metadata, infer }
        }

        pub const fn metadata(&self) -> ArtifactInferenceServiceMetadata {
            self.metadata
        }

        /// 🧷️ Returns the capability identity of this service's actual request-aware executable.
        pub async fn executable_identity(&self) -> ArtifactExecutableIdentity {
            ArtifactExecutableIdentity(self.infer as usize)
        }

        pub async fn infer(&self, request: &ArtifactInferenceExecutionRequest<'_>) -> Result<ArtifactInferenceExecution, ArtifactInferenceExecutionError> {
            (self.infer)(request)
        }

        async fn identical_to(&self, other: &Self) -> bool {
            self.metadata == other.metadata && std::ptr::fn_addr_eq(self.infer, other.infer)
        }
    }

    /// 🔑️ Lookup key intentionally excludes owner and versions: there can be only one owner
    /// and one versioned implementation for an artifact-kind/inference-schema pair in a process.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    pub struct ArtifactInferenceServiceKey {
        pub artifact_kind: &'static str,
        pub inference_schema: &'static str,
    }

    impl From<ArtifactInferenceServiceMetadata> for ArtifactInferenceServiceKey {
        fn from(metadata: ArtifactInferenceServiceMetadata) -> Self {
            Self { artifact_kind: metadata.artifact_kind, inference_schema: metadata.inference_schema }
        }
    }

    /// 🚨️ Typed failure from the native inference-service registry.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub enum ArtifactInferenceRegistrationError {
        Conflict { key: ArtifactInferenceServiceKey, existing: ArtifactInferenceServiceMetadata, incoming: ArtifactInferenceServiceMetadata },
        Unavailable,
    }

    impl std::fmt::Display for ArtifactInferenceRegistrationError {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            match self {
                Self::Conflict { key, existing, incoming } => write!(formatter, "conflicting artifact inference registration for {}/{}: existing {:?}, incoming {:?}", key.artifact_kind, key.inference_schema, existing, incoming),
                Self::Unavailable => formatter.write_str("artifact inference registry is poisoned"),
            }
        }
    }

    impl std::error::Error for ArtifactInferenceRegistrationError {}

    /// 📚️ Deterministic process-local catalogue for executable native inferences.
    #[derive(Default)]
    pub struct ArtifactInferenceServiceRegistry {
        by_key: BTreeMap<ArtifactInferenceServiceKey, ArtifactInferenceService>,
    }

    impl ArtifactInferenceServiceRegistry {
        pub async fn new() -> Self {
            Self::default()
        }

        pub async fn register(&mut self, service: ArtifactInferenceService) -> Result<(), ArtifactInferenceRegistrationError> {
            let key = ArtifactInferenceServiceKey::from(service.metadata);
            if let Some(existing) = self.by_key.get(&key) {
                if existing.identical_to(&service).await {
                    return Ok(());
                }
                return Err(ArtifactInferenceRegistrationError::Conflict { key, existing: existing.metadata, incoming: service.metadata });
            }
            self.by_key.insert(key, service);
            Ok(())
        }

        pub async fn get(&self, artifact_kind: &str, inference_schema: &str) -> Option<&ArtifactInferenceService> {
            self.by_key.iter().find_map(|(key, service)| (key.artifact_kind == artifact_kind && key.inference_schema == inference_schema).then_some(service))
        }

        pub async fn metadata(&self) -> Vec<ArtifactInferenceServiceMetadata> {
            self.by_key.values().map(ArtifactInferenceService::metadata).collect()
        }

        pub async fn infer(&self, artifact_kind: &str, inference_schema: &str, request: &ArtifactInferenceExecutionRequest<'_>) -> Result<ArtifactInferenceExecution, ArtifactInferenceExecutionError> {
            let service = self.get(artifact_kind, inference_schema).await.ok_or_else(|| ArtifactInferenceExecutionError::new("artifact-inference.not-registered", format!("no native inference service for {artifact_kind}/{inference_schema}")))?;
            service.infer(request).await
        }
    }

    static ARTIFACT_INFERENCE_SERVICE_REGISTRY: std::sync::OnceLock<std::sync::RwLock<ArtifactInferenceServiceRegistry>> = std::sync::OnceLock::new();

    async fn artifact_inference_service_registry() -> &'static std::sync::RwLock<ArtifactInferenceServiceRegistry> {
        // 🌉️ `OnceLock::get_or_init`'s closure is sync — bridged via `resolve_ready`; `new()` is a
        // pure `Self::default()` with no real suspension.
        ARTIFACT_INFERENCE_SERVICE_REGISTRY.get_or_init(|| std::sync::RwLock::new(resolve_ready(ArtifactInferenceServiceRegistry::new())))
    }

    pub async fn register_artifact_inference_service(service: ArtifactInferenceService) -> Result<(), ArtifactInferenceRegistrationError> {
        artifact_inference_service_registry().await.write().map_err(|_| ArtifactInferenceRegistrationError::Unavailable)?.register(service).await
    }

    /// 🔬️ Verifies native inference services against the established registry without mutation.
    #[must_use]
    pub async fn preflight_artifact_inference_services(services: &[ArtifactInferenceService]) -> Result<(), ArtifactInferenceRegistrationError> {
        let mut proposed = ArtifactInferenceServiceRegistry::new().await;
        for service in services {
            proposed.register(*service).await?;
        }
        let registry = artifact_inference_service_registry().await.read().map_err(|_| ArtifactInferenceRegistrationError::Unavailable)?;
        for service in services {
            let key = ArtifactInferenceServiceKey::from(service.metadata());
            if let Some(existing) = registry.by_key.get(&key) {
                if !existing.identical_to(service).await {
                    return Err(ArtifactInferenceRegistrationError::Conflict { key, existing: existing.metadata(), incoming: service.metadata() });
                }
            }
        }
        Ok(())
    }

    /// 📌️ Registers native inference services only after the whole candidate set is conflict-free.
    #[must_use]
    pub async fn register_artifact_inference_services(services: Vec<ArtifactInferenceService>) -> Result<(), ArtifactInferenceRegistrationError> {
        preflight_artifact_inference_services(&services).await?;
        let mut registry = artifact_inference_service_registry().await.write().map_err(|_| ArtifactInferenceRegistrationError::Unavailable)?;
        for service in services {
            registry.register(service).await?;
        }
        Ok(())
    }

    pub async fn artifact_inference_service(artifact_kind: &str, inference_schema: &str) -> Result<Option<ArtifactInferenceService>, ArtifactInferenceExecutionError> {
        Ok(artifact_inference_service_registry().await.read().map_err(|_| ArtifactInferenceExecutionError::new("artifact-inference.unavailable", "artifact inference registry is poisoned"))?.get(artifact_kind, inference_schema).await.copied())
    }

    pub async fn list_artifact_inference_services() -> Result<Vec<ArtifactInferenceServiceMetadata>, ArtifactInferenceExecutionError> {
        Ok(artifact_inference_service_registry().await.read().map_err(|_| ArtifactInferenceExecutionError::new("artifact-inference.unavailable", "artifact inference registry is poisoned"))?.metadata().await)
    }

    /// 💡️ Runs one bounded native inference through its immutable request contract.
    pub async fn infer_artifact(artifact_kind: &str, inference_schema: &str, request: &ArtifactInferenceExecutionRequest<'_>) -> Result<ArtifactInferenceExecution, ArtifactInferenceExecutionError> {
        let service =
            artifact_inference_service(artifact_kind, inference_schema).await?.ok_or_else(|| ArtifactInferenceExecutionError::new("artifact-inference.not-registered", format!("no native inference service for {artifact_kind}/{inference_schema}")))?;
        service.infer(request).await
    }

    #[cfg(test)]
    mod artifact_inference_service_tests {
        use super::*;

        async fn echo(request: &ArtifactInferenceExecutionRequest<'_>) -> Result<ArtifactInferenceExecution, ArtifactInferenceExecutionError> {
            Ok(ArtifactInferenceExecution {
                canonical_payload: request.canonical_payload.to_vec(),
                diagnostics: Vec::new(),
                validity: "valid".into(),
                quality: "complete".into(),
                complete: true,
                actual_cache_mode: request.requested_cache_mode.clone(),
            })
        }

        async fn reject(_request: &ArtifactInferenceExecutionRequest<'_>) -> Result<ArtifactInferenceExecution, ArtifactInferenceExecutionError> {
            Err(ArtifactInferenceExecutionError::new("test.rejected", "rejected"))
        }

        async fn metadata(artifact_kind: &'static str, inference_schema: &'static str) -> ArtifactInferenceServiceMetadata {
            ArtifactInferenceServiceMetadata {
                owner: "test",
                artifact_kind,
                artifact_schema: artifact_kind,
                artifact_schema_version: 1,
                document_schema: "test.document",
                document_schema_version: 1,
                inference_schema,
                inference_schema_version: 1,
                algorithm_version: 1,
                policy_version: 1,
            }
        }

        #[semio_framework_async_macros::async_test]
        async fn artifact_inference_registry_is_order_independent_and_idempotent() {
            let alpha = ArtifactInferenceService::new(metadata("s.test.alpha", "s.test.alpha.inference"), echo);
            let beta = ArtifactInferenceService::new(metadata("s.test.beta", "s.test.beta.inference"), echo);
            let mut forward = ArtifactInferenceServiceRegistry::new();
            forward.register(alpha).unwrap();
            forward.register(beta).unwrap();
            forward.register(alpha).unwrap();
            let mut reverse = ArtifactInferenceServiceRegistry::new();
            reverse.register(beta).unwrap();
            reverse.register(alpha).unwrap();
            assert_eq!(forward.metadata(), reverse.metadata());
            let budget = WireArtifactInferenceBudget { allocation_bytes: 16, work_units: 1, recursion_depth: 1 };
            let request = ArtifactInferenceExecutionRequest { policy: &[], budgets: &budget, cancellation_id: "test", previous_state: None, requested_cache_mode: WireArtifactInferenceCacheMode::Cold, canonical_payload: b"pack", dependencies: &[] };
            assert_eq!(forward.infer("s.test.alpha", "s.test.alpha.inference", &request).unwrap().canonical_payload, b"pack");
        }

        #[semio_framework_async_macros::async_test]
        async fn artifact_inference_registry_rejects_any_conflicting_duplicate() {
            let identity = metadata("s.test.conflict", "s.test.conflict.inference");
            let first = ArtifactInferenceService::new(identity, echo);
            assert_eq!(first.executable_identity(), ArtifactInferenceService::new(identity, echo).executable_identity());
            assert_ne!(first.executable_identity(), ArtifactInferenceService::new(identity, reject).executable_identity());
            let mut changed_metadata = metadata("s.test.conflict", "s.test.conflict.inference");
            changed_metadata.algorithm_version = 2;
            let mut registry = ArtifactInferenceServiceRegistry::new();
            registry.register(first).unwrap();
            let executable_error = registry.register(ArtifactInferenceService::new(identity, reject)).unwrap_err();
            let ArtifactInferenceRegistrationError::Conflict { existing, incoming, .. } = executable_error else {
                panic!("in-memory registry must report a registration conflict");
            };
            assert_eq!(existing, incoming);
            let error = registry.register(ArtifactInferenceService::new(changed_metadata, reject)).unwrap_err();
            let ArtifactInferenceRegistrationError::Conflict { key, existing, incoming } = error else {
                panic!("in-memory registry must report a registration conflict");
            };
            assert_eq!(key.artifact_kind, "s.test.conflict");
            assert_eq!(existing.algorithm_version, 1);
            assert_eq!(incoming.algorithm_version, 2);
        }
    }
    //#endregion 💡️ArtifactInferenceService

