    /// 📌️ One unique, externally addressable identity owned by a capability.
    #[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub struct ArtifactIdentityClaim {
        namespace: ArtifactIdentityNamespace,
        value: String,
    }

    impl ArtifactIdentityClaim {
        /// 🏗️ Creates a non-empty claim; caller-selectable namespaces keep this contract open.
        pub async fn new(namespace: ArtifactIdentityNamespace, value: impl Into<String>) -> Result<Self, ArtifactDefinitionError> {
            let value = value.into();
            if value.trim().is_empty() {
                return Err(ArtifactDefinitionError::new("artifact-definition.claim", "identity claim values must be non-empty"));
            }
            Ok(Self { namespace, value })
        }

        /// 🏷️ Returns the claim namespace.
        pub async fn namespace(&self) -> &ArtifactIdentityNamespace {
            &self.namespace
        }

        /// 🧭️ Returns the exact identity value; MIME and extension values are deliberately not rewritten.
        pub async fn value(&self) -> &str {
            &self.value
        }
    }

    /// 🌐️ Explicit locale identity. There is intentionally no default locale.
    #[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub struct ArtifactLocale(String);

    impl ArtifactLocale {
        /// 🏗️ Parses a lower-case BCP-47-like locale tag.
        pub async fn parse(value: impl Into<String>) -> Result<Self, ArtifactDefinitionError> {
            let value = value.into();
            if value.is_empty() || value.starts_with('-') || value.ends_with('-') || value.contains("--") || !value.bytes().all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-') {
                return Err(ArtifactDefinitionError::new("artifact-definition.locale", format!("locale {value:?} must be an explicit lower-case BCP-47-like tag")));
            }
            Ok(Self(value))
        }

        /// 🧭️ Returns the explicit locale tag.
        pub async fn as_str(&self) -> &str {
            &self.0
        }
    }

    /// 🗺️ Localized descriptor text for exactly one explicit locale.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct ArtifactLocalization {
        locale: ArtifactLocale,
        text: String,
    }

    impl ArtifactLocalization {
        /// 🏗️ Creates localized text. Locale is mandatory and text must be non-empty.
        pub async fn new(locale: ArtifactLocale, text: impl Into<String>) -> Result<Self, ArtifactDefinitionError> {
            let text = text.into();
            if text.trim().is_empty() {
                return Err(ArtifactDefinitionError::new("artifact-definition.localization", "localized text must be non-empty"));
            }
            Ok(Self { locale, text })
        }

        /// 🌐️ Returns the explicitly declared locale.
        pub async fn locale(&self) -> &ArtifactLocale {
            &self.locale
        }

        /// 📝 Returns localized text.
        pub async fn text(&self) -> &str {
            &self.text
        }
    }

    /// 🧩️ One extension-owned capability and its conflict-checked external identities.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct ArtifactCapability {
        identity: ArtifactIdentity,
        kind: ArtifactCapabilityKind,
        descriptor: Vec<u8>,
        executable_identity: Option<ArtifactExecutableIdentity>,
        claims: Vec<ArtifactIdentityClaim>,
        localizations: Vec<ArtifactLocalization>,
    }

    /// ⚙️ Stable process-local identity of a non-capturing capability executable.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub struct ArtifactExecutableIdentity(usize);

    impl ArtifactExecutableIdentity {
        /// 🧷️ Captures executable identity without exposing a runtime dependency type.
        pub async fn from_function(function: fn()) -> Self {
            Self(function as usize)
        }

        /// 🧬️ Captures an actual typed function pointer erased to its process-local code address.
        pub async fn from_function_pointer(function: *const ()) -> Self {
            Self(function as usize)
        }
    }

    impl ArtifactCapability {
        /// 🏗️ Constructs a capability at a full hierarchical identity.
        pub async fn new(identity: ArtifactIdentity, kind: ArtifactCapabilityKind) -> Self {
            Self { identity, kind, descriptor: Vec::new(), executable_identity: None, claims: Vec::new(), localizations: Vec::new() }
        }

        /// 🧾️ Attaches the canonical byte descriptor whose exact bytes participate in idempotence.
        pub async fn descriptor(mut self, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let descriptor = descriptor.into();
            if descriptor.is_empty() {
                return Err(ArtifactDefinitionError::new("artifact-definition.descriptor", format!("capability {} has an empty descriptor", self.identity)));
            }
            self.descriptor = descriptor;
            Ok(self)
        }

        /// ⚙️ Attaches the non-capturing executable identity whose exact value participates in idempotence.
        pub async fn executable(mut self, identity: ArtifactExecutableIdentity) -> Self {
            self.executable_identity = Some(identity);
            self
        }

        /// 📌️ Adds an exclusive external identity claim.
        pub async fn claim(mut self, claim: ArtifactIdentityClaim) -> Result<Self, ArtifactDefinitionError> {
            if self.claims.contains(&claim) {
                return Err(ArtifactDefinitionError::new("artifact-definition.duplicate-claim", format!("capability {} repeats {}:{}", self.identity, claim.namespace.as_str().await, claim.value)));
            }
            self.claims.push(claim);
            self.claims.sort();
            Ok(self)
        }

        /// 🗺️ Adds localized text. An explicit locale can occur at most once per capability.
        pub async fn localization(mut self, localization: ArtifactLocalization) -> Result<Self, ArtifactDefinitionError> {
            if self.localizations.iter().any(|existing| existing.locale == localization.locale) {
                return Err(ArtifactDefinitionError::new("artifact-definition.duplicate-locale", format!("capability {} repeats locale {}", self.identity, localization.locale.as_str().await)));
            }
            self.localizations.push(localization);
            self.localizations.sort_by(|left, right| left.locale.cmp(&right.locale));
            Ok(self)
        }

        /// 🪪️ Returns the hierarchical capability identity.
        // 🚫️async: E1 pure accessor consumed by sync iterator-adapter closures (`.filter(|c| ...)`
        // in `capabilities_of`/`standards`/etc. below, whose `impl Iterator` return type admits no
        // suspension point) — see R9.
        pub fn identity(&self) -> &ArtifactIdentity {
            &self.identity
        }

        /// 🏷️ Returns the open-ended capability category.
        // 🚫️async: E1 pure accessor — see `identity`'s own comment above.
        pub fn kind(&self) -> &ArtifactCapabilityKind {
            &self.kind
        }

        /// 🧾️ Returns the exact canonical descriptor bytes.
        pub async fn descriptor_bytes(&self) -> &[u8] {
            &self.descriptor
        }

        /// ⚙️ Returns the optional executable identity.
        pub async fn executable_identity(&self) -> Option<ArtifactExecutableIdentity> {
            self.executable_identity
        }

        /// 📌️ Returns deterministically ordered external identity claims.
        pub async fn claims(&self) -> &[ArtifactIdentityClaim] {
            &self.claims
        }

        /// 🗺️ Returns deterministically ordered localized descriptor text.
        pub async fn localizations(&self) -> &[ArtifactLocalization] {
            &self.localizations
        }
    }

    /// 🗿️ Schema-owned, plural declarative contract for one artifact family or standard profile.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct ArtifactDefinition {
        identity: ArtifactIdentity,
        capabilities: BTreeMap<ArtifactIdentity, ArtifactCapability>,
    }

    impl ArtifactDefinition {
        /// 🧾️ Starts the one authoritative definition for a canonical stdio artifact.
        pub async fn stdio(artifact: impl AsRef<str>) -> Result<Self, ArtifactDefinitionError> {
            Ok(Self::new(ArtifactIdentity::stdio_artifact(artifact).await?).await)
        }

        /// 🏗️ Starts an empty definition and claims its artifact identity.
        pub async fn new(identity: ArtifactIdentity) -> Self {
            Self { identity, capabilities: BTreeMap::new() }
        }

        /// 🪪️ Returns the definition's hierarchical artifact identity.
        pub async fn identity(&self) -> &ArtifactIdentity {
            &self.identity
        }

        /// 🧩️ Adds one capability. Its identity must live below this definition's identity.
        pub async fn capability(mut self, capability: ArtifactCapability) -> Result<Self, ArtifactDefinitionError> {
            if !capability.identity.is_within(&self.identity).await || capability.identity == self.identity {
                return Err(ArtifactDefinitionError::new("artifact-definition.capability-owner", format!("capability {} is not a descendant of artifact {}", capability.identity, self.identity)));
            }
            if self.capabilities.insert(capability.identity.clone(), capability).is_some() {
                return Err(ArtifactDefinitionError::new("artifact-definition.duplicate-capability", "capability identity is already declared"));
            }
            Ok(self)
        }

        /// 🏅️ Declares a standard leaf in this artifact's plural definition.
        pub async fn standard(self, revision: impl AsRef<str>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let identity = self.identity.standard(revision).await?;
            self.stdio_capability(identity, ArtifactCapabilityKind::standard().await, descriptor).await
        }

        /// 🪆️ Declares a profile leaf in this artifact's plural definition.
        pub async fn profile(self, revision: impl AsRef<str>, profile: impl AsRef<str>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let identity = self.identity.standard(revision).await?.profile(profile).await?;
            self.stdio_capability(identity, ArtifactCapabilityKind::profile().await, descriptor).await
        }

        /// 🚪️ Declares a source-dialect leaf in this artifact's plural definition.
        pub async fn source_dialect(self, revision: impl AsRef<str>, dialect: impl AsRef<str>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let identity = self.identity.standard(revision).await?.source_dialect(dialect).await?;
            self.stdio_capability(identity, ArtifactCapabilityKind::source_dialect().await, descriptor).await
        }

        /// 🎭️ Declares a representation leaf, optionally claiming its MIME identity.
        pub async fn representation(self, revision: impl AsRef<str>, representation: impl AsRef<str>, mime: Option<ArtifactMime>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let identity = self.identity.standard(revision).await?.representation(representation).await?;
            let capability = match mime {
                Some(mime) => {
                    let claim = ArtifactIdentityClaim::new(ArtifactIdentityNamespace::mime().await, mime.as_str()).await?;
                    ArtifactCapability::new(identity.clone(), ArtifactCapabilityKind::representation().await).await.claim(claim).await?
                }
                None => ArtifactCapability::new(identity, ArtifactCapabilityKind::representation().await).await,
            }
            .await.descriptor(descriptor)?;
            self.capability(capability).await
        }

        /// 🗜️ Declares a codec leaf in this artifact's plural definition.
        pub async fn codec(self, revision: impl AsRef<str>, codec: impl AsRef<str>, version: impl AsRef<str>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let identity = self.identity.standard(revision).await?.codec(codec, version).await?;
            self.stdio_capability(identity, ArtifactCapabilityKind::codec().await, descriptor).await
        }

        /// 🧬️ Declares a semantic mutation leaf in this artifact's plural definition.
        pub async fn mutation(self, command: impl AsRef<str>, version: impl AsRef<str>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let identity = self.identity.mutation(command, version).await?;
            self.stdio_capability(identity, ArtifactCapabilityKind::mutation().await, descriptor).await
        }

        /// 💡️ Declares an atomic inference leaf in this artifact's plural definition.
        pub async fn inference(self, semantic_slug: impl AsRef<str>, version: impl AsRef<str>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let identity = self.identity.inference(semantic_slug, version).await?;
            self.stdio_capability(identity, ArtifactCapabilityKind::inference().await, descriptor).await
        }

        /// 📦️ Declares an open resource-policy leaf in this artifact's plural definition.
        pub async fn resource(self, name: impl AsRef<str>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let identity = self.identity.child("resource").await?.child(name.as_ref()).await?;
            self.stdio_capability(identity, ArtifactCapabilityKind::resource().await, descriptor).await
        }

        /// 🗺️ Declares an explicit locale leaf in this artifact's plural definition.
        pub async fn localization(self, locale: ArtifactLocale, text: impl Into<String>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let capability = ArtifactCapability::new(self.identity.child("localization").await?.child(locale.as_str().await).await?, ArtifactCapabilityKind::localization().await).await.localization(ArtifactLocalization::new(locale, text).await?).await?.descriptor(descriptor).await?;
            self.capability(capability).await
        }

        /// ✅️ Declares a conformance-suite leaf in this artifact's plural definition.
        pub async fn conformance_suite(self, name: impl AsRef<str>, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            let identity = self.identity.child("conformance-suite").await?.child(name.as_ref()).await?;
            self.stdio_capability(identity, ArtifactCapabilityKind::conformance_suite().await, descriptor).await
        }

        /// 📚️ Returns capabilities in stable hierarchical order.
        // 🚫️async: E1 pure accessor — `impl Iterator` return type admits no suspension point,
        // and every sibling below chains a sync `.filter()` off it — see R9.
        pub fn capabilities(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities.values()
        }

        /// 🔐️ Requires one exact immutable capability before runtime registration.
        pub async fn require_declared_capability(&self, kind: &ArtifactCapabilityKind, id: &ArtifactIdentity, claims: &[ArtifactIdentityClaim], descriptor: Option<&[u8]>) -> Result<&ArtifactCapability, ArtifactDefinitionError> {
            let capability = self.capabilities.get(id).ok_or_else(|| ArtifactDefinitionError::new("artifact-definition.runtime-capability", format!("runtime registration names undeclared capability {id}")))?;
            if capability.kind != *kind {
                return Err(ArtifactDefinitionError::new("artifact-definition.runtime-category", format!("runtime registration for {id} requires {}, declared {}", kind.as_str(), capability.kind.as_str())));
            }
            let mut claims = claims.to_vec();
            claims.sort();
            if capability.claims != claims {
                return Err(ArtifactDefinitionError::new("artifact-definition.runtime-claims", format!("runtime registration claims do not exactly match {id}")));
            }
            if let Some(descriptor) = descriptor {
                if capability.descriptor_bytes().await != descriptor {
                    return Err(ArtifactDefinitionError::new("artifact-definition.runtime-descriptor", format!("runtime descriptor does not exactly match {id}")));
                }
            }
            Ok(capability)
        }

        /// 🧩️ Returns capabilities belonging to one open-ended category in stable identity order.
        // 🚫️async: E1 pure filter — `impl Iterator` return type admits no suspension point — see R9.
        pub fn capabilities_of<'a>(&'a self, kind: &'a ArtifactCapabilityKind) -> impl Iterator<Item = &'a ArtifactCapability> {
            self.capabilities().filter(move |capability| capability.kind() == kind)
        }

        /// 🏅️ Returns every standard leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn standards(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "standard")
        }

        /// 🪆️ Returns every profile leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn profiles(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "profile")
        }

        /// 🚪️ Returns every source-dialect leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn source_dialects(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "source-dialect")
        }

        /// 🎭️ Returns every representation leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn representations(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "representation")
        }

        /// 🗜️ Returns every codec leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn codecs(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "codec")
        }

        /// 🧬️ Returns every mutation leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn mutations(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "mutation")
        }

        /// 💡️ Returns every inference leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn inferences(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "inference")
        }

        /// 📦️ Returns every resource-policy leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn resources(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "resource")
        }

        /// 🗺️ Returns every localization leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn localizations(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "localization")
        }

        /// ✅️ Returns every conformance-suite leaf in stable identity order.
        // 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn conformance_suites(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "conformance-suite")
        }

        /// 🛡️ Validates identity ownership and all claims before registration mutates a registry.
        pub async fn validate(&self) -> Result<(), ArtifactDefinitionError> {
            let mut claims = BTreeMap::<ArtifactIdentityClaim, ArtifactIdentity>::new();
            for capability in self.capabilities() {
                if !capability.identity.is_within(&self.identity).await || capability.identity == self.identity {
                    return Err(ArtifactDefinitionError::new("artifact-definition.capability-owner", format!("capability {} is not a descendant of artifact {}", capability.identity, self.identity)));
                }
                if capability.descriptor.is_empty() {
                    return Err(ArtifactDefinitionError::new("artifact-definition.descriptor", format!("capability {} has no immutable descriptor", capability.identity)));
                }
                self.validate_capability_identity(capability).await?;
                for claim in capability.claims() {
                    if let Some(previous) = claims.insert(claim.clone(), capability.identity.clone()) {
                        return Err(ArtifactDefinitionError::new("artifact-definition.duplicate-claim", format!("{}:{} is claimed by both {} and {}", claim.namespace.as_str(), claim.value, previous, capability.identity)));
                    }
                }
            }
            Ok(())
        }

        async fn validate_capability_identity(&self, capability: &ArtifactCapability) -> Result<(), ArtifactDefinitionError> {
            if !self.identity.is_stdio_artifact().await {
                return Ok(());
            }
            let segments = capability.identity.segments().await;
            let category = capability.kind.as_str().await;
            let valid = match category {
                "standard" => segments.len() == 5 && segments[3] == "standard",
                "profile" => segments.len() == 7 && segments[3] == "standard" && segments[5] == "profile",
                "source-dialect" => segments.len() == 7 && segments[3] == "standard" && segments[5] == "dialect",
                "representation" => segments.len() == 7 && segments[3] == "standard" && segments[5] == "representation",
                "codec" => segments.len() == 8 && segments[3] == "standard" && segments[5] == "codec" && ArtifactIdentity::version(&segments[7]).await.is_ok(),
                "mutation" => segments.len() == 6 && segments[3] == "mutation" && ArtifactIdentity::version(&segments[5]).await.is_ok(),
                "inference" => segments.len() == 6 && segments[3] == "inference" && ArtifactIdentity::version(&segments[5]).await.is_ok(),
                "schema" => segments.len() >= 5 && segments[3] == "schema",
                "extension" => segments.len() >= 5 && segments[3] == "extension",
                "grammar" => segments.len() >= 5 && segments[3] == "grammar",
                "composer" => segments.len() >= 5 && segments[3] == "composer",
                "subset-validator" => segments.len() >= 5 && segments[3] == "subset-validator",
                "resource" => segments.len() >= 5 && segments[3] == "resource",
                "localization" => segments.len() == 5 && segments[3] == "localization",
                "conformance-suite" => segments.len() >= 5 && segments[3] == "conformance-suite",
                _ => true,
            };
            if valid {
                Ok(())
            } else {
                Err(ArtifactDefinitionError::new("artifact-definition.category-identity", format!("{} does not use the canonical {} identity grammar", capability.identity, category)))
            }
        }

        async fn stdio_capability(self, identity: ArtifactIdentity, kind: ArtifactCapabilityKind, descriptor: impl Into<Vec<u8>>) -> Result<Self, ArtifactDefinitionError> {
            self.capability(ArtifactCapability::new(identity, kind).await.descriptor(descriptor).await?).await
        }

        async fn identical_to(&self, other: &Self) -> bool {
            self.identity == other.identity && self.capabilities == other.capabilities
        }
    }

    /// 📮️ A validated optional representation MIME identity.
    #[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub struct ArtifactMime(String);

    impl ArtifactMime {
        /// 🏗️ Parses a lower-case ASCII `type/subtype` MIME identity.
        pub async fn parse(value: impl Into<String>) -> Result<Self, ArtifactDefinitionError> {
            let value = value.into();
            let mut segments = value.split('/');
            let Some(kind) = segments.next() else {
                return Err(ArtifactDefinitionError::new("artifact-definition.mime", "MIME must contain a type and subtype"));
            };
            let Some(subtype) = segments.next() else {
                return Err(ArtifactDefinitionError::new("artifact-definition.mime", "MIME must contain a type and subtype"));
            };
            if segments.next().is_some() || kind.is_empty() || subtype.is_empty() || !value.bytes().all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || matches!(byte, b'!' | b'#' | b'$' | b'&' | b'^' | b'_' | b'.' | b'+' | b'-' | b'/'))
            {
                return Err(ArtifactDefinitionError::new("artifact-definition.mime", format!("MIME {value:?} is not lower-case ASCII type/subtype")));
            }
            Ok(Self(value))
        }

        /// 🧭️ Returns the exact MIME identity.
        pub async fn as_str(&self) -> &str {
            &self.0
        }
    }

    /// 📚️ Deterministic, conflict-rejecting registry for independently assembled definitions.
    pub struct ArtifactDefinitionRegistry {
        definitions: BTreeMap<ArtifactIdentity, ArtifactDefinition>,
        claims: BTreeMap<ArtifactIdentityClaim, ArtifactIdentity>,
    }

    impl Default for ArtifactDefinitionRegistry {
        fn default() -> Self {
            Self::new()
        }
    }

    impl ArtifactDefinitionRegistry {
        /// 🏗️ Creates an empty artifact-definition registry.
        pub async fn new() -> Self {
            Self { definitions: BTreeMap::new(), claims: BTreeMap::new() }
        }

        /// 🛡️ Registers exactly one new definition or rejects it without partial mutation.
        pub async fn register(&mut self, definition: ArtifactDefinition) -> Result<(), ArtifactDefinitionError> {
            definition.validate().await?;
            let definition_identity = definition.identity().await;
            if let Some(existing) = self.definitions.get(definition_identity) {
                if existing.identical_to(&definition).await {
                    return Ok(());
                }
                return Err(ArtifactDefinitionError::new("artifact-definition.conflicting-artifact", format!("artifact {} has a different descriptor or executable identity", definition_identity)));
            }
            let artifact_claim = ArtifactIdentityClaim::new(ArtifactIdentityNamespace::artifact().await, definition_identity.as_str().await).await?;
            if let Some(previous) = self.claims.get(&artifact_claim) {
                return Err(ArtifactDefinitionError::new("artifact-definition.duplicate-artifact", format!("artifact {} is already registered by {}", definition_identity, previous)));
            }
            let mut additions = vec![(artifact_claim, definition_identity.clone())];
            for capability in definition.capabilities() {
                for claim in capability.claims().await {
                    if let Some(previous) = self.claims.get(claim) {
                        return Err(ArtifactDefinitionError::new("artifact-definition.conflicting-claim", format!("{}:{} is already registered by {}", claim.namespace.as_str().await, claim.value().await, previous)));
                    }
                    if let Some((_, previous)) = additions.iter().find(|(candidate, _)| candidate == claim) {
                        return Err(ArtifactDefinitionError::new("artifact-definition.duplicate-claim", format!("{}:{} is declared by both {} and {}", claim.namespace.as_str().await, claim.value().await, previous, capability.identity())));
                    }
                    additions.push((claim.clone(), capability.identity().clone()));
                }
            }
            for (claim, owner) in additions {
                self.claims.insert(claim, owner);
            }
            self.definitions.insert(definition.identity().clone(), definition);
            Ok(())
        }

        /// 🔎️ Resolves a definition by its artifact identity.
        pub async fn get(&self, identity: &ArtifactIdentity) -> Option<&ArtifactDefinition> {
            self.definitions.get(identity)
        }

        /// 🔢 Returns the number of registered artifact definitions.
        pub async fn len(&self) -> usize {
            self.definitions.len()
        }

        /// 📭️ Whether no definitions are registered.
        pub async fn is_empty(&self) -> bool {
            self.definitions.is_empty()
        }

        /// 🚶️ Walks definitions in deterministic hierarchical identity order.
        pub async fn definitions(&self) -> impl Iterator<Item = &ArtifactDefinition> {
            self.definitions.values()
        }
    }

    /// 🔐️ Locates the one immutable typed capability whose complete claim set authorizes a runtime facet.
    async fn require_declared_capability_or_record(definition: &ArtifactDefinition, definition_error: &mut Option<ArtifactDefinitionError>, kind: ArtifactCapabilityKind, claims: Result<Vec<ArtifactIdentityClaim>, ArtifactDefinitionError>) {
        if definition_error.is_some() {
            return;
        }
        let result: Result<(), ArtifactDefinitionError> = async {
            let mut claims = claims?;
            claims.sort();
            let capability = definition
                .capabilities_of(&kind)
                .find(|capability| capability.claims() == claims)
                .ok_or_else(|| ArtifactDefinitionError::new("artifact-definition.runtime-capability", format!("no declared {} capability owns the runtime claims", kind.as_str())))?;
            definition.require_declared_capability(&kind, capability.identity(), &claims, None).await.map(|_| ())
        }.await;
        if let Err(error) = result {
            *definition_error = Some(error);
        }
    }
    //#endregion 🧾️ArtifactDefinition

    //#region 🔖️ArtifactDeclaration
    /// 🔖️ Everything an artifact declares as data for `PluginBuilder::try_build()` — see
    /// `.🦑️repo/🎫️tickets/26/08/12/ARTIFACTS-ONLY-PLUGIN-ARCHITECTURE/📓️w1-mechanism-design.md`. Every
    /// field mirrors exactly one global registration function reachable from plugin code (census:
    /// `📓️w0-d-sdk-surface.md` §6); the app-scoped `register_app_schema_descriptor` has no field
    /// here because it belongs to `.document_app`, while flow extensions use plugin-level
    /// `FlowExtensionDeclaration` rather than a setup registrar. Built
    /// only through `ArtifactDeclaration::builder(definition)`, a consuming typestate builder mirroring
    /// `PluginBuilder`'s own shape, so a declaration missing its mandatory `schema` is a compile
    /// error rather than a runtime panic. Every field is module-private — a plugin crate can
    /// describe a declaration through the builder's methods but never read or hand-assemble one;
    /// only the transactional assembly plan ever walks it.
    pub struct ArtifactDeclaration {
        kind: String,
        schemas: Vec<::semio_framework_schema::ArtifactSchemaDescriptor>,
        inferences: Vec<::semio_framework_schema::ArtifactInferenceDescriptor>,
        inference_services: Vec<ArtifactInferenceService>,
        composers: Vec<&'static ComposerEntry>,
        formats: Vec<semio_framework::FormatDescriptor>,
        subset_validators: Vec<&'static SubsetValidatorEntry>,
        languages: Vec<&'static dsl::LanguageSpec>,
        document_codecs: Vec<DocumentCodecSpec>,
        migrations: Vec<store::DialectMigration>,
        // 🧒️🔗️ Pulled from `<Snapshot as ArtifactCompositionFields>::{child_slots,link_slots}` via
        // `.composition::<Snapshot>()` — never settable directly (UCAS review, 2026-08-12): the
        // derive-emitted trait impl IS the truth, so a hand-written list would be unwritable rather
        // than merely discouraged. No registration function consumes these yet (UCAS's composition
        // runtime reads `ArtifactCompositionFields` straight off the snapshot type on demand); they
        // are captured here so the declaration is a complete, single-source manifest of the
        // artifact's shape, not because `register_all` calls anything with them today.
        #[allow(dead_code, reason = "manifest-completeness capture, no reader yet — see comment above")]
        child_slots: &'static [::semio_framework_schema::ChildSlotSpec],
        #[allow(dead_code, reason = "manifest-completeness capture, no reader yet — see comment above")]
        link_slots: &'static [::semio_framework_schema::LinkSlotSpec],
        capabilities: Vec<CapabilityRequirement>,
        definition: ArtifactDefinition,
        definition_error: Option<ArtifactDefinitionError>,
    }

    /// 🧾️ One exact immutable capability claim-set required by a declared runtime facet.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct ArtifactRuntimeCapabilityRequirement {
        kind: ArtifactCapabilityKind,
        claims: Vec<ArtifactIdentityClaim>,
    }

    impl ArtifactRuntimeCapabilityRequirement {
        async fn new(kind: ArtifactCapabilityKind, mut claims: Vec<ArtifactIdentityClaim>) -> Self {
            claims.sort();
            Self { kind, claims }
        }

        /// 🏷️ Returns the strict runtime capability category.
        pub async fn kind(&self) -> &ArtifactCapabilityKind {
            &self.kind
        }

        /// 🧷️ Returns the complete canonical claim set; partial matches are never valid.
        pub async fn claims(&self) -> &[ArtifactIdentityClaim] {
            &self.claims
        }
    }

    /// 🏷️ Declaration builder has a definition only — next call must be `.schema(...)`.
    pub struct NeedsSchema;
    /// ✅️ Declaration builder has a definition + `schema` — ready for every other facet plus `.try_build()`.
    pub struct DeclarationReady;

    /// 🏗️ Consuming typestate builder for [`ArtifactDeclaration`] — mirrors [`PluginBuilder`]'s own
    /// missing-mandatory-field-is-a-compile-error shape.
    pub struct ArtifactDeclarationBuilder<State> {
        kind: String,
        schemas: Vec<::semio_framework_schema::ArtifactSchemaDescriptor>,
        inferences: Vec<::semio_framework_schema::ArtifactInferenceDescriptor>,
        inference_services: Vec<ArtifactInferenceService>,
        composers: Vec<&'static ComposerEntry>,
        formats: Vec<semio_framework::FormatDescriptor>,
        subset_validators: Vec<&'static SubsetValidatorEntry>,
        languages: Vec<&'static dsl::LanguageSpec>,
        document_codecs: Vec<DocumentCodecSpec>,
        migrations: Vec<store::DialectMigration>,
        child_slots: &'static [::semio_framework_schema::ChildSlotSpec],
        link_slots: &'static [::semio_framework_schema::LinkSlotSpec],
        capabilities: Vec<CapabilityRequirement>,
        definition: ArtifactDefinition,
        definition_error: Option<ArtifactDefinitionError>,
        _state: std::marker::PhantomData<State>,
    }

    impl ArtifactDeclaration {
        /// 🪪️ Starts a declaration from its one authoritative artifact definition.
        pub async fn builder(definition: ArtifactDefinition) -> ArtifactDeclarationBuilder<NeedsSchema> {
            let kind = definition.identity().await.as_str().to_string();
            ArtifactDeclarationBuilder {
                kind,
                schemas: Vec::new(),
                inferences: Vec::new(),
                inference_services: Vec::new(),
                composers: Vec::new(),
                formats: Vec::new(),
                subset_validators: Vec::new(),
                languages: Vec::new(),
                document_codecs: Vec::new(),
                migrations: Vec::new(),
                child_slots: &[],
                link_slots: &[],
                capabilities: Vec::new(),
                definition,
                definition_error: None,
                _state: std::marker::PhantomData,
            }
        }
    }

    impl ArtifactDeclarationBuilder<NeedsSchema> {
        /// 🧬️ Sets the artifact's four-facet schema descriptor — mandatory, so this is the one call
        /// that unlocks every other declaration method.
        pub async fn schema(mut self, descriptor: ::semio_framework_schema::ArtifactSchemaDescriptor) -> ArtifactDeclarationBuilder<DeclarationReady> {
            require_declared_capability_or_record(&self.definition, &mut self.definition_error, ArtifactCapabilityKind::schema().await, ArtifactIdentityClaim::new(ArtifactIdentityNamespace::schema().await, descriptor.id).await.map(|claim| vec![claim]));
            ArtifactDeclarationBuilder {
                kind: self.kind,
                schemas: vec![descriptor],
                inferences: self.inferences,
                inference_services: self.inference_services,
                composers: self.composers,
                formats: self.formats,
                subset_validators: self.subset_validators,
                languages: self.languages,
                document_codecs: self.document_codecs,
                migrations: self.migrations,
                child_slots: self.child_slots,
                link_slots: self.link_slots,
                capabilities: self.capabilities,
                definition: self.definition,
                definition_error: self.definition_error,
                _state: std::marker::PhantomData,
            }
        }
    }

    impl ArtifactDeclarationBuilder<DeclarationReady> {
        /// 🧾️ Lists exact runtime capability rows without attempting plugin assembly.
        pub async fn runtime_capability_requirements(&self) -> Result<Vec<ArtifactRuntimeCapabilityRequirement>, ArtifactDefinitionError> {
            runtime_capability_requirements(&self.schemas, &self.inferences, &self.inference_services, &self.composers, &self.formats, &self.subset_validators, &self.languages, &self.document_codecs).await
        }

        /// 🧬️ Appends further schema descriptors for independently versioned standards or profiles.
        pub async fn schemas(mut self, items: impl IntoIterator<Item = ::semio_framework_schema::ArtifactSchemaDescriptor>) -> Self {
            for item in items {
                require_declared_capability_or_record(&self.definition, &mut self.definition_error, ArtifactCapabilityKind::schema().await, ArtifactIdentityClaim::new(ArtifactIdentityNamespace::schema().await, item.id).await.map(|claim| vec![claim]));
                self.schemas.push(item);
            }
            self
        }

        /// 💡️ Appends inference descriptors for transactional registration. Repeatable.
        pub async fn inferences(mut self, items: impl IntoIterator<Item = ::semio_framework_schema::ArtifactInferenceDescriptor>) -> Self {
            for item in items {
                require_declared_capability_or_record(&self.definition, &mut self.definition_error, ArtifactCapabilityKind::inference().await, ArtifactIdentityClaim::new(ArtifactIdentityNamespace::schema().await, item.id).await.map(|claim| vec![claim]));
                self.inferences.push(item);
            }
            self
        }

        /// 🧠️ Appends executable native inference services. Each service is ownership- and
        /// schema-checked against this declaration before deterministic registry insertion.
        pub async fn inference_services(mut self, items: impl IntoIterator<Item = ArtifactInferenceService>) -> Self {
            for service in items {
                let metadata = service.metadata();
                require_declared_capability_or_record(
                    &self.definition,
                    &mut self.definition_error,
                    ArtifactCapabilityKind::inference().await,
                    ArtifactIdentityClaim::new(ArtifactIdentityNamespace::schema().await, metadata.inference_schema).await.map(|claim| vec![claim]),
                );
                self.inference_services.push(service);
            }
            self
        }

        /// 🎹️ Appends this artifact's composer table for transactional registration.
        pub async fn composers(mut self, entries: &'static [ComposerEntry]) -> Self {
            for entry in entries {
                require_declared_capability_or_record(
                    &self.definition,
                    &mut self.definition_error,
                    ArtifactCapabilityKind::composer().await,
                    ArtifactIdentityClaim::new(ArtifactIdentityNamespace::dialect().await, ArtifactDialect::from(entry.writes).to_coordinate().await).await.map(|claim| vec![claim]),
                );
                self.composers.push(entry);
            }
            self
        }

        /// 🗂️ Appends format rows (`register_format_descriptors`).
        pub async fn formats(mut self, rows: impl IntoIterator<Item = semio_framework::FormatDescriptor>) -> Self {
            for row in rows {
                let mut claims = Vec::with_capacity(row.mimes.len() + row.extensions.len());
                let mut claim_error = None;
                for mime in row.mimes.iter() {
                    match ArtifactIdentityClaim::new(ArtifactIdentityNamespace::mime().await, mime.clone()).await {
                        Ok(claim) => claims.push(claim),
                        Err(error) => {
                            claim_error = Some(error);
                            break;
                        }
                    }
                }
                if claim_error.is_none() {
                    for extension in row.extensions.iter() {
                        match ArtifactIdentityClaim::new(ArtifactIdentityNamespace::extension().await, extension.clone()).await {
                            Ok(claim) => claims.push(claim),
                            Err(error) => {
                                claim_error = Some(error);
                                break;
                            }
                        }
                    }
                }
                let claims_result = match claim_error {
                    Some(error) => Err(error),
                    None => Ok(claims),
                };
                require_declared_capability_or_record(
                    &self.definition,
                    &mut self.definition_error,
                    ArtifactCapabilityKind::representation().await,
                    claims_result,
                );
                self.formats.push(row);
            }
            self
        }

        /// 🧾️ Appends this artifact's subset-validator table (`register_subset_validator`, one call per entry).
        pub async fn subset_validators(mut self, entries: &'static [SubsetValidatorEntry]) -> Self {
            for entry in entries {
                require_declared_capability_or_record(
                    &self.definition,
                    &mut self.definition_error,
                    ArtifactCapabilityKind::subset_validator().await,
                    ArtifactIdentityClaim::new(ArtifactIdentityNamespace::dialect().await, ArtifactDialect::from(entry.dialect).to_coordinate().await).await.map(|claim| vec![claim]),
                );
                self.subset_validators.push(entry);
            }
            self
        }

        /// 📖️ Appends this artifact's grammar table (`register_language`, one call per entry).
        pub async fn languages(mut self, specs: &'static [dsl::LanguageSpec]) -> Self {
            for spec in specs {
                require_declared_capability_or_record(&self.definition, &mut self.definition_error, ArtifactCapabilityKind::grammar().await, ArtifactIdentityClaim::new(ArtifactIdentityNamespace::grammar().await, spec.id).await.map(|claim| vec![claim]));
            }
            self.languages.extend(specs);
            self
        }

        /// 🗂️ Declares the document codec for one document-owning `ArtifactApp`
        /// (`register_document_codec_for_app::<A>`, keyed by `A::DOCUMENT_SCHEMA`). Repeatable:
        /// every schema-owned codec is retained and conflict-checked before runtime registration.
        pub async fn document_codec<A: ArtifactApp>(mut self) -> Self {
            let codec = DocumentCodecSpec::of::<A>().await;
            let namespace_codec = ArtifactIdentityNamespace::codec().await;
            let claims = match ArtifactIdentityClaim::new(namespace_codec, codec.schema.clone()).await {
                Ok(schema) => match ArtifactIdentityClaim::new(ArtifactIdentityNamespace::extension().await, codec.extension.clone()).await {
                    Ok(extension) => Ok(vec![schema, extension]),
                    Err(error) => Err(error),
                },
                Err(error) => Err(error),
            };
            require_declared_capability_or_record(
                &self.definition,
                &mut self.definition_error,
                ArtifactCapabilityKind::codec().await,
                claims,
            );
            self.document_codecs.push(codec);
            self
        }

        /// 🗂️ Sibling of `.document_codec::<A>()` for a library artifact with ZERO `ArtifactApp`s to
        /// bind to (ticket 26/08/12/ARTIFACTS-ONLY-PLUGIN-ARCHITECTURE W1d, gap A — see
        /// `📓️w1d-declaration-gaps-report.md`). `.document_codec::<A>()` is keyed off `A::DOCUMENT_SCHEMA`
        /// and calls `register_document_codec_for_app::<A>`, which requires a real `ArtifactApp`; a
        /// headless library plugin (energy's `EnergyModelSnapshot`/`EnergyModelMutation` is the
        /// motivating case) has no such type. Same bounds as `store::ArtifactCodec::of`; it appends
        /// to the same plural codec capability set as `.document_codec::<A>()`.
        pub async fn document_codec_bare<Snapshot, Mutation>(mut self, schema: impl Into<String>) -> Self
        where
            Snapshot: Clone + PartialEq + Serialize + DeserializeOwned + Send + store::ArtifactDsl + ArtifactPack + 'static,
            Mutation: ::protocol::Mutation<Snapshot> + PartialEq + Serialize + DeserializeOwned + Send + ::protocol::OpText + ::protocol::OpBinary + 'static,
        {
            let codec = DocumentCodecSpec::bare::<Snapshot, Mutation>(schema).await;
            let namespace_codec = ArtifactIdentityNamespace::codec().await;
            let claims = match ArtifactIdentityClaim::new(namespace_codec, codec.schema.clone()).await {
                Ok(schema) => match ArtifactIdentityClaim::new(ArtifactIdentityNamespace::extension().await, codec.extension.clone()).await {
                    Ok(extension) => Ok(vec![schema, extension]),
                    Err(error) => Err(error),
                },
                Err(error) => Err(error),
            };
            require_declared_capability_or_record(
                &self.definition,
                &mut self.definition_error,
                ArtifactCapabilityKind::codec().await,
                claims,
            );
            self.document_codecs.push(codec);
            self
        }

        /// 🧭️ Appends dialect migrations for transactional registration.
        pub async fn migrations(mut self, items: impl IntoIterator<Item = store::DialectMigration>) -> Self {
            self.migrations.extend(items);
            self
        }

        /// 🧒️🔗️ Pulls `child_slots`/`link_slots` from `<Snapshot as ArtifactCompositionFields>` — the
        /// ONLY way to set them (UCAS review, 2026-08-12: a hand-written list could silently disagree
        /// with the `#[derive(ArtifactSchema)]`-emitted impl the composition runtime actually reads,
        /// so there is deliberately no other setter).
        pub async fn composition<Snapshot: ::semio_framework_schema::ArtifactCompositionFields>(mut self) -> Self {
            self.child_slots = Snapshot::child_slots().await;
            self.link_slots = Snapshot::link_slots().await;
            self
        }

        /// 🔒️ Declares a capability requirement owned by this artifact (unioned into
        /// `PluginManifest.capabilities` at assembly time) — IO is artifact-owned, so an artifact
        /// that reads assets declares this on itself, not on the plugin.
        pub async fn capability(mut self, capability: CapabilityRequirement) -> Self {
            if !self.capabilities.contains(&capability) {
                self.capabilities.push(capability);
            }
            self
        }

        /// ✅️ Validates the declaration-local contract before assembly.
        pub async fn try_build(self) -> Result<ArtifactDeclaration, ArtifactDefinitionError> {
            if let Some(error) = self.definition_error {
                return Err(error);
            }
            Ok(ArtifactDeclaration {
                kind: self.kind,
                schemas: self.schemas,
                inferences: self.inferences,
                inference_services: self.inference_services,
                composers: self.composers,
                formats: self.formats,
                subset_validators: self.subset_validators,
                languages: self.languages,
                document_codecs: self.document_codecs,
                migrations: self.migrations,
                child_slots: self.child_slots,
                link_slots: self.link_slots,
                capabilities: self.capabilities,
                definition: self.definition,
                definition_error: None,
            })
        }
    }

    /// 🗂️ A monomorphized, non-capturing thunk pairing a `schema` string with the fn pointer that
    /// registers a document codec under it — lets `.document_codec::<A>()`/`.document_codec_bare()`
    /// store the registration as inert data instead of performing it immediately, matching every
    /// other declaration field's "described now, committed once by `PluginBuilder::try_build()`" contract. The
    /// `schema` sits alongside the thunk (not baked into it) because `bare`'s schema is a runtime
    /// `impl Into<String>`, not a type-level const like `A::DOCUMENT_SCHEMA` — a `fn()` thunk cannot
    /// close over it without capturing, which would break the "plain fn pointer" contract this type
    /// exists to keep.
    pub struct DocumentCodecSpec {
        schema: String,
        extension: &'static str,
        codec: fn(String) -> store::ArtifactCodec,
        app_id: &'static str,
        foreign: bool,
    }

    impl DocumentCodecSpec {
        async fn of<A: ArtifactApp>() -> Self {
            // 🚫️async: E4 fn-pointer slot — `DocumentCodecSpec.codec: fn(String) -> store::ArtifactCodec`
            // is a bare fn pointer; an `async fn` item's pointer type is unnameable. Bridged via
            // `resolve_ready` since `ArtifactCodec::of` only monomorphizes zero-sized bridge fns (no
            // real suspension) — see the framework io module's `resolve_ready` doc comment.
            fn codec<A: ArtifactApp>(schema: String) -> store::ArtifactCodec {
                resolve_ready(store::ArtifactCodec::of::<A::Snapshot, A::Mutation>(schema))
            }
            DocumentCodecSpec { schema: A::DOCUMENT_SCHEMA.to_string(), extension: <A::Snapshot as store::ArtifactDsl>::EXTENSION, codec: codec::<A>, app_id: A::APP_ID, foreign: false }
        }

        pub(crate) async fn foreign<A: ArtifactApp>(schema: impl Into<String>) -> Self {
            // 🚫️async: E4 fn-pointer slot — see `of`'s own comment above.
            fn codec<A: ArtifactApp>(schema: String) -> store::ArtifactCodec {
                resolve_ready(store::ArtifactCodec::of::<A::Snapshot, A::Mutation>(schema))
            }
            DocumentCodecSpec { schema: schema.into(), extension: <A::Snapshot as store::ArtifactDsl>::EXTENSION, codec: codec::<A>, app_id: A::APP_ID, foreign: true }
        }

        /// 🗂️ `of::<A>()`'s app-less sibling — see `.document_codec_bare()`'s own doc for why this
        /// exists. Registers straight against `store::register_document_codec`, bypassing
        /// `register_document_codec_for_app`'s `A::` indirection since there is no `A` to name.
        async fn bare<Snapshot, Mutation>(schema: impl Into<String>) -> Self
        where
            Snapshot: Clone + PartialEq + Serialize + DeserializeOwned + Send + store::ArtifactDsl + ArtifactPack + 'static,
            Mutation: ::protocol::Mutation<Snapshot> + PartialEq + Serialize + DeserializeOwned + Send + ::protocol::OpText + ::protocol::OpBinary + 'static,
        {
            // 🚫️async: E4 fn-pointer slot — see `of`'s own comment above.
            fn codec<Snapshot, Mutation>(schema: String) -> store::ArtifactCodec
            where
                Snapshot: Clone + PartialEq + Serialize + DeserializeOwned + Send + store::ArtifactDsl + ArtifactPack + 'static,
                Mutation: ::protocol::Mutation<Snapshot> + PartialEq + Serialize + DeserializeOwned + Send + ::protocol::OpText + ::protocol::OpBinary + 'static,
            {
                resolve_ready(store::ArtifactCodec::of::<Snapshot, Mutation>(schema))
            }
            DocumentCodecSpec { schema: schema.into(), extension: <Snapshot as store::ArtifactDsl>::EXTENSION, codec: codec::<Snapshot, Mutation>, app_id: "", foreign: false }
        }

        async fn codec(&self) -> store::ArtifactCodec {
            (self.codec)(self.schema.clone())
        }

        pub(crate) async fn preflight_foreign(&self, document_app_ids: &BTreeSet<&'static str>) -> Result<(), PluginAssemblyError> {
            if !self.foreign {
                return Ok(());
            }
            if self.schema.trim().is_empty() || self.extension.trim().is_empty() {
                return Err(PluginAssemblyError::new("plugin-assembly.foreign-document-codec-schema", "foreign document codecs require non-empty schema and extension"));
            }
            if !document_app_ids.contains(self.app_id) {
                return Err(PluginAssemblyError::new("plugin-assembly.foreign-document-codec-owner", format!("foreign document codec for app {:?} requires that app to be declared by this plugin", self.app_id)));
            }
            Ok(())
        }
    }

    async fn runtime_capability_requirements(
        schemas: &[::semio_framework_schema::ArtifactSchemaDescriptor],
        inferences: &[::semio_framework_schema::ArtifactInferenceDescriptor],
        inference_services: &[ArtifactInferenceService],
        composers: &[&'static ComposerEntry],
        formats: &[semio_framework::FormatDescriptor],
        subset_validators: &[&'static SubsetValidatorEntry],
        languages: &[&'static dsl::LanguageSpec],
        document_codecs: &[DocumentCodecSpec],
    ) -> Result<Vec<ArtifactRuntimeCapabilityRequirement>, ArtifactDefinitionError> {
        let mut rows = Vec::new();
        for schema in schemas {
            rows.push(ArtifactRuntimeCapabilityRequirement::new(ArtifactCapabilityKind::schema().await, vec![ArtifactIdentityClaim::new(ArtifactIdentityNamespace::schema().await, schema.id).await?]));
        }
        for inference in inferences {
            rows.push(ArtifactRuntimeCapabilityRequirement::new(ArtifactCapabilityKind::inference().await, vec![ArtifactIdentityClaim::new(ArtifactIdentityNamespace::schema().await, inference.id).await?]));
        }
        for service in inference_services {
            rows.push(ArtifactRuntimeCapabilityRequirement::new(ArtifactCapabilityKind::inference().await, vec![ArtifactIdentityClaim::new(ArtifactIdentityNamespace::schema().await, service.metadata().inference_schema).await?]));
        }
        for entry in composers {
            rows.push(ArtifactRuntimeCapabilityRequirement::new(ArtifactCapabilityKind::composer().await, vec![ArtifactIdentityClaim::new(ArtifactIdentityNamespace::dialect().await, ArtifactDialect::from(entry.writes).to_coordinate().await).await?]));
        }
        for row in formats {
            let mut claims = Vec::with_capacity(row.mimes.len() + row.extensions.len());
            for mime in row.mimes.iter() {
                claims.push(ArtifactIdentityClaim::new(ArtifactIdentityNamespace::mime().await, mime.clone()).await?);
            }
            for extension in row.extensions.iter() {
                claims.push(ArtifactIdentityClaim::new(ArtifactIdentityNamespace::extension().await, extension.clone()).await?);
            }
            rows.push(ArtifactRuntimeCapabilityRequirement::new(ArtifactCapabilityKind::representation().await, claims));
        }
        for entry in subset_validators {
            rows.push(ArtifactRuntimeCapabilityRequirement::new(
                ArtifactCapabilityKind::subset_validator().await,
                vec![ArtifactIdentityClaim::new(ArtifactIdentityNamespace::dialect().await, ArtifactDialect::from(entry.dialect).to_coordinate().await).await?],
            ));
        }
        for spec in languages {
            rows.push(ArtifactRuntimeCapabilityRequirement::new(ArtifactCapabilityKind::grammar().await, vec![ArtifactIdentityClaim::new(ArtifactIdentityNamespace::grammar().await, spec.id).await?]));
        }
        for codec in document_codecs {
            rows.push(ArtifactRuntimeCapabilityRequirement::new(
                ArtifactCapabilityKind::codec().await,
                vec![ArtifactIdentityClaim::new(ArtifactIdentityNamespace::codec().await, codec.schema.clone()).await?, ArtifactIdentityClaim::new(ArtifactIdentityNamespace::extension().await, codec.extension).await?],
            ));
        }
        Ok(rows)
    }

    impl ArtifactDeclaration {
        /// 📚️ Returns this declaration's one authoritative artifact definition.
        pub async fn definition(&self) -> &ArtifactDefinition {
            &self.definition
        }

        /// 🧾️ Lists every exact runtime capability required by this immutable declaration.
        pub async fn runtime_capability_requirements(&self) -> Result<Vec<ArtifactRuntimeCapabilityRequirement>, ArtifactDefinitionError> {
            runtime_capability_requirements(&self.schemas, &self.inferences, &self.inference_services, &self.composers, &self.formats, &self.subset_validators, &self.languages, &self.document_codecs).await
        }

        /// 🛡️ Inserts every attached definition into a caller-owned plugin registry. The caller
        /// owns the transaction boundary so independently declared artifacts are checked together
        /// before any runtime registration can mutate its legacy registry.
        pub(crate) async fn register_definitions(&self, registry: &mut ArtifactDefinitionRegistry) -> Result<(), ArtifactDefinitionError> {
            if let Some(error) = &self.definition_error {
                return Err(error.clone());
            }
            registry.register(self.definition.clone()).await?;
            Ok(())
        }

        /// 🛡️ Validates this declaration into one plugin-owned registry without side effects.
        pub(crate) async fn preflight(&self, plugin_id: &str, definitions: &mut ArtifactDefinitionRegistry) -> Result<(), PluginAssemblyError> {
            self.register_definitions(definitions).await.map_err(PluginAssemblyError::definition)?;
            if let Ok(canonical) = ArtifactKindId::parse(&self.kind).await {
                if canonical.plugin().await != plugin_id {
                    return Err(PluginAssemblyError::new("plugin-assembly.artifact-owner", format!("plugin {plugin_id:?} does not own artifact {:?}", self.kind)));
                }
            }
            for entry in &self.composers {
                if entry.writes.artifact_kind != self.kind && !entry.reads.iter().any(|dialect| dialect.artifact_kind == self.kind) {
                    return Err(PluginAssemblyError::new("plugin-assembly.composer-owner", format!("composer for {:?} neither reads nor writes that artifact", self.kind)));
                }
            }
            for entry in &self.subset_validators {
                if entry.dialect.artifact_kind != self.kind {
                    return Err(PluginAssemblyError::new("plugin-assembly.subset-owner", format!("subset validator for {:?} validates {}", self.kind, entry.dialect.artifact_kind)));
                }
            }
            for migration in &self.migrations {
                if migration.from.artifact_kind != self.kind || migration.to.artifact_kind != self.kind {
                    return Err(PluginAssemblyError::new("plugin-assembly.migration-owner", format!("migration for {:?} names {}→{}", self.kind, migration.from.artifact_kind, migration.to.artifact_kind)));
                }
            }
            for service in &self.inference_services {
                let metadata = service.metadata();
                if metadata.owner != plugin_id || metadata.artifact_kind != self.kind {
                    return Err(PluginAssemblyError::new("plugin-assembly.inference-owner", format!("inference service {:?}/{:?} does not belong to plugin {plugin_id:?} artifact {:?}", metadata.owner, metadata.artifact_kind, self.kind)));
                }
                if !self.schemas.iter().any(|schema| metadata.artifact_schema == schema.id) {
                    return Err(PluginAssemblyError::new("plugin-assembly.inference-schema", format!("inference service {:?} has no declared artifact schema", metadata.inference_schema)));
                }
                if !self.inferences.iter().any(|descriptor| descriptor.id == metadata.inference_schema) {
                    return Err(PluginAssemblyError::new("plugin-assembly.inference-descriptor", format!("inference service {:?} has no descriptor", metadata.inference_schema)));
                }
            }
            Ok(())
        }

        /// 🏗️ Adds this declaration's manifest capabilities after registration-plan commit.
        /// 🌀️ A plain `Iterator::fold` closure cannot `.await` (fixed sync `FnMut`, std API) —
        /// restructured into a for loop, same net effect.
        pub(crate) async fn apply_to<PA: PluginApp>(self, plugin: Plugin<PA>) -> Plugin<PA> {
            let mut plugin = plugin;
            for capability in self.capabilities {
                plugin = plugin.capability(capability).await;
            }
            plugin
        }
    }

    //#region 🧭️RuntimeContributions
    /// 🧷️ Typed mesh-to-document executable retained by the plugin runtime for a DWG bridge.
    pub type MeshDwgDocumentImporter = fn(&semio_framework::MeshData) -> Result<Value, String>;

    /// 🧷️ Typed document-to-SVG executable retained by the plugin runtime for 2D export.
    pub type TwoDSvgDocumentRenderer = fn(&Value) -> Result<(String, u32, u32), String>;

    /// 🧭️ The closed set of host-media contribution roles.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    pub enum HostMediaHandlerKind {
        MeshDwgBridge,
        TwoDSvgExport,
    }

    impl HostMediaHandlerKind {
        async fn as_str(self) -> &'static str {
            match self {
                Self::MeshDwgBridge => "mesh-dwg-bridge",
                Self::TwoDSvgExport => "2d-svg-export",
            }
        }
    }

    /// ⚙️ Complete process-local identity of a typed host-media executable.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    pub enum HostMediaExecutableIdentity {
        MeshDwgBridge(usize),
        TwoDSvgExport(usize),
    }

    /// 📋️ Immutable host-media descriptor visible to a runtime host.
    #[derive(Clone, Debug, PartialEq)]
    pub struct HostMediaHandlerDescriptor {
        pub id: String,
        pub owner: String,
        pub kind: HostMediaHandlerKind,
        pub artifact_kind: ArtifactKindSpec,
        pub document_schema: String,
        pub file_stem: Option<String>,
        pub executable_identity: HostMediaExecutableIdentity,
    }

    /// 🧾️ Descriptor-owned typed host-media contribution, frozen before any aggregate commit.
    #[derive(Clone, Debug)]
    pub struct HostMediaHandlerDeclaration {
        id: ArtifactIdentity,
        kind: HostMediaHandlerKind,
        artifact_kind: ArtifactKindSpec,
        document_schema: String,
        file_stem: Option<String>,
        executable: HostMediaExecutable,
    }

    #[derive(Clone, Copy, Debug)]
    enum HostMediaExecutable {
        MeshDwgBridge(MeshDwgDocumentImporter),
        TwoDSvgExport(TwoDSvgDocumentRenderer),
    }

    impl HostMediaHandlerDeclaration {
        /// 🏗️ Describes one mesh-DWG bridge without invoking its converter during assembly.
        pub async fn mesh_dwg_bridge(id: impl Into<String>, artifact_kind: ArtifactKindSpec, document_schema: impl Into<String>, importer: MeshDwgDocumentImporter) -> Result<Self, PluginAssemblyError> {
            let declaration = Self {
                id: ArtifactIdentity::parse(id).await.map_err(PluginAssemblyError::definition)?,
                kind: HostMediaHandlerKind::MeshDwgBridge,
                artifact_kind,
                document_schema: document_schema.into(),
                file_stem: None,
                executable: HostMediaExecutable::MeshDwgBridge(importer),
            };
            declaration.validate_shape().await?;
            Ok(declaration)
        }

        /// 🏗️ Describes one 2D SVG renderer without invoking it during assembly.
        pub async fn two_d_svg_export(id: impl Into<String>, artifact_kind: ArtifactKindSpec, document_schema: impl Into<String>, file_stem: impl Into<String>, renderer: TwoDSvgDocumentRenderer) -> Result<Self, PluginAssemblyError> {
            let declaration = Self {
                id: ArtifactIdentity::parse(id).await.map_err(PluginAssemblyError::definition)?,
                kind: HostMediaHandlerKind::TwoDSvgExport,
                artifact_kind,
                document_schema: document_schema.into(),
                file_stem: Some(file_stem.into()),
                executable: HostMediaExecutable::TwoDSvgExport(renderer),
            };
            declaration.validate_shape().await?;
            Ok(declaration)
        }

        /// 🪪️ Returns the stable contribution id.
        pub async fn id(&self) -> &str {
            self.id.as_str().await
        }

        /// ⚙️ Returns the complete executable identity used for idempotence and conflict rejection.
        pub async fn executable_identity(&self) -> HostMediaExecutableIdentity {
            match self.executable {
                HostMediaExecutable::MeshDwgBridge(importer) => HostMediaExecutableIdentity::MeshDwgBridge(importer as usize),
                HostMediaExecutable::TwoDSvgExport(renderer) => HostMediaExecutableIdentity::TwoDSvgExport(renderer as usize),
            }
        }

        async fn validate_shape(&self) -> Result<(), PluginAssemblyError> {
            if self.artifact_kind.id.trim().is_empty() || self.artifact_kind.schema.trim().is_empty() || self.document_schema.trim().is_empty() {
                return Err(PluginAssemblyError::new("plugin-assembly.host-media-shape", "host-media contributions require non-empty artifact kind and document schema"));
            }
            if self.artifact_kind.schema != self.document_schema {
                return Err(PluginAssemblyError::new(
                    "plugin-assembly.host-media-schema",
                    format!("host-media contribution {:?} schema {:?} does not equal artifact-kind schema {:?}", self.id.as_str().await, self.document_schema, self.artifact_kind.schema),
                ));
            }
            if matches!(self.kind, HostMediaHandlerKind::TwoDSvgExport) && self.file_stem.as_deref().is_none_or(|file_stem| file_stem.trim().is_empty()) {
                return Err(PluginAssemblyError::new("plugin-assembly.host-media-file-stem", "2D SVG export contributions require a non-empty file stem"));
            }
            Ok(())
        }

        pub(crate) async fn preflight(&self, owner: &str, declared_media_kinds: &BTreeMap<String, ArtifactKindSpec>) -> Result<(), PluginAssemblyError> {
            ArtifactIdentity::parse(owner.to_string()).await.map_err(PluginAssemblyError::definition)?;
            self.validate_shape().await?;
            let self_id = self.id.as_str().await;
            let declared = declared_media_kinds
                .get(&self.artifact_kind.id)
                .ok_or_else(|| PluginAssemblyError::new("plugin-assembly.host-media-owner", format!("host-media contribution {:?} targets undeclared artifact kind {:?}", self_id, self.artifact_kind.id)))?;
            if declared != &self.artifact_kind {
                return Err(PluginAssemblyError::new("plugin-assembly.host-media-kind", format!("host-media contribution {:?} does not use the plugin-owned descriptor for {:?}", self.id.as_str().await, self.artifact_kind.id)));
            }
            Ok(())
        }

        async fn descriptor(&self, owner: &str) -> HostMediaHandlerDescriptor {
            HostMediaHandlerDescriptor {
                id: self.id.as_str().await.to_string(),
                owner: owner.to_string(),
                kind: self.kind,
                artifact_kind: self.artifact_kind.clone(),
                document_schema: self.document_schema.clone(),
                file_stem: self.file_stem.clone(),
                executable_identity: self.executable_identity().await,
            }
        }
    }

    /// 📥️ Typed mesh-DWG bridge runtime request.
    #[derive(Clone, Debug, PartialEq)]
    pub struct MeshDwgBridgeRequest {
        pub artifact_kind: String,
        pub document_schema: String,
        pub mesh: semio_framework::MeshData,
    }

    /// 📤️ Typed mesh-DWG bridge runtime result.
    #[derive(Clone, Debug, PartialEq)]
    pub struct MeshDwgBridgeResult {
        pub document: Value,
    }

    /// 📥️ Typed 2D SVG export runtime request.
    #[derive(Clone, Debug, PartialEq)]
    pub struct TwoDSvgExportRequest {
        pub artifact_kind: String,
        pub document_schema: String,
        pub document: Value,
    }

    /// 📤️ Typed 2D SVG export runtime result.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct TwoDSvgExportResult {
        pub file_stem: String,
        pub svg: String,
        pub width: u32,
        pub height: u32,
    }

    /// 🚧️ Typed host-media runtime rejection.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct HostMediaRuntimeError {
        pub code: String,
        pub message: String,
    }

    impl std::fmt::Display for HostMediaRuntimeError {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(formatter, "{}: {}", self.code, self.message)
        }
    }

    impl std::error::Error for HostMediaRuntimeError {}

    /// ⚙️ Immutable executable identity for a flow-extension contribution.
    #[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
    pub struct FlowExtensionExecutableIdentity {
        pub package_id: String,
        pub module_id: String,
        pub entrypoint: String,
        pub abi: String,
    }

    impl FlowExtensionExecutableIdentity {
        /// 🏗️ Names a native executable entry without accepting an installer callback.
        pub async fn native(package_id: impl Into<String>, module_id: impl Into<String>, entrypoint: impl Into<String>) -> Result<Self, PluginAssemblyError> {
            let identity = Self { package_id: package_id.into(), module_id: module_id.into(), entrypoint: entrypoint.into(), abi: "semio.flow.extension.native.v1".into() };
            for value in [&identity.package_id, &identity.module_id, &identity.entrypoint, &identity.abi] {
                ArtifactIdentity::parse(value.clone()).await.map_err(PluginAssemblyError::definition)?;
            }
            Ok(identity)
        }
    }

    /// 🧾️ One closed contribution category inside a `flow.extension` manifest.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    pub enum FlowExtensionContributionKind {
        Schema,
        Operator,
        Widget,
        Command,
        Setting,
    }

    /// 🧾️ One externally addressable contribution declared by a flow extension.
    #[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
    pub struct FlowExtensionContribution {
        pub kind: FlowExtensionContributionKind,
        pub id: String,
    }

    impl FlowExtensionContribution {
        /// 🏗️ Creates one non-empty typed flow-extension contribution identity.
        pub async fn new(kind: FlowExtensionContributionKind, id: impl Into<String>) -> Result<Self, PluginAssemblyError> {
            let id = id.into();
            ArtifactIdentity::parse(id.clone()).await.map_err(PluginAssemblyError::definition)?;
            Ok(Self { kind, id })
        }
    }

    /// 📋️ Schema-owned, immutable `flow.extension` manifest descriptor.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct FlowExtensionManifest {
        pub id: String,
        pub name: String,
        pub version: String,
        pub activation_events: Vec<String>,
        pub contributions: Vec<FlowExtensionContribution>,
    }

    impl FlowExtensionManifest {
        /// 🏗️ Creates a typed flow-extension manifest with an explicit startup activation.
        pub async fn new(id: impl Into<String>, name: impl Into<String>, version: impl Into<String>) -> Result<Self, PluginAssemblyError> {
            let manifest = Self { id: id.into(), name: name.into(), version: version.into(), activation_events: vec!["onStartup".into()], contributions: Vec::new() };
            manifest.validate().await?;
            Ok(manifest)
        }

        /// 🧩️ Adds one typed contribution to this immutable descriptor.
        pub async fn contribution(mut self, contribution: FlowExtensionContribution) -> Result<Self, PluginAssemblyError> {
            if self.contributions.iter().any(|candidate| candidate.kind == contribution.kind && candidate.id == contribution.id) {
                return Ok(self);
            }
            self.contributions.push(contribution);
            Ok(self)
        }

        async fn validate(&self) -> Result<(), PluginAssemblyError> {
            ArtifactIdentity::parse(self.id.clone()).await.map_err(PluginAssemblyError::definition)?;
            if self.name.trim().is_empty() || self.version.trim().is_empty() || self.activation_events.iter().any(|event| event.trim().is_empty()) {
                return Err(PluginAssemblyError::new("plugin-assembly.flow-extension-manifest", "flow extension manifests require non-empty name, version, and activation events"));
            }
            let mut contributions = BTreeSet::new();
            for contribution in &self.contributions {
                ArtifactIdentity::parse(contribution.id.clone()).await.map_err(PluginAssemblyError::definition)?;
                if !contributions.insert((contribution.kind, contribution.id.clone())) {
                    return Err(PluginAssemblyError::new("plugin-assembly.flow-extension-contribution", format!("duplicate flow extension contribution {:?}", contribution.id)));
                }
            }
            Ok(())
        }
    }

    /// 📋️ Immutable runtime descriptor for one linked flow extension.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct FlowExtensionDescriptor {
        pub id: String,
        pub owner: String,
        pub domain: String,
        pub schema: String,
        pub extension_id: String,
        pub manifest: FlowExtensionManifest,
        pub executable_identity: FlowExtensionExecutableIdentity,
    }

    /// 🌊️ Immutable `flow.extension` contribution; it carries no mutating installer function.
    #[derive(Clone, Debug)]
    pub struct FlowExtensionDeclaration {
        id: ArtifactIdentity,
        extension_id: ArtifactIdentity,
        manifest: FlowExtensionManifest,
        executable_identity: FlowExtensionExecutableIdentity,
    }

    impl FlowExtensionDeclaration {
        /// 🏗️ Declares a `flow.extension` manifest and its immutable native executable identity.
        pub async fn new(id: impl Into<String>, manifest: FlowExtensionManifest, executable_identity: FlowExtensionExecutableIdentity) -> Result<Self, PluginAssemblyError> {
            let declaration = Self { id: ArtifactIdentity::parse(id).await.map_err(PluginAssemblyError::definition)?, extension_id: ArtifactIdentity::parse(manifest.id.clone()).await.map_err(PluginAssemblyError::definition)?, manifest, executable_identity };
            declaration.validate_shape().await?;
            Ok(declaration)
        }

        /// 🪪️ Returns the stable contribution id.
        pub async fn id(&self) -> &str {
            self.id.as_str().await
        }

        async fn validate_shape(&self) -> Result<(), PluginAssemblyError> {
            self.manifest.validate().await
        }

        pub(crate) async fn preflight(&self, owner: &str) -> Result<(), PluginAssemblyError> {
            ArtifactIdentity::parse(owner.to_string()).await.map_err(PluginAssemblyError::definition)?;
            self.validate_shape().await
        }

        async fn descriptor(&self, owner: &str) -> FlowExtensionDescriptor {
            FlowExtensionDescriptor {
                id: self.id.as_str().await.to_string(),
                owner: owner.to_string(),
                domain: "flow.extension".into(),
                schema: "flow.extension".into(),
                extension_id: self.extension_id.as_str().to_string(),
                manifest: self.manifest.clone(),
                executable_identity: self.executable_identity.clone(),
            }
        }
    }

    struct RegisteredHostMediaHandler {
        descriptor: HostMediaHandlerDescriptor,
        executable: HostMediaExecutable,
    }

    impl RegisteredHostMediaHandler {
        async fn identical_to(&self, other: &Self) -> bool {
            self.descriptor == other.descriptor
                && match (self.executable, other.executable) {
                    (HostMediaExecutable::MeshDwgBridge(left), HostMediaExecutable::MeshDwgBridge(right)) => std::ptr::fn_addr_eq(left, right),
                    (HostMediaExecutable::TwoDSvgExport(left), HostMediaExecutable::TwoDSvgExport(right)) => std::ptr::fn_addr_eq(left, right),
                    _ => false,
                }
        }
    }

    struct HostMediaHandlerRegistry {
        by_id: BTreeMap<String, RegisteredHostMediaHandler>,
        by_target: BTreeMap<(HostMediaHandlerKind, String), String>,
    }

    impl HostMediaHandlerRegistry {
        async fn new() -> Self {
            Self { by_id: BTreeMap::new(), by_target: BTreeMap::new() }
        }

        async fn from_declarations(owner: &str, declarations: &[HostMediaHandlerDeclaration]) -> Result<Self, PluginAssemblyError> {
            let mut registry = Self::new().await;
            for declaration in declarations {
                registry.register(owner, declaration).await?;
            }
            Ok(registry)
        }

        async fn register(&mut self, owner: &str, declaration: &HostMediaHandlerDeclaration) -> Result<(), PluginAssemblyError> {
            let descriptor = declaration.descriptor(owner).await;
            let entry = RegisteredHostMediaHandler { descriptor: descriptor.clone(), executable: declaration.executable };
            if let Some(existing) = self.by_id.get(&descriptor.id) {
                if existing.identical_to(&entry).await {
                    return Ok(());
                }
                return Err(PluginAssemblyError::new("plugin-assembly.host-media-id", format!("host-media contribution {:?} has a conflicting descriptor or executable identity", descriptor.id)));
            }
            let target = (descriptor.kind, descriptor.artifact_kind.id.clone());
            if let Some(existing) = self.by_target.get(&target) {
                return Err(PluginAssemblyError::new("plugin-assembly.host-media-target", format!("host-media target {}:{} is already owned by {:?}", descriptor.kind.as_str().await, descriptor.artifact_kind.id, existing)));
            }
            self.by_target.insert(target, descriptor.id.clone());
            self.by_id.insert(descriptor.id.clone(), entry);
            Ok(())
        }

        async fn descriptors(&self) -> Vec<HostMediaHandlerDescriptor> {
            self.by_id.values().map(|entry| entry.descriptor.clone()).collect()
        }

        async fn mesh_dwg_bridge(&self, request: MeshDwgBridgeRequest) -> Result<MeshDwgBridgeResult, HostMediaRuntimeError> {
            let entry = self.lookup(HostMediaHandlerKind::MeshDwgBridge, &request.artifact_kind, &request.document_schema).await?;
            let HostMediaExecutable::MeshDwgBridge(importer) = entry.executable else {
                return Err(HostMediaRuntimeError { code: "host-media.executable-kind".into(), message: format!("host-media target {:?} has no mesh-DWG executable", request.artifact_kind) });
            };
            importer(&request.mesh).map(|document| MeshDwgBridgeResult { document }).map_err(|message| HostMediaRuntimeError { code: "host-media.mesh-dwg".into(), message })
        }

        async fn two_d_svg_export(&self, request: TwoDSvgExportRequest) -> Result<TwoDSvgExportResult, HostMediaRuntimeError> {
            let entry = self.lookup(HostMediaHandlerKind::TwoDSvgExport, &request.artifact_kind, &request.document_schema).await?;
            let HostMediaExecutable::TwoDSvgExport(renderer) = entry.executable else {
                return Err(HostMediaRuntimeError { code: "host-media.executable-kind".into(), message: format!("host-media target {:?} has no 2D SVG executable", request.artifact_kind) });
            };
            let (svg, width, height) = renderer(&request.document).map_err(|message| HostMediaRuntimeError { code: "host-media.2d-svg".into(), message })?;
            Ok(TwoDSvgExportResult { file_stem: entry.descriptor.file_stem.clone().expect("2D SVG declaration requires a file stem"), svg, width, height })
        }

        async fn lookup(&self, kind: HostMediaHandlerKind, artifact_kind: &str, document_schema: &str) -> Result<&RegisteredHostMediaHandler, HostMediaRuntimeError> {
            let kind_str = kind.as_str().await;
            let id =
                self.by_target.get(&(kind, artifact_kind.to_string())).ok_or_else(|| HostMediaRuntimeError { code: "host-media.not-declared".into(), message: format!("no {} declaration for artifact kind {:?}", kind_str, artifact_kind) })?;
            let entry = self.by_id.get(id).expect("host-media target index always points to an entry");
            if entry.descriptor.document_schema != document_schema {
                return Err(HostMediaRuntimeError {
                    code: "host-media.schema-mismatch".into(),
                    message: format!("host-media declaration {:?} expects schema {:?}, request supplied {:?}", entry.descriptor.id, entry.descriptor.document_schema, document_schema),
                });
            }
            Ok(entry)
        }
    }

    struct FlowExtensionRegistry {
        by_id: BTreeMap<String, FlowExtensionDescriptor>,
        by_extension_id: BTreeMap<String, String>,
    }

    impl FlowExtensionRegistry {
        async fn new() -> Self {
            Self { by_id: BTreeMap::new(), by_extension_id: BTreeMap::new() }
        }

        async fn from_declarations(owner: &str, declarations: &[FlowExtensionDeclaration]) -> Result<Self, PluginAssemblyError> {
            let mut registry = Self::new().await;
            for declaration in declarations {
                registry.register(owner, declaration).await?;
            }
            Ok(registry)
        }

        async fn register(&mut self, owner: &str, declaration: &FlowExtensionDeclaration) -> Result<(), PluginAssemblyError> {
            let descriptor = declaration.descriptor(owner).await;
            if let Some(existing) = self.by_id.get(&descriptor.id) {
                if existing == &descriptor {
                    return Ok(());
                }
                return Err(PluginAssemblyError::new("plugin-assembly.flow-extension-id", format!("flow extension contribution {:?} has a conflicting descriptor or executable identity", descriptor.id)));
            }
            if let Some(existing) = self.by_extension_id.get(&descriptor.extension_id) {
                return Err(PluginAssemblyError::new("plugin-assembly.flow-extension-target", format!("flow extension {:?} is already owned by {:?}", descriptor.extension_id, existing)));
            }
            self.by_extension_id.insert(descriptor.extension_id.clone(), descriptor.id.clone());
            self.by_id.insert(descriptor.id.clone(), descriptor);
            Ok(())
        }

        async fn descriptors(&self) -> Vec<FlowExtensionDescriptor> {
            self.by_id.values().cloned().collect()
        }
    }
    //#endregion 🧭️RuntimeContributions

    /// 🧭️ One immutable plugin runtime catalogue assembled before any shared registry commit.
    pub(crate) struct ArtifactRegistrationPlan {
        schemas: Vec<::semio_framework_schema::ArtifactSchemaDescriptor>,
        inferences: Vec<::semio_framework_schema::ArtifactInferenceDescriptor>,
        inference_services: Vec<ArtifactInferenceService>,
        formats: Vec<semio_framework::FormatDescriptor>,
        subset_validators: Vec<&'static SubsetValidatorEntry>,
        composers: Vec<&'static ComposerEntry>,
        languages: Vec<dsl::LanguageSpec>,
        document_codecs: Vec<store::ArtifactCodec>,
        migrations: Vec<store::DialectMigration>,
        app_schemas: Vec<::semio_framework_schema::AppSchemaDescriptor>,
        owner: String,
        host_media_handlers: Vec<HostMediaHandlerDeclaration>,
        flow_extensions: Vec<FlowExtensionDeclaration>,
    }

    impl ArtifactRegistrationPlan {
        pub(crate) async fn from_declarations(
            declarations: &[ArtifactDeclaration],
            app_schemas: Vec<::semio_framework_schema::AppSchemaDescriptor>,
            foreign_document_codecs: Vec<DocumentCodecSpec>,
            owner: impl Into<String>,
            host_media_handlers: Vec<HostMediaHandlerDeclaration>,
            flow_extensions: Vec<FlowExtensionDeclaration>,
        ) -> Self {
            let mut plan = Self {
                schemas: Vec::new(),
                inferences: Vec::new(),
                inference_services: Vec::new(),
                formats: Vec::new(),
                subset_validators: Vec::new(),
                composers: Vec::new(),
                languages: Vec::new(),
                document_codecs: Vec::new(),
                migrations: Vec::new(),
                app_schemas,
                owner: owner.into(),
                host_media_handlers,
                flow_extensions,
            };
            for declaration in declarations {
                plan.schemas.extend(declaration.schemas.iter().cloned());
                plan.inferences.extend(declaration.inferences.iter().cloned());
                plan.inference_services.extend(declaration.inference_services.iter().copied());
                plan.formats.extend(declaration.formats.iter().cloned());
                plan.subset_validators.extend(declaration.subset_validators.iter().copied());
                plan.composers.extend(declaration.composers.iter().copied());
                plan.languages.extend(declaration.languages.iter().map(|spec| **spec));
                for spec in declaration.document_codecs.iter() {
                    plan.document_codecs.push(spec.codec().await);
                }
                plan.migrations.extend(declaration.migrations.iter().cloned());
            }
            for spec in foreign_document_codecs.iter() {
                plan.document_codecs.push(spec.codec().await);
            }
            plan
        }

        /// 🧬️ Freezes every definition, schema, app, language, and inference before external state changes.
        pub(crate) async fn into_runtime(self, definitions: ArtifactDefinitionRegistry) -> Result<(PluginRuntimeRegistry, semio_framework::io::ArtifactAssemblyRegistryPlan), PluginAssemblyError> {
            let Self { schemas, inferences, inference_services: declared_inference_services, formats, subset_validators, composers, languages, document_codecs, migrations, app_schemas, owner, host_media_handlers, flow_extensions } = self;
            let mut inference_services = ArtifactInferenceServiceRegistry::new().await;
            for service in &declared_inference_services {
                inference_services.register(*service).await.map_err(|error| PluginAssemblyError::new("plugin-assembly.inference", error.to_string()))?;
            }
            let host_media_handlers = HostMediaHandlerRegistry::from_declarations(&owner, &host_media_handlers).await?;
            let flow_extensions = FlowExtensionRegistry::from_declarations(&owner, &flow_extensions).await?;
            Ok((
                PluginRuntimeRegistry { definitions, schemas, inferences, inference_services, languages, app_schemas, host_media_handlers, flow_extensions, owner_mutations: BTreeMap::new(), contributed_mutations: BTreeMap::new() },
                semio_framework::io::ArtifactAssemblyRegistryPlan { composer_entries: composers, subset_validators, format_descriptors: formats, document_codecs, dialect_migrations: migrations },
            ))
        }
    }

    /// 🧬️ Authoritative per-plugin runtime declarations. It is complete before global IO/store rows mutate.
    pub(crate) struct PluginRuntimeRegistry {
        definitions: ArtifactDefinitionRegistry,
        // 🕳️ Unlike every other field here, these four have no reader anywhere in this crate —
        // `inference_services`/`host_media_handlers`/`flow_extensions`/the two mutation maps all
        // flow out through a `self.runtime.*` accessor (see the `impl` below); these were collected
        // at `into_runtime` time and then never consumed. Z1 (26/08/17/MICROKERNEL-POOLED-ACTOR-PLUGIN-RUNTIME)
        // found this while chasing a `dead_code` warning: a real gap (some global artifact
        // schema/inference/language catalog this crate should be publishing into, analogous to how
        // `definitions()` already exposes `ArtifactDefinitionRegistry`), not dead data — flagged for
        // follow-up wiring rather than fixed here, since inventing the consumer without knowing the
        // intended catalog risks wiring it to the wrong place.
        #[allow(dead_code, reason = "captured but unwired — see comment above, follow-up needed")]
        schemas: Vec<::semio_framework_schema::ArtifactSchemaDescriptor>,
        #[allow(dead_code, reason = "captured but unwired — see comment above, follow-up needed")]
        inferences: Vec<::semio_framework_schema::ArtifactInferenceDescriptor>,
        inference_services: ArtifactInferenceServiceRegistry,
        #[allow(dead_code, reason = "captured but unwired — see comment above, follow-up needed")]
        languages: Vec<dsl::LanguageSpec>,
        #[allow(dead_code, reason = "captured but unwired — see comment above, follow-up needed")]
        app_schemas: Vec<::semio_framework_schema::AppSchemaDescriptor>,
        host_media_handlers: HostMediaHandlerRegistry,
        flow_extensions: FlowExtensionRegistry,
        owner_mutations: BTreeMap<String, WireMutationRosterEntry>,
        contributed_mutations: BTreeMap<String, ContributedMutationRuntimeEntry>,
    }

    impl PluginRuntimeRegistry {
        async fn empty() -> Self {
            Self {
                definitions: ArtifactDefinitionRegistry::new().await,
                schemas: Vec::new(),
                inferences: Vec::new(),
                inference_services: ArtifactInferenceServiceRegistry::new().await,
                languages: Vec::new(),
                app_schemas: Vec::new(),
                host_media_handlers: HostMediaHandlerRegistry::new().await,
                flow_extensions: FlowExtensionRegistry::new().await,
                owner_mutations: BTreeMap::new(),
                contributed_mutations: BTreeMap::new(),
            }
        }

        async fn inference_services(&self) -> &ArtifactInferenceServiceRegistry {
            &self.inference_services
        }

        /// 🧾️ Reads the immutable definitions published by this plugin assembly.
        pub async fn definitions(&self) -> &ArtifactDefinitionRegistry {
            &self.definitions
        }

        pub(crate) async fn extend_contributions(
            &mut self,
            inference_services: Vec<ArtifactInferenceService>,
            owner_rosters: &[fn() -> (&'static str, &'static [::protocol::SemanticDescriptor])],
            contributed_mutations: Vec<(String, ContributedMutationRuntimeEntry)>,
        ) -> Result<(), PluginAssemblyError> {
            for service in inference_services {
                self.inference_services.register(service).await.map_err(|error| PluginAssemblyError::new("plugin-assembly.contribution-inference", error.to_string()))?;
            }
            for provider in owner_rosters {
                let (document_schema, kinds) = provider();
                for descriptor in kinds {
                    let entry = WireMutationRosterEntry::owner(document_schema, descriptor).await;
                    if let Some(existing) = self.owner_mutations.get(&entry.mutation_id) {
                        if existing != &entry {
                            return Err(PluginAssemblyError::new("plugin-assembly.owner-mutation-roster", format!("conflicting owner mutation roster entry for {:?}", entry.mutation_id)));
                        }
                    } else {
                        self.owner_mutations.insert(entry.mutation_id.clone(), entry);
                    }
                }
            }
            for (mutation_id, entry) in contributed_mutations {
                if let Some(existing) = self.contributed_mutations.get(&mutation_id) {
                    if existing.roster != entry.roster || !std::ptr::fn_addr_eq(existing.plan_cold, entry.plan_cold) {
                        return Err(PluginAssemblyError::new("plugin-assembly.contribution-mutation", format!("conflicting contributed mutation registration for {mutation_id:?}")));
                    }
                } else {
                    self.contributed_mutations.insert(mutation_id, entry);
                }
            }
            Ok(())
        }

        async fn mutation_roster_entries(&self) -> Vec<WireMutationRosterEntry> {
            let mut entries: Vec<_> = self.owner_mutations.values().cloned().collect();
            entries.extend(self.contributed_mutations.values().map(|entry| entry.roster.clone()));
            entries.sort_by(|left, right| left.mutation_id.cmp(&right.mutation_id));
            entries
        }

        async fn contributed_mutation_plan(&self, mutation_id: &str, artifact_kind: &str, snapshot_pack: &[u8], payload: &[u8]) -> Result<ContributedMutationPlanOutput, ContributedMutationExecutionError> {
            let entry = self.contributed_mutations.get(mutation_id).ok_or_else(|| ContributedMutationExecutionError::new("artifact-mutation.not-registered", format!("no contributed mutation service for {mutation_id:?}")))?;
            if entry.roster.artifact_kind.as_deref() != Some(artifact_kind) {
                return Err(ContributedMutationExecutionError::new("artifact-mutation.artifact-kind-mismatch", format!("mutation {mutation_id:?} targets {:?}, request claims {artifact_kind:?}", entry.roster.artifact_kind)));
            }
            (entry.plan_cold)(snapshot_pack, payload)
        }
    }

    /// 📌️ Atomically commits all external IO/store registry rows after the local runtime is frozen.
    pub(crate) async fn commit_artifact_registration_plan(assembly: &store::ArtifactAssemblyTransaction, plan: semio_framework::io::ArtifactAssemblyRegistryPlan) -> Result<(), PluginAssemblyError> {
        semio_framework::io::commit_artifact_assembly_registry_plan(assembly, plan).await.map_err(|error| PluginAssemblyError::new("plugin-assembly.registry", error.to_string()))
    }
    //#endregion 🔖️ArtifactDeclaration

    //#region 🔖️ArtifactContribution
    /// 🗂️ One plugin's contribution of mutations and/or inferences onto an artifact kind OWNED by a
    /// plugin it directly depends on — contract freeze `26/08/16/PLUGIN-DEPENDENCIES-ARTIFACT-
    /// CONTRIBUTIONS-AND-COMPOSITE-MUTATIONS` §3/§4. Built through `ArtifactContribution::builder`
    /// (self-accumulating, no typestate — only `artifact_kind` is mandatory and it is supplied up
    /// front), consumed by `PluginBuilder::contributes`/`ExtensionBundle::contributes`, which resolve
    /// it against their own plugin id (`.resolve`) and hand the result to `register_contributions`
    /// for the frozen gates before any runtime registration.
    pub struct ArtifactContribution {
        artifact_kind: String,
        mutations: Vec<ContributedMutationSpec>,
        inference_services: Vec<ArtifactInferenceService>,
        inference_depends_on: BTreeMap<String, Vec<String>>,
    }

    /// 🗂️ One `.mutation::<Snapshot, Op, K>()` call, still missing the contributor's own plugin id
    /// (only known once a builder that already carries it calls `.contributes()`) — see
    /// `ArtifactContribution::resolve`.
    struct ContributedMutationSpec {
        target_document_schema: String,
        semantics: semio_framework::ContributedMutationSemantics,
        schema_version: u32,
        algorithm_version: u32,
        plan_cold: ColdContributedMutationPlan,
    }

    impl ArtifactContribution {
        /// 🪪️ Starts a contribution targeting one artifact kind owned by a plugin dependency.
        pub async fn builder(artifact_kind: impl Into<String>) -> Self {
            Self { artifact_kind: artifact_kind.into(), mutations: Vec::new(), inference_services: Vec::new(), inference_depends_on: BTreeMap::new() }
        }

        /// 🕸️ Declares one contributed composite-mutation kind. `K`'s payload is this plugin's own
        /// (the contributor's); `Snapshot`/`Op` are the TARGET artifact's own types (from the
        /// dependency crate) — the bound `K: protocol::CompositeMutationKind<Snapshot, Op>` makes a
        /// contribution that does not typecheck against the target artifact's own mutation vocabulary
        /// impossible to express: a `K` whose `plan` cannot drive a `Planner<Snapshot, Op>` simply does
        /// not satisfy it. `target_document_schema` is `Snapshot`'s owning `ArtifactApp::DOCUMENT_SCHEMA`
        /// (mirrors `.document_codec_bare`'s own `impl Into<String>` — a bare `Snapshot` type carries no
        /// compile-time document-schema constant of its own). The frozen id
        /// `"<target-document-schema>#<contributor-plugin-id>:<kebab-kind>"` is only fully assembled at
        /// `.resolve()`, once the contributor's own plugin id is known.
        pub async fn mutation<Snapshot, Op, K>(mut self, target_document_schema: impl Into<String>, schema_version: u32, algorithm_version: u32) -> Self
        where
            Snapshot: Clone + ArtifactPack + 'static,
            Op: ::protocol::Mutation<Snapshot> + ::protocol::OpBinary + 'static,
            K: ::protocol::CompositeMutationKind<Snapshot, Op> + 'static,
        {
            // 🚫️async: E4 fn-pointer slot — `ContributedMutationSpec.plan_cold: ColdContributedMutationPlan`
            // is a bare fn pointer; an `async fn` item's pointer type is unnameable. The body's own
            // awaits (`decode_pack`/`decode_contributed_wire`/`plan_of`/etc.) are all pure, no-real-
            // suspension calls (io-async-signatures), so the whole body is bridged via `resolve_ready`.
            fn plan_cold<Snapshot, Op, K>(snapshot_pack: &[u8], payload: &[u8]) -> Result<ContributedMutationPlanOutput, ContributedMutationExecutionError>
            where
                Snapshot: Clone + ArtifactPack,
                Op: ::protocol::Mutation<Snapshot> + ::protocol::OpBinary,
                K: ::protocol::CompositeMutationKind<Snapshot, Op>,
            {
                resolve_ready(async {
                    let base = Snapshot::decode_pack(snapshot_pack).await.map_err(|error| ContributedMutationExecutionError::new("artifact-mutation.snapshot-decode", error.to_string()))?;
                    let kind: K = decode_contributed_wire(payload).await.map_err(|error| ContributedMutationExecutionError::new("artifact-mutation.payload-decode", error))?;
                    let steps = ::protocol::plan_of(&kind, &base).await.map_err(|error| ContributedMutationExecutionError::new("artifact-mutation.plan", error.to_string()))?;
                    let label = kind.label().await;
                    let mut owner_ops = Vec::new();
                    let mut foreign = Vec::new();
                    for step in steps {
                        match step {
                            ::protocol::PlanStep::Local(op) => owner_ops.push(op.encode_op().await.map_err(|error| ContributedMutationExecutionError::new("artifact-mutation.op-encode", error.to_string()))?),
                            ::protocol::PlanStep::Foreign(hop) => foreign.push(hop),
                        }
                    }
                    Ok(ContributedMutationPlanOutput { owner_ops, label, foreign })
                })
            }
            self.mutations.push(ContributedMutationSpec {
                target_document_schema: target_document_schema.into(),
                semantics: semio_framework::ContributedMutationSemantics { verb: K::SEMANTICS.verb.to_string(), entity: K::SEMANTICS.entity.to_string(), kind: K::SEMANTICS.kind.to_string(), record: K::SEMANTICS.record.to_string() },
                schema_version,
                algorithm_version,
                plan_cold: plan_cold::<Snapshot, Op, K>,
            });
            self
        }

        /// 💡️ Declares one contributed executable inference service — same native
        /// `ArtifactInferenceService` shape a declaration's own `.inference_services(...)` takes; only
        /// the manifest-level gate (`register_contributions`) distinguishes "owned" from "contributed"
        /// (owner==self&&artifact_kind==self vs owner==contributor&&artifact_kind==target).
        pub async fn inference_service(mut self, service: ArtifactInferenceService) -> Self {
            self.inference_services.push(service);
            self
        }

        /// 🔗️ Declares `inference_schema`'s contributed-inference dependency ordering — folded into
        /// `ContributedInferenceMetadata.depends_on` at `.resolve()`.
        pub async fn inference_depends_on(mut self, inference_schema: impl Into<String>, depends_on: impl IntoIterator<Item = impl Into<String>>) -> Self {
            self.inference_depends_on.entry(inference_schema.into()).or_default().extend(depends_on.into_iter().map(Into::into));
            self
        }

        /// ✅️ Finalizes the contribution — infallible (every frozen gate needs the contributor's own
        /// plugin id, only known once a builder's `.contributes()` calls `.resolve()`).
        pub async fn build(self) -> Self {
            self
        }

        /// 🏗️ Assembles the manifest-facing `ArtifactContributionDescriptor` plus the native runtime
        /// pieces (inference services to register verbatim, and `(mutation_id, entry)` pairs for
        /// `commit_contributed_mutation_services`) now that `plugin_id` (the contributor) is known.
        /// Pure — no registry side effects; the caller runs `register_contributions` on the result
        /// before committing anything.
        pub(crate) async fn resolve(self, plugin_id: &str) -> (semio_framework::ArtifactContributionDescriptor, Vec<ArtifactInferenceService>, Vec<(String, ContributedMutationRuntimeEntry)>) {
            let mut mutation_metadata = Vec::with_capacity(self.mutations.len());
            let mut mutation_runtime = Vec::with_capacity(self.mutations.len());
            for spec in self.mutations {
                let mutation_id = format!("{}#{}:{}", spec.target_document_schema, plugin_id, spec.semantics.kind);
                let roster = WireMutationRosterEntry::contributed(plugin_id, &self.artifact_kind, mutation_id.clone(), &spec.semantics).await;
                mutation_metadata.push(semio_framework::ContributedMutationMetadata { mutation_id: mutation_id.clone(), semantics: spec.semantics, schema_version: spec.schema_version, algorithm_version: spec.algorithm_version });
                mutation_runtime.push((mutation_id, ContributedMutationRuntimeEntry { roster, plan_cold: spec.plan_cold }));
            }
            let inferences = self
                .inference_services
                .iter()
                .map(|service| {
                    let metadata = service.metadata();
                    semio_framework::ContributedInferenceMetadata {
                        owner: metadata.owner.to_string(),
                        artifact_kind: metadata.artifact_kind.to_string(),
                        artifact_schema: metadata.artifact_schema.to_string(),
                        artifact_schema_version: metadata.artifact_schema_version,
                        document_schema: metadata.document_schema.to_string(),
                        document_schema_version: metadata.document_schema_version,
                        inference_schema: metadata.inference_schema.to_string(),
                        inference_schema_version: metadata.inference_schema_version,
                        algorithm_version: metadata.algorithm_version,
                        policy_version: metadata.policy_version,
                        contributor: plugin_id.to_string(),
                        depends_on: self.inference_depends_on.get(metadata.inference_schema).cloned().unwrap_or_default(),
                    }
                })
                .collect();
            let descriptor = semio_framework::ArtifactContributionDescriptor { artifact_kind: self.artifact_kind, mutations: mutation_metadata, inferences };
            (descriptor, self.inference_services, mutation_runtime)
        }
    }

    /// 🚧️ Typed failure of the contract-freeze §4 registration gates (dependency directness, mutation
    /// id namespacing, contributed-inference identity) — pure over already-assembled manifest data,
    /// never touches a runtime registry.
    #[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
    pub(crate) enum ContributionRegistrationError {
        #[error("contribution targets artifact kind {artifact_kind:?} (owned by plugin {owner:?}), which is not a direct dependency of {plugin_id:?}")]
        DependencyNotDeclared { plugin_id: String, artifact_kind: String, owner: String },
        #[error("contribution targets artifact kind {0:?}, which is not canonical `s.<plugin>.<artifact>` grammar")]
        InvalidArtifactKind(String),
        #[error("contributed mutation id {mutation_id:?} does not match the frozen grammar `<target-document-schema>#{plugin_id}:<kebab-kind>`")]
        MalformedMutationId { plugin_id: String, mutation_id: String },
        #[error("contributed mutation id {0:?} collides with the bare owner-mutation-id grammar (`<document-schema>#<kebab-kind>`, no contributor `:` segment)")]
        CollidesWithOwnerKind(String),
        #[error("contributed inference {inference_schema:?} has owner/contributor {owner:?}/{contributor:?}, expected both to equal contributor {plugin_id:?}")]
        InferenceOwnerMismatch { plugin_id: String, inference_schema: String, owner: String, contributor: String },
        #[error("contributed inference {inference_schema:?} targets artifact_kind {actual:?}, expected the contribution's own target {expected:?}")]
        InferenceTargetMismatch { inference_schema: String, expected: String, actual: String },
    }

    /// ✅️ Contract freeze §4 registration gates, run over already-assembled manifest data (never a
    /// live registry): (a) a contribution's target artifact kind must be OWNED by a plugin the
    /// contributor directly depends on; (b) every contributed mutation id must match the frozen
    /// `"<target-document-schema>#<contributor-plugin-id>:<kebab-kind>"` grammar, which by
    /// construction can never collide with the colon-free owner-mutation-id grammar; (c) every
    /// contributed inference's `owner`/`contributor` must both equal `plugin_id`, and its
    /// `artifact_kind` must equal the contribution's own target. Called by both
    /// `PluginBuilder::try_build` and `ExtensionBundle::contributes` — see those call sites for how the
    /// pure `&[ArtifactContributionDescriptor]` this validates is assembled first.
    pub(crate) async fn register_contributions(plugin_id: &str, dependencies: &[semio_framework::PluginDependency], contributions: &[semio_framework::ArtifactContributionDescriptor]) -> Result<(), ContributionRegistrationError> {
        for descriptor in contributions {
            let target = ArtifactKindId::parse(&descriptor.artifact_kind).await.map_err(|_| ContributionRegistrationError::InvalidArtifactKind(descriptor.artifact_kind.clone()))?;
            let owner = target.plugin().await;
            if !dependencies.iter().any(|dependency| dependency.plugin_id == owner) {
                return Err(ContributionRegistrationError::DependencyNotDeclared { plugin_id: plugin_id.to_string(), artifact_kind: descriptor.artifact_kind.clone(), owner: owner.to_string() });
            }
            for mutation in &descriptor.mutations {
                let Some(hash_at) = mutation.mutation_id.rfind('#') else {
                    return Err(ContributionRegistrationError::MalformedMutationId { plugin_id: plugin_id.to_string(), mutation_id: mutation.mutation_id.clone() });
                };
                let suffix = &mutation.mutation_id[hash_at + 1..];
                if !suffix.contains(':') {
                    return Err(ContributionRegistrationError::CollidesWithOwnerKind(mutation.mutation_id.clone()));
                }
                let expected_suffix = format!("{plugin_id}:{}", mutation.semantics.kind);
                if suffix != expected_suffix {
                    return Err(ContributionRegistrationError::MalformedMutationId { plugin_id: plugin_id.to_string(), mutation_id: mutation.mutation_id.clone() });
                }
            }
            for inference in &descriptor.inferences {
                if inference.owner != plugin_id || inference.contributor != plugin_id {
                    return Err(ContributionRegistrationError::InferenceOwnerMismatch {
                        plugin_id: plugin_id.to_string(),
                        inference_schema: inference.inference_schema.clone(),
                        owner: inference.owner.clone(),
                        contributor: inference.contributor.clone(),
                    });
                }
                if inference.artifact_kind != descriptor.artifact_kind {
                    return Err(ContributionRegistrationError::InferenceTargetMismatch { inference_schema: inference.inference_schema.clone(), expected: descriptor.artifact_kind.clone(), actual: inference.artifact_kind.clone() });
                }
            }
        }
        Ok(())
    }

    /// 🗂️ One roster row of `contributor.list-artifact-mutations` — an owner mutation
    /// (`"<document-schema>#<kebab-kind>"`, `contributor`/`artifact_kind` both `None`) or a contributed
    /// one (`contributor`/`artifact_kind` both `Some`).
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub struct WireMutationRosterEntry {
        pub mutation_id: String,
        pub verb: String,
        pub entity: String,
        pub kind: String,
        pub record: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub contributor: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub artifact_kind: Option<String>,
    }

    impl WireMutationRosterEntry {
        async fn owner(document_schema: &str, descriptor: &::protocol::SemanticDescriptor) -> Self {
            Self {
                mutation_id: format!("{document_schema}#{}", descriptor.kind),
                verb: descriptor.verb.to_string(),
                entity: descriptor.entity.to_string(),
                kind: descriptor.kind.to_string(),
                record: descriptor.record.to_string(),
                contributor: None,
                artifact_kind: None,
            }
        }

        async fn contributed(plugin_id: &str, artifact_kind: &str, mutation_id: String, semantics: &semio_framework::ContributedMutationSemantics) -> Self {
            Self { mutation_id, verb: semantics.verb.clone(), entity: semantics.entity.clone(), kind: semantics.kind.clone(), record: semantics.record.clone(), contributor: Some(plugin_id.to_string()), artifact_kind: Some(artifact_kind.to_string()) }
        }
    }

    /// 🗂️ Type-erased plan result of one `contributor.artifact-mutation-plan` execution: the target
    /// artifact's own encoded ops, a human label, and any further foreign hops — mirrors
    /// `protocol::PlanStep`'s split without exposing the target's concrete `Op` type.
    #[derive(Clone, Debug, PartialEq)]
    pub struct ContributedMutationPlanOutput {
        pub owner_ops: Vec<Vec<u8>>,
        pub label: String,
        pub foreign: Vec<::protocol::ForeignStep>,
    }

    /// ⚠️ Structured failure from a type-erased contributed-mutation-plan execution boundary — mirrors
    /// `ArtifactInferenceExecutionError`'s shape for the mutation-contribution seam.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct ContributedMutationExecutionError {
        pub code: &'static str,
        pub message: String,
    }

    // 🚫️async: E1 pure error constructor consumed pervasively by sync closures
    // (`.map_err`/`.ok_or_else`) — see R9.
    impl ContributedMutationExecutionError {
        pub fn new(code: &'static str, message: impl Into<String>) -> Self {
            Self { code, message: message.into() }
        }
    }

    impl std::fmt::Display for ContributedMutationExecutionError {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(formatter, "{}: {}", self.code, self.message)
        }
    }

    impl std::error::Error for ContributedMutationExecutionError {}

    /// 🧰️ Native type-erased contributed-mutation-plan entry: target snapshot pack + contributor
    /// payload bytes in, target ops/label/foreign out. Non-capturing fn pointer monomorphized per
    /// `(Snapshot, Op, K)` by `ArtifactContribution::mutation`, exactly like `DocumentCodecSpec`/
    /// `ArtifactInferenceService`'s own thunks.
    pub type ColdContributedMutationPlan = fn(&[u8], &[u8]) -> Result<ContributedMutationPlanOutput, ContributedMutationExecutionError>;

    /// 🧰️ One committed contributed-mutation runtime entry — the wire roster row plus the fn pointer
    /// `wire_artifact_mutation_plan` calls.
    pub(crate) struct ContributedMutationRuntimeEntry {
        roster: WireMutationRosterEntry,
        plan_cold: ColdContributedMutationPlan,
    }

    /// 🎞️ `contributor.artifact-mutation-plan`'s request envelope: target snapshot pack + contributor
    /// payload in, plus the identity/echo fields (`artifact_kind`/`mutation_id`/`revision`/
    /// `generation`) `wire_artifact_mutation_plan` validates and echoes back.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    pub struct WireArtifactMutationPlanRequest {
        pub artifact_kind: String,
        pub mutation_id: String,
        pub revision: u64,
        pub generation: u64,
        pub snapshot_pack: Vec<u8>,
        pub payload: Vec<u8>,
    }

    /// 🎞️ `contributor.artifact-mutation-plan`'s result envelope — echoes the request's identity
    /// fields alongside the plan's `owner_ops`/`label`/`foreign`.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    pub struct WireArtifactMutationPlanResult {
        pub artifact_kind: String,
        pub mutation_id: String,
        pub revision: u64,
        pub generation: u64,
        pub owner_ops: Vec<Vec<u8>>,
        pub label: String,
        pub foreign: Vec<::protocol::ForeignStep>,
    }

    #[cfg(test)]
    pub(crate) async fn encode_contributed_wire<T: Serialize>(value: &T) -> Vec<u8> {
        store::pack_rt::encode_wire_value(&to_dsl_value(value).unwrap_or(DslValue::Null))
    }

    async fn decode_contributed_wire<T: DeserializeOwned>(bytes: &[u8]) -> Result<T, String> {
        let value = store::pack_rt::decode_wire_value(bytes).await.map_err(|error| error.to_string())?;
        dsl::from_dsl_value(value)
    }

    static OWNER_MUTATION_ROSTER_REGISTRY: std::sync::OnceLock<std::sync::RwLock<BTreeMap<String, WireMutationRosterEntry>>> = std::sync::OnceLock::new();
    static CONTRIBUTED_MUTATION_REGISTRY: std::sync::OnceLock<std::sync::RwLock<BTreeMap<String, ContributedMutationRuntimeEntry>>> = std::sync::OnceLock::new();

    async fn owner_mutation_roster_registry() -> &'static std::sync::RwLock<BTreeMap<String, WireMutationRosterEntry>> {
        OWNER_MUTATION_ROSTER_REGISTRY.get_or_init(|| std::sync::RwLock::new(BTreeMap::new()))
    }

    async fn contributed_mutation_registry() -> &'static std::sync::RwLock<BTreeMap<String, ContributedMutationRuntimeEntry>> {
        CONTRIBUTED_MUTATION_REGISTRY.get_or_init(|| std::sync::RwLock::new(BTreeMap::new()))
    }

    /// 📌️ Commits every document app's owner mutation roster (`PluginBuilder::document_app`'s
    /// captured `(document_schema, kinds)` providers) — idempotent for byte-identical re-registration
    /// (mirrors `ArtifactInferenceServiceRegistry::register`), a typed conflict otherwise.
    #[cfg(test)]
    pub(crate) async fn commit_owner_mutation_roster(providers: &[fn() -> (&'static str, &'static [::protocol::SemanticDescriptor])]) -> Result<(), PluginAssemblyError> {
        let mut registry = owner_mutation_roster_registry().write().map_err(|_| PluginAssemblyError::new("plugin-assembly.owner-mutation-roster", "owner mutation roster registry is poisoned"))?;
        for provider in providers {
            let (document_schema, kinds) = provider();
            for descriptor in kinds {
                let entry = WireMutationRosterEntry::owner(document_schema, descriptor);
                if let Some(existing) = registry.get(&entry.mutation_id) {
                    if *existing != entry {
                        return Err(PluginAssemblyError::new("plugin-assembly.owner-mutation-roster", format!("conflicting owner mutation roster entry for {:?}", entry.mutation_id)));
                    }
                    continue;
                }
                registry.insert(entry.mutation_id.clone(), entry);
            }
        }
        Ok(())
    }

    /// 📌️ Commits every resolved contribution's `(mutation_id, runtime entry)` pair — same
    /// idempotent-or-typed-conflict discipline as `commit_owner_mutation_roster`.
    pub(crate) async fn commit_contributed_mutation_services(entries: Vec<(String, ContributedMutationRuntimeEntry)>) -> Result<(), PluginAssemblyError> {
        let mut registry = contributed_mutation_registry().await.write().map_err(|_| PluginAssemblyError::new("plugin-assembly.contribution-mutation-registry", "contributed mutation registry is poisoned"))?;
        for (mutation_id, entry) in entries {
            if let Some(existing) = registry.get(&mutation_id) {
                if existing.roster != entry.roster || !std::ptr::fn_addr_eq(existing.plan_cold, entry.plan_cold) {
                    return Err(PluginAssemblyError::new("plugin-assembly.contribution-mutation-registry", format!("conflicting contributed mutation registration for {mutation_id:?}")));
                }
                continue;
            }
            registry.insert(mutation_id, entry);
        }
        Ok(())
    }

    /// 📖️ This process's deterministic mutation roster (owner + contributed rows, sorted by
    /// `mutation_id`) — `plugin_runtime::wire_list_artifact_mutations`'s data source.
    pub(crate) async fn mutation_roster_entries() -> Vec<WireMutationRosterEntry> {
        let mut entries: Vec<WireMutationRosterEntry> = owner_mutation_roster_registry().await.read().map(|registry| registry.values().cloned().collect()).unwrap_or_default();
        entries.extend(contributed_mutation_registry().await.read().map(|registry| registry.values().map(|entry| entry.roster.clone()).collect::<Vec<_>>()).unwrap_or_default());
        entries.sort_by(|a, b| a.mutation_id.cmp(&b.mutation_id));
        entries
    }

    /// 🎯️ Runs a registered contributed mutation's plan against `snapshot_pack`/`payload`, first
    /// verifying `artifact_kind` echoes the mutation's own registered target — mirrors
    /// `wire_artifact_infer`'s `validate_wire_request_metadata` discipline for the mutation-plan seam.
    pub(crate) async fn contributed_mutation_plan(mutation_id: &str, artifact_kind: &str, snapshot_pack: &[u8], payload: &[u8]) -> Result<ContributedMutationPlanOutput, ContributedMutationExecutionError> {
        let registry = contributed_mutation_registry().await.read().map_err(|_| ContributedMutationExecutionError::new("artifact-mutation.unavailable", "contributed mutation registry is poisoned"))?;
        let entry = registry.get(mutation_id).ok_or_else(|| ContributedMutationExecutionError::new("artifact-mutation.not-registered", format!("no contributed mutation service for {mutation_id:?}")))?;
        if entry.roster.artifact_kind.as_deref() != Some(artifact_kind) {
            return Err(ContributedMutationExecutionError::new("artifact-mutation.artifact-kind-mismatch", format!("mutation {mutation_id:?} targets {:?}, request claims {artifact_kind:?}", entry.roster.artifact_kind)));
        }
        (entry.plan_cold)(snapshot_pack, payload)
    }

    #[cfg(test)]
    mod artifact_contribution_tests {
        use super::*;

        async fn semantics(kind: &str) -> semio_framework::ContributedMutationSemantics {
            semio_framework::ContributedMutationSemantics { verb: "add".into(), entity: "thing".into(), kind: kind.into(), record: "AddedThing".into() }
        }

        async fn descriptor_with_mutation(artifact_kind: &str, mutation_id: &str, kind: &str) -> semio_framework::ArtifactContributionDescriptor {
            semio_framework::ArtifactContributionDescriptor {
                artifact_kind: artifact_kind.into(),
                mutations: vec![semio_framework::ContributedMutationMetadata { mutation_id: mutation_id.into(), semantics: semantics(kind), schema_version: 1, algorithm_version: 1 }],
                inferences: Vec::new(),
            }
        }

        #[semio_framework_async_macros::async_test]
        async fn dependency_gating_rejects_a_contribution_onto_a_non_dependency() {
            let descriptor = descriptor_with_mutation("s.dep.target", "dep.document#contributor:add-thing", "add-thing");
            let error = register_contributions("contributor", &[], std::slice::from_ref(&descriptor)).expect_err("missing dependency must be rejected");
            assert!(matches!(error, ContributionRegistrationError::DependencyNotDeclared { owner, .. } if owner == "dep"));
            let dependencies = vec![semio_framework::PluginDependency::new("dep", semio_framework::VersionReq::Any)];
            register_contributions("contributor", &dependencies, std::slice::from_ref(&descriptor)).expect("direct dependency must be accepted");
        }

        #[semio_framework_async_macros::async_test]
        async fn id_namespacing_rejects_a_collision_with_an_owner_kind() {
            let dependencies = vec![semio_framework::PluginDependency::new("dep", semio_framework::VersionReq::Any)];
            let bare = descriptor_with_mutation("s.dep.target", "dep.document#add-thing", "add-thing");
            let error = register_contributions("contributor", &dependencies, std::slice::from_ref(&bare)).expect_err("bare owner-shaped id must be rejected");
            assert!(matches!(error, ContributionRegistrationError::CollidesWithOwnerKind(id) if id == "dep.document#add-thing"));
            let well_formed = descriptor_with_mutation("s.dep.target", "dep.document#contributor:add-thing", "add-thing");
            register_contributions("contributor", &dependencies, std::slice::from_ref(&well_formed)).expect("well-formed contributed id must be accepted");
        }

        async fn owner_roster_provider() -> (&'static str, &'static [::protocol::SemanticDescriptor]) {
            const KINDS: &[::protocol::SemanticDescriptor] =
                &[::protocol::SemanticDescriptor { verb: "add", entity: "widget", kind: "add-widget", record: "AddedWidget" }, ::protocol::SemanticDescriptor { verb: "remove", entity: "widget", kind: "remove-widget", record: "RemovedWidget" }];
            ("roster-determinism-test.document", KINDS)
        }

        #[semio_framework_async_macros::async_test]
        async fn mutation_roster_entries_are_deterministic_across_repeated_calls() {
            let providers: &[fn() -> (&'static str, &'static [::protocol::SemanticDescriptor])] = &[owner_roster_provider];
            commit_owner_mutation_roster(providers).expect("commit owner roster");
            let first = mutation_roster_entries();
            let second = mutation_roster_entries();
            assert_eq!(first, second);
            let mut sorted = first.clone();
            sorted.sort_by(|a, b| a.mutation_id.cmp(&b.mutation_id));
            assert_eq!(first, sorted);
            assert!(first.iter().any(|entry| entry.mutation_id == "roster-determinism-test.document#add-widget"));
        }
    }
    //#endregion 🔖️ArtifactContribution

    #[cfg(test)]
    mod artifact_definition_contract_tests {
        use super::*;

        async fn identity(value: &str) -> ArtifactIdentity {
            ArtifactIdentity::parse(value).unwrap()
        }

        async fn capability(owner: &ArtifactIdentity, segment: &str, kind: ArtifactCapabilityKind) -> ArtifactCapability {
            ArtifactCapability::new(owner.child(segment).unwrap(), kind).descriptor(b"test".to_vec()).unwrap()
        }

        #[semio_framework_async_macros::async_test]
        async fn plural_definition_carries_every_artifact_capability_without_a_dispatch_edit() {
            let owner = identity("s.stdio.ifc");
            let schema = capability(&owner, "schema", ArtifactCapabilityKind::schema()).claim(ArtifactIdentityClaim::new(ArtifactIdentityNamespace::schema(), "s.stdio.ifc.v4").unwrap()).unwrap();
            let standard = capability(&owner, "standard", ArtifactCapabilityKind::standard());
            let profile = capability(&owner, "profile", ArtifactCapabilityKind::profile());
            let dialect = capability(&owner, "source-dialect", ArtifactCapabilityKind::source_dialect()).claim(ArtifactIdentityClaim::new(ArtifactIdentityNamespace::dialect(), "s.stdio.ifc.standard.v4.dialect.any").unwrap()).unwrap();
            let representation = capability(&owner, "representation", ArtifactCapabilityKind::representation()).claim(ArtifactIdentityClaim::new(ArtifactIdentityNamespace::mime(), "application/ifc").unwrap()).unwrap();
            let codec = capability(&owner, "codec", ArtifactCapabilityKind::codec()).claim(ArtifactIdentityClaim::new(ArtifactIdentityNamespace::codec(), "stdio.ifc.v4.pack").unwrap()).unwrap();
            let mutation = capability(&owner, "mutation", ArtifactCapabilityKind::mutation());
            let inference = capability(&owner, "inference", ArtifactCapabilityKind::inference());
            let resource = capability(&owner, "resource", ArtifactCapabilityKind::resource()).claim(ArtifactIdentityClaim::new(ArtifactIdentityNamespace::extension(), "ifc").unwrap()).unwrap();
            let localization = capability(&owner, "localization", ArtifactCapabilityKind::localization())
                .localization(ArtifactLocalization::new(ArtifactLocale::parse("en").unwrap(), "Industry Foundation Classes").unwrap())
                .unwrap()
                .localization(ArtifactLocalization::new(ArtifactLocale::parse("de").unwrap(), "Industriegrundklassen").unwrap())
                .unwrap();
            let conformance = capability(&owner, "conformance-suite", ArtifactCapabilityKind::conformance_suite()).claim(ArtifactIdentityClaim::new(ArtifactIdentityNamespace::extension_implementation(), "ifc-v4-conformance").unwrap()).unwrap();
            let definition = [schema, standard, profile, dialect, representation, codec, mutation, inference, resource, localization, conformance]
                .into_iter()
                .try_fold(ArtifactDefinition::new(owner.clone()), |definition, capability| definition.capability(capability))
                .unwrap();

            assert_eq!(definition.capabilities().count(), 11);
            assert!(definition.validate().is_ok());
            assert_eq!(definition.capabilities().last().unwrap().identity().as_str(), "s.stdio.ifc.standard");
        }

        #[semio_framework_async_macros::async_test]
        async fn registry_rejects_duplicate_schema_dialect_codec_mime_and_extension_claims_atomically() {
            let owner_a = identity("s.stdio.ifc");
            let owner_b = identity("s.stdio.json");
            let namespaces = [ArtifactIdentityNamespace::schema(), ArtifactIdentityNamespace::dialect(), ArtifactIdentityNamespace::codec(), ArtifactIdentityNamespace::mime(), ArtifactIdentityNamespace::extension()];
            for (index, namespace) in namespaces.into_iter().enumerate() {
                let value = format!("shared-{index}");
                let first = ArtifactDefinition::new(owner_a.clone())
                    .capability(capability(&owner_a, &format!("first-{index}"), ArtifactCapabilityKind::resource()).claim(ArtifactIdentityClaim::new(namespace.clone(), value.clone()).unwrap()).unwrap())
                    .unwrap();
                let second = ArtifactDefinition::new(owner_b.clone()).capability(capability(&owner_b, &format!("second-{index}"), ArtifactCapabilityKind::resource()).claim(ArtifactIdentityClaim::new(namespace, value).unwrap()).unwrap()).unwrap();
                let mut registry = ArtifactDefinitionRegistry::new();
                registry.register(first).unwrap();
                let error = registry.register(second).unwrap_err();
                assert_eq!(error.code(), "artifact-definition.conflicting-claim");
                assert_eq!(registry.len(), 1);
            }
        }

        #[semio_framework_async_macros::async_test]
        async fn identities_and_locales_are_explicit_and_conflicts_do_not_overwrite() {
            assert!(ArtifactIdentity::parse("s.stdio..ifc").is_err());
            assert!(ArtifactLocale::parse("EN").is_err());
            let owner = identity("s.stdio.ifc");
            let localized = capability(&owner, "localized", ArtifactCapabilityKind::localization()).localization(ArtifactLocalization::new(ArtifactLocale::parse("en").unwrap(), "Ifc").unwrap()).unwrap();
            let duplicate = localized.clone().localization(ArtifactLocalization::new(ArtifactLocale::parse("en").unwrap(), "IFC").unwrap()).unwrap_err();
            assert_eq!(duplicate.code(), "artifact-definition.duplicate-locale");

            let mut registry = ArtifactDefinitionRegistry::new();
            registry.register(ArtifactDefinition::new(owner.clone()).capability(localized).unwrap()).unwrap();
            let error = registry.register(ArtifactDefinition::new(owner)).unwrap_err();
            assert_eq!(error.code(), "artifact-definition.conflicting-artifact");
            assert_eq!(registry.len(), 1);
        }
    }

    pub struct AppBuilder {
        id: String,
        label: LocalizedLabel,
        document: Vec<String>,
        icon_id: Option<IconName>,
        controller_id: String,
        modes: Vec<ModeSpec>,
        default_mode_id: Option<String>,
        window_kinds: Vec<WindowKindSpec>,
        panel_tabs: Vec<PanelTabSpec>,
        keybindings: Vec<KeybindingSpec>,
        actions: Vec<ActionDefinition>,
        utilities: Vec<UtilityDefinition>,
        interactions: Vec<InteractionDefinition>,
        tools: Vec<ToolDefinition>,
        commands: Vec<CommandDefinition>,
        named_layouts: Vec<NamedLayout>,
        default_layout: Option<WindowLayout>,
        terminologies: Vec<String>,
        terminology_breadcrumbs: HashMap<String, Vec<String>>,
        introduction: Option<IntroductionDefinition>,
        tutorials: Vec<TutorialDefinition>,
        dialogs: Vec<DialogDefinition>,
        artifact_kinds: Vec<ArtifactKindSpec>,
        media_inputs: Vec<MediaPortSpec>,
        media_outputs: Vec<MediaPortSpec>,
        config: ConfigSpec,
        command_grammar: CommandGrammar,
        io: AppIo,
    }

    impl AppBuilder {
        pub async fn new(id: impl Into<String>, label: impl Into<LocalizedLabel>) -> Self {
            let id = id.into();
            Self {
                controller_id: id.clone(),
                id,
                label: label.into(),
                document: Vec::new(),
                icon_id: None,
                modes: Vec::new(),
                default_mode_id: None,
                window_kinds: Vec::new(),
                panel_tabs: Vec::new(),
                keybindings: Vec::new(),
                actions: Vec::new(),
                utilities: Vec::new(),
                interactions: Vec::new(),
                tools: Vec::new(),
                commands: Vec::new(),
                named_layouts: Vec::new(),
                default_layout: None,
                terminologies: Vec::new(),
                terminology_breadcrumbs: HashMap::new(),
                introduction: None,
                tutorials: Vec::new(),
                dialogs: Vec::new(),
                artifact_kinds: Vec::new(),
                media_inputs: Vec::new(),
                media_outputs: Vec::new(),
                config: ConfigSpec::empty().await,
                command_grammar: CommandGrammar::empty().await,
                io: AppIo::default(),
            }
        }

        /// 🗂️ Declares one resource kind this app produces/consumes (see `ArtifactKindSpec`). Repeatable.
        pub async fn artifact_kind(mut self, spec: ArtifactKindSpec) -> Self {
            self.artifact_kinds.push(spec);
            self
        }

        /// 🧮️ Declares this app's typed configuration record (see `crate::ConfigSpec`).
        pub async fn config(mut self, spec: ConfigSpec) -> Self {
            self.config = spec;
            self
        }

        /// 🔌️ Declares this app's typed media I/O surface (see `crate::AppIo`).
        pub async fn io(mut self, io: AppIo) -> Self {
            self.io = io;
            self
        }

        /// 🎛️ Declares this app's typed binary command grammar (see `crate::CommandGrammar`).
        pub async fn command_grammar(mut self, grammar: CommandGrammar) -> Self {
            self.command_grammar = grammar;
            self
        }

        /// 🔌️ Declares one workflow input port this app accepts (see `MediaPortSpec`). Repeatable;
        /// validated in `build_definition` (non-empty/unique id, `direction` must be `In`).
        pub async fn media_input(mut self, spec: MediaPortSpec) -> Self {
            self.media_inputs.push(spec);
            self
        }

        /// 🔌️ Declares one workflow output port this app produces (see `MediaPortSpec`). Repeatable;
        /// validated in `build_definition` (non-empty/unique id, `direction` must be `Out`, `MediaForm::Any`
        /// is rejected — `Any` is only ever legal on the accepting/input side, see `media_types_compatible`).
        pub async fn media_output(mut self, spec: MediaPortSpec) -> Self {
            self.media_outputs.push(spec);
            self
        }

        /// 🗣️ Declares an alternative terminology id this app supports beyond the implicit "native" default.
        pub async fn terminology(mut self, id: impl Into<String>) -> Self {
            self.terminologies.push(id.into());
            self
        }

        /// 🗺️ Replaces the full document path (product + app segments) while terminology `id` is active;
        /// `id` must also be declared via `terminology` — validated in `build_definition`.
        pub async fn terminology_document(mut self, id: impl Into<String>, document: impl IntoIterator<Item = impl Into<String>>) -> Self {
            self.terminology_breadcrumbs.insert(id.into(), document.into_iter().map(Into::into).collect());
            self
        }

        /// @emoji 🎓️ Declares this app's first-run introduction walkthrough. Step anchors/advance
        /// conditions are validated against declared window kinds/utilities/actions/panel tabs in
        /// `build_definition`; declaring one auto-injects the `startIntroduction` action.
        pub async fn introduction(mut self, introduction: IntroductionDefinition) -> Self {
            self.introduction = Some(introduction);
            self
        }

        /// @emoji 🎬️ Declares one recorded, timed tutorial (repeatable — an app may offer several). Every
        /// track is validated in `build_definition` (`validate_tutorial` plus referenced action/command/
        /// utility/tool/element ids); declaring at least one auto-injects the `startTutorial` action. The
        /// `recordTutorial` action is injected unconditionally (see `record_tutorial_action_definition`).
        pub async fn tutorial(mut self, tutorial: TutorialDefinition) -> Self {
            self.tutorials.push(tutorial);
            self
        }

        /// @emoji 🗨️ Declares a modal form dialog (repeatable). `submit_action`/`cancel_action` and its
        /// `args` are validated in `build_definition`; opened only via `Effect::OpenDialog`.
        pub async fn dialog(mut self, dialog: DialogDefinition) -> Self {
            self.dialogs.push(dialog);
            self
        }

        pub async fn icon_id(mut self, icon_id: impl Into<IconName>) -> Self {
            self.icon_id = Some(icon_id.into());
            self
        }

        pub async fn document<I, S>(mut self, document: I) -> Self
        where
            I: IntoIterator<Item = S>,
            S: Into<String>,
        {
            self.document = document.into_iter().map(Into::into).collect();
            self
        }

        pub async fn mode(mut self, id: impl Into<String>, label: impl Into<LocalizedLabel>, icon_id: impl Into<IconName>) -> Self {
            self.modes.push(ModeSpec { id: id.into(), label: label.into(), icon_id: icon_id.into(), tools: Vec::new(), layout_id: None, commands: Vec::new() });
            self
        }

        /// 🎛️ Replaces the commands structurally owned by one mode.
        pub async fn mode_commands(mut self, mode_id: impl AsRef<str>, commands: Vec<CommandDefinition>) -> Self {
            let mode_id = mode_id.as_ref();
            if let Some(mode) = self.modes.iter_mut().find(|entry| entry.id == mode_id) {
                mode.commands = commands;
            }
            self
        }

        /// 🎛️ Adds one command definition to the mode that owns it.
        pub async fn mode_command(mut self, mode_id: impl AsRef<str>, command: CommandDefinition) -> Self {
            let mode_id = mode_id.as_ref();
            if let Some(mode) = self.modes.iter_mut().find(|entry| entry.id == mode_id) {
                mode.commands.push(command);
            }
            self
        }

        pub async fn mode_layout(mut self, mode_id: impl AsRef<str>, layout_id: impl Into<String>) -> Self {
            let mode_id = mode_id.as_ref();
            if let Some(mode) = self.modes.iter_mut().find(|entry| entry.id == mode_id) {
                mode.layout_id = Some(layout_id.into());
            }
            self
        }

        /// 🛠️ Scopes tools to a mode — references ids declared via `.tool()`/`.tool_simple()`. A tool is a
        /// mode-level activatable capability (e.g. puzzle3d fill); distinct from a window-scoped utility.
        pub async fn mode_tools(mut self, mode_id: impl AsRef<str>, tool_ids: Vec<ToolRef>) -> Self {
            let mode_id = mode_id.as_ref();
            if let Some(mode) = self.modes.iter_mut().find(|entry| entry.id == mode_id) {
                mode.tools = tool_ids;
            }
            self
        }

        pub async fn default_mode_id(mut self, id: impl Into<String>) -> Self {
            self.default_mode_id = Some(id.into());
            self
        }

        pub async fn window_kind(mut self, id: impl Into<String>, label: impl Into<LocalizedLabel>, body_key: impl Into<String>, surface_kind: SurfaceKind, icon_id: impl Into<IconName>) -> Self {
            self.window_kinds.push(WindowKindSpec {
                id: id.into(),
                label: label.into(),
                body_key: body_key.into(),
                surface_kind,
                icon_id: icon_id.into(),
                measures: Vec::new(),
                engagement: None,
                actions: Vec::new(),
                action_refs: Vec::new(),
                utilities: Vec::new(),
                interactions: Vec::new(),
                params_schema: None,
                artifact_snapshot_schema: None,
                input_event_schema: None,
                output_schema: None,
                capabilities: Vec::new(),
            });
            self
        }

        pub async fn window_kind_with_engagement(mut self, id: impl Into<String>, label: impl Into<LocalizedLabel>, body_key: impl Into<String>, surface_kind: SurfaceKind, engagement: WindowEngagement, icon_id: impl Into<IconName>) -> Self {
            self.window_kinds.push(WindowKindSpec {
                id: id.into(),
                label: label.into(),
                body_key: body_key.into(),
                surface_kind,
                icon_id: icon_id.into(),
                measures: Vec::new(),
                engagement: Some(engagement),
                actions: Vec::new(),
                action_refs: Vec::new(),
                utilities: Vec::new(),
                interactions: Vec::new(),
                params_schema: None,
                artifact_snapshot_schema: None,
                input_event_schema: None,
                output_schema: None,
                capabilities: Vec::new(),
            });
            self
        }

        /// @emoji 🧱️ Declares a mode from an already-built `ModeDefinition` — e.g. assembled by a taxonomy
        /// `🎭️modes/<mode>/🦀️component.rs` component file instead of the scalar `.mode(...)` args. Stored
        /// through the same `ModeSpec` pipeline as `.mode()`, so `.mode_commands()`/`.mode_tools()`/
        /// `.mode_layout()` still apply post-hoc and `build_definition`'s validation runs unchanged.
        pub async fn mode_def(mut self, def: ModeDefinition) -> Self {
            self.modes.push(mode_definition_to_spec(def).await);
            self
        }

        /// @emoji 🧱️ Declares a window kind from an already-built `WindowKindDefinition` — mirrors
        /// `.mode_def()`. `.window_kind_measures()`/`.window_kind_actions()`/`.window_kind_utilities()`/
        /// `.window_kind_interactions()`
        /// still apply post-hoc.
        pub async fn window_kind_def(mut self, def: WindowKindDefinition) -> Self {
            self.window_kinds.push(window_kind_definition_to_spec(def).await);
            self
        }

        /// @emoji 🧱️ Declares a (possibly nested) panel tab tree from an already-built `PanelTabDefinition`
        /// — mirrors `.panel_tab_tree()`, converting recursively through the same `PanelTabSpec` pipeline.
        pub async fn panel_tab_def(mut self, def: PanelTabDefinition) -> Self {
            self.panel_tabs.push(panel_tab_definition_to_spec(def).await);
            self
        }

        /// 🎛️ Attaches measure controls (sliders/selects/toggles/groups) to an already-declared window kind.
        pub async fn window_kind_measures(mut self, window_kind_id: impl AsRef<str>, measures: Vec<WindowMeasure>) -> Self {
            let window_kind_id = window_kind_id.as_ref();
            if let Some(window) = self.window_kinds.iter_mut().find(|entry| entry.id == window_kind_id) {
                window.measures = measures;
            }
            self
        }

        /// 📇️ Replaces the action definitions structurally owned by one window kind.
        pub async fn window_kind_actions(mut self, window_kind_id: impl AsRef<str>, actions: Vec<ActionDefinition>) -> Self {
            let window_kind_id = window_kind_id.as_ref();
            if let Some(window) = self.window_kinds.iter_mut().find(|entry| entry.id == window_kind_id) {
                window.actions = actions;
            }
            self
        }

        /// 📇️ Assigns centrally declared builder actions to one structural window owner.
        pub async fn window_kind_action_refs(mut self, window_kind_id: impl AsRef<str>, action_refs: Vec<ActionRef>) -> Self {
            let window_kind_id = window_kind_id.as_ref();
            if let Some(window) = self.window_kinds.iter_mut().find(|entry| entry.id == window_kind_id) {
                window.action_refs = action_refs;
            }
            self
        }

        /// 🧰️ Scopes utilities to a window kind — references ids declared via `.utility()`/`.utility_simple()`. Mirrors
        /// `window_kind_actions`: the referenced utility ids are validated to resolve in `build_definition`.
        pub async fn window_kind_utilities(mut self, window_kind_id: impl AsRef<str>, utility_ids: Vec<UtilityRef>) -> Self {
            let window_kind_id = window_kind_id.as_ref();
            if let Some(window) = self.window_kinds.iter_mut().find(|entry| entry.id == window_kind_id) {
                window.utilities = utility_ids;
            }
            self
        }

        /// 🕹️ Scopes declarative interaction domains to a window kind.
        pub async fn window_kind_interactions(mut self, window_kind_id: impl AsRef<str>, interaction_ids: Vec<InteractionRef>) -> Self {
            let window_kind_id = window_kind_id.as_ref();
            if let Some(window) = self.window_kinds.iter_mut().find(|entry| entry.id == window_kind_id) {
                window.interactions = interaction_ids;
            }
            self
        }

        pub async fn named_layout(mut self, layout: NamedLayout) -> Self {
            self.named_layouts.push(layout);
            self
        }

        pub async fn default_layout(mut self, layout: WindowLayout) -> Self {
            self.default_layout = Some(layout);
            self
        }

        pub async fn panel_tab(mut self, id: impl Into<String>, label: impl Into<LocalizedLabel>, group: PanelGroup, body_key: impl Into<String>) -> Self {
            self.panel_tabs.push(PanelTabSpec::leaf(id, label, group, body_key).await);
            self
        }

        /// 🌳️ Declares a root panel tab that may itself be a nested tree — build `tab` via `PanelTabSpec::leaf`/`PanelTabSpec::group`.
        pub async fn panel_tab_tree(mut self, tab: PanelTabSpec) -> Self {
            self.panel_tabs.push(tab);
            self
        }

        /// 🏛️ Declares a framework-predefined panel tab (workbench/display/details/settings category or
        /// leaf) — only the framework shell itself should call this; plugins must use `.panel_tab()`/`.panel_tab_tree()`.
        pub async fn panel_tab_framework(mut self, tab: PanelTabSpec) -> Self {
            self.panel_tabs.push(tab);
            self
        }

        pub async fn keybinding(mut self, keys: impl Into<String>, action: impl Into<String>) -> Self {
            self.keybindings.push(KeybindingSpec { keys: keys.into(), controller_id: self.controller_id.clone(), action: action.into() });
            self
        }

        /// @emoji ✏️ Declares a document-mutating action — dispatched as VCS operations with a true inverse.
        pub async fn mutation(self, id: impl Into<String>, label: impl Into<LocalizedLabel>) -> Self {
            self.action_with(ActionDefinition::new_catalog(id, label, ActionKind::Mutation).await).await
        }

        /// @emoji 👁️ Declares an ephemeral view action (camera, selection, hover, active utility) — not recorded in history.
        pub async fn view_action(self, id: impl Into<String>, label: impl Into<LocalizedLabel>) -> Self {
            self.action_with(ActionDefinition::new_catalog(id, label, ActionKind::View).await).await
        }

        /// @emoji 🐚️ Declares a shell-only effect action (navigate, export, spawn) — no document mutation.
        pub async fn shell_action(self, id: impl Into<String>, label: impl Into<LocalizedLabel>) -> Self {
            self.action_with(ActionDefinition::new_catalog(id, label, ActionKind::Shell).await).await
        }

        /// @emoji 📇️ Declares a fully specified action (icon, args, keybinding, palette visibility, category).
        pub async fn action_with(mut self, action: ActionDefinition) -> Self {
            self.actions.push(action);
            self
        }

        /// @emoji 📝️ Attaches typed argument declarations to an already-declared action (post-hoc, mirroring
        /// `window_kind_actions`). If the id isn't declared yet at call time the args are dropped; the
        /// mismatch surfaces in `build_definition`, which asserts every declared action's args are consistent.
        pub async fn action_args(mut self, action_id: impl AsRef<str>, args: Vec<ActionArgDef>) -> Self {
            let action_id = action_id.as_ref();
            if let Some(action) = self.actions.iter_mut().find(|entry| entry.id == action_id) {
                action.args = args;
            }
            self
        }

        /// @emoji 🎛️ Declares a fully specified app-owned command.
        pub async fn command(mut self, command: CommandDefinition) -> Self {
            self.commands.push(command);
            self
        }

        /// @emoji 🎛️ Declares an app-scope command (applies whenever this app is focused, in any mode).
        pub async fn app_command(self, id: impl Into<String>, label: impl Into<LocalizedLabel>, category: impl Into<String>, kind: ActionKind) -> Self {
            self.command(CommandDefinition::new_catalog(id, label, category, kind).await).await
        }

        /// @emoji 📝️ Attaches typed argument declarations to an already-declared command (post-hoc,
        /// mirroring `action_args`).
        pub async fn command_args(mut self, command_id: impl AsRef<str>, args: Vec<ActionArgDef>) -> Self {
            let command_id = command_id.as_ref();
            if let Some(command) = self.commands.iter_mut().find(|entry| entry.id == command_id) {
                command.args = args;
            }
            self
        }

        /// @emoji 🧰️ Declares an interactive utility this app exposes (referenced by `window_kind_utilities`).
        pub async fn utility(mut self, utility: UtilityDefinition) -> Self {
            self.utilities.push(utility);
            self
        }

        /// 🕹️ Declares a framework-managed hover and selection domain.
        pub async fn interaction(mut self, interaction: InteractionDefinition) -> Self {
            self.interactions.push(interaction);
            self
        }

        /// @emoji 🧰️ Declares a utility with default settings (no group/keys/cursor/category, gates actions while active).
        pub async fn utility_simple(self, id: impl Into<String>, label: impl Into<LocalizedLabel>, icon_id: impl Into<IconName>) -> Self {
            self.utility(UtilityDefinition::new(id, label, icon_id).await).await
        }

        /// @emoji 🛠️ Declares a mode-level tool this app exposes (referenced by `.mode_tools()`). Distinct
        /// from `.utility()`: a tool is scoped to a whole mode, not a window kind, and its live options are
        /// supplied dynamically via `ArtifactApp::tool_measures`/`PluginApp::tool_measures`.
        pub async fn tool(mut self, tool: ToolDefinition) -> Self {
            self.tools.push(tool);
            self
        }

        /// @emoji 🛠️ Declares a tool with default settings (no keybinding).
        pub async fn tool_simple(self, id: impl Into<String>, label: impl Into<LocalizedLabel>, icon_id: impl Into<IconName>) -> Self {
            self.tool(ToolDefinition::new(id, label, icon_id).await).await
        }

        /// @emoji 🧷️ Keybinding-vs-action-registry consistency is only enforced for apps that declare
        /// actions via `.mutation()`/`.view_action()`/`.shell_action()` — apps with an empty action
        /// registry keybind directly against controller actions instead, so there is nothing to check.
        pub async fn try_build_definition(mut self) -> Result<AppDefinition, PluginAssemblyError> {
            if !(!self.document.is_empty() && self.document.iter().all(|segment| !segment.trim().is_empty())) {
                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} document must contain non-empty segments", self.id)));
            }
            for (terminology_id, document) in &self.terminology_breadcrumbs {
                if !(self.terminologies.iter().any(|id| id == terminology_id)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} declares terminology_document for undeclared terminology {}", self.id, terminology_id)));
                }
                if !(!document.is_empty() && document.iter().all(|segment| !segment.trim().is_empty())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} terminology_document for {} must contain non-empty segments", self.id, terminology_id)));
                }
            }
            if !(!self.window_kinds.is_empty()) {
                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} must declare at least one window kind", self.id)));
            }
            if !(!self.modes.is_empty()) {
                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} must declare at least one mode", self.id)));
            }
            let mut window_kind_ids = HashSet::new();
            for window in &self.window_kinds {
                if !(!window.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind id must be non-empty", self.id)));
                }
                if !(!window.body_key.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} body_key must be non-empty", self.id, window.id)));
                }
                if !(window_kind_ids.insert(window.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate window kind id {}", self.id, window.id)));
                }
            }
            let mut panel_tab_ids = HashSet::new();
            for tab in &self.panel_tabs {
                validate_panel_tab_spec(&self.id, tab, &mut panel_tab_ids);
            }
            // 🕰️ Unlike Document/Catalogue/Inspection/Parameters (per-app content, opt-in via
            // `.panel_tab(...)`), the history panel's content is framework-generic (`HistoryView`), so
            // every app gets it unconditionally — unless it already declared the reserved id itself.
            if panel_tab_ids.insert(ui_wgpu::wgpu::FRAMEWORK_PANEL_TAB_HISTORY_ID.to_string()) {
                self.panel_tabs.push(PanelTabSpec::framework(
                    PanelTabKind::App(ui_wgpu::wgpu::FRAMEWORK_PANEL_TAB_HISTORY_ID.to_string()),
                    LocalizedLabel::native(ui_wgpu::wgpu::FRAMEWORK_PANEL_TAB_HISTORY_LABEL, "Verlauf"),
                    PanelGroup::Settings,
                    Some(FRAMEWORK_HISTORY_BODY_KEY.to_string()),
                    Vec::new(),
                ).await);
            }
            let mut layout_window_ids = Vec::new();
            if let Some(layout) = &self.default_layout {
                layout_window_ids.extend(collect_window_kind_ids_from_layout(layout));
            }
            for named in &self.named_layouts {
                layout_window_ids.extend(collect_window_kind_ids_from_layout(&named.layout));
            }
            for window_kind_id in layout_window_ids {
                if !(window_kind_ids.contains(&window_kind_id)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} layout references undeclared window kind {}", self.id, window_kind_id)));
                }
            }
            let default_mode_id = self.default_mode_id.clone().unwrap_or_else(|| self.modes[0].id.clone());
            if !(self.modes.iter().any(|mode| mode.id == default_mode_id)) {
                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} default_mode_id {} does not reference a declared mode", self.id, default_mode_id)));
            }
            let mut declared_action_ids = HashSet::new();
            for action in &self.actions {
                if !(declared_action_ids.insert(action.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate action id {}", self.id, action.id)));
                }
                validate_arg_defs(&self.id, &format!("action {}", action.id), &action.args);
            }
            let mut declared_utility_ids = HashSet::new();
            for utility in &self.utilities {
                if !(!utility.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} utility id must be non-empty", self.id)));
                }
                if !(declared_utility_ids.insert(utility.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate utility id {}", self.id, utility.id)));
                }
            }
            let mut declared_interaction_ids = HashSet::new();
            for interaction in &self.interactions {
                if !(!interaction.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction id must be non-empty", self.id)));
                }
                if !(declared_interaction_ids.insert(interaction.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate interaction id {}", self.id, interaction.id)));
                }
                if !(!interaction.granularities.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} must declare at least one granularity", self.id, interaction.id)));
                }
                if !(!interaction.selection.modes.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} must declare at least one selection mode", self.id, interaction.id)));
                }
                if !(!interaction.selection.methods.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} must declare at least one selection method", self.id, interaction.id)));
                }
                if !(!interaction.selection.merges.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} must declare at least one merge mode", self.id, interaction.id)));
                } // 🕹️ W3b: `transitive` (hover or selection) means "expand to descendant closure" — over
                  // `HierarchyProvider::Flat` there is no descendant relation to expand along at all, so a
                  // transitive `Flat` domain could only ever silently degrade to non-transitive behavior;
                  // reject it at build time instead.
                if !(!interaction.hover.transitive || !matches!(interaction.hierarchy, semio_framework::HierarchyProvider::Flat)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} declares hover.transitive with HierarchyProvider::Flat (transitive requires a real hierarchy)", self.id, interaction.id)));
                }
                if !(!interaction.selection.transitive || !matches!(interaction.hierarchy, semio_framework::HierarchyProvider::Flat)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} declares selection.transitive with HierarchyProvider::Flat (transitive requires a real hierarchy)", self.id, interaction.id)));
                }
            }
            let mut declared_tool_ids = HashSet::new();
            for tool in &self.tools {
                if !(!tool.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} tool id must be non-empty", self.id)));
                }
                if !(declared_tool_ids.insert(tool.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate tool id {}", self.id, tool.id)));
                }
            }
            let mut declared_command_ids = HashSet::new();
            for command in &self.commands {
                if !(!command.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} command id must be non-empty", self.id)));
                }
                if !(declared_command_ids.insert(command.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate app command id {}", self.id, command.id)));
                }
                validate_arg_defs(&self.id, &format!("command {}", command.id), &command.args);
            }
            let app_declared_actions = !self.actions.is_empty();
            let mut actions = self.actions;
            for history_action in history_action_definitions() {
                if declared_action_ids.insert(history_action.id.clone()) {
                    actions.push(history_action);
                }
            }
            for clipboard_action in clipboard_action_definitions() {
                if declared_action_ids.insert(clipboard_action.id.clone()) {
                    actions.push(clipboard_action);
                }
            }
            if !self.utilities.is_empty() && declared_action_ids.insert(SET_ACTIVE_UTILITY_ACTION_ID.to_string()) {
                actions.push(set_active_utility_action_definition().await);
            }
            if !self.tools.is_empty() && declared_action_ids.insert(SET_ACTIVE_TOOL_ACTION_ID.to_string()) {
                actions.push(set_active_tool_action_definition().await);
            }
            if self.introduction.is_some() && declared_action_ids.insert(START_INTRODUCTION_ACTION_ID.to_string()) {
                actions.push(start_introduction_action_definition().await);
            }
            if !self.tutorials.is_empty() && declared_action_ids.insert(START_TUTORIAL_ACTION_ID.to_string()) {
                actions.push(start_tutorial_action_definition(&self.tutorials).await);
            }
            if declared_action_ids.insert(RECORD_TUTORIAL_ACTION_ID.to_string()) {
                actions.push(record_tutorial_action_definition().await);
            }
            if declared_action_ids.insert(SET_HISTORY_COMMAND_FILTER_ACTION_ID.to_string()) {
                actions.push(set_history_command_filter_action_definition().await);
            }
            if declared_action_ids.insert(NOTE_SHELL_COMMAND_ACTION_ID.to_string()) {
                actions.push(note_shell_command_action_definition().await);
            }
            let explicitly_owned_action_ids: HashSet<String> = self.window_kinds.iter().flat_map(|window| window.actions.iter().map(|action| action.id.clone()).chain(window.action_refs.iter().map(|action| action.as_str().to_string()))).collect();
            for window in &mut self.window_kinds {
                for action_ref in &window.action_refs {
                    let action = actions
                        .iter()
                        .find(|action| action.id == action_ref.as_str())
                        .ok_or_else(|| PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} references undeclared action {}", self.id, window.id, action_ref.as_str())))?;
                    window.actions.push(action.clone());
                }
                let mut window_action_ids = HashSet::new();
                for action in &window.actions {
                    if !(!action.id.trim().is_empty()) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} action id must be non-empty", self.id, window.id)));
                    }
                    if !(window_action_ids.insert(action.id.clone())) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} duplicate action id {}", self.id, window.id, action.id)));
                    }
                    declared_action_ids.insert(action.id.clone());
                    validate_arg_defs(&self.id, &format!("window kind {} action {}", window.id, action.id), &action.args);
                }
                for action in &actions {
                    if !explicitly_owned_action_ids.contains(&action.id) {
                        window.actions.push(action.clone());
                    }
                }
            }
            let mut bound_keys: HashSet<String> = self.keybindings.iter().map(|binding| binding.keys.clone()).collect();
            let mut keybindings: Vec<Keybinding> = self.keybindings.into_iter().map(|binding| Keybinding { keys: binding.keys, action: ActionDescriptor { controller_id: binding.controller_id, action: binding.action, args: None } }).collect();
            for history_action in actions.iter().filter(|action| matches!(action.kind, ActionKind::History | ActionKind::Clipboard)) {
                if let Some(keys) = &history_action.keys {
                    if bound_keys.insert(keys.clone()) {
                        keybindings.push(Keybinding { keys: keys.clone(), action: ActionDescriptor { controller_id: self.controller_id.clone(), action: history_action.id.clone(), args: None } });
                    }
                }
            }
            for utility in &self.utilities {
                if let Some(keys) = &utility.keys {
                    if bound_keys.insert(keys.clone()) {
                        keybindings.push(Keybinding {
                            keys: keys.clone(),
                            action: ActionDescriptor { controller_id: self.controller_id.clone(), action: SET_ACTIVE_UTILITY_ACTION_ID.to_string(), args: Some(DslValue::Object(vec![("utilityId".into(), DslValue::String(utility.id.clone()))])) },
                        });
                    }
                }
            }
            for tool in &self.tools {
                if let Some(keys) = &tool.keys {
                    if bound_keys.insert(keys.clone()) {
                        keybindings.push(Keybinding {
                            keys: keys.clone(),
                            action: ActionDescriptor { controller_id: self.controller_id.clone(), action: SET_ACTIVE_TOOL_ACTION_ID.to_string(), args: Some(DslValue::Object(vec![("toolId".into(), DslValue::String(tool.id.clone()))])) },
                        });
                    }
                }
            }
            if app_declared_actions {
                for binding in &keybindings {
                    if !(declared_action_ids.contains(&binding.action.action)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} keybinding {} references undeclared action {}", self.id, binding.keys, binding.action.action)));
                    }
                }
            }
            for window in &self.window_kinds {
                for utility_ref in &window.utilities {
                    let utility_ref_str = utility_ref.as_str().await;
                    if !(declared_utility_ids.contains(utility_ref_str)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} references undeclared utility {}", self.id, window.id, utility_ref_str)));
                    }
                }
                for interaction_ref in &window.interactions {
                    let interaction_ref_str = interaction_ref.as_str().await;
                    if !(declared_interaction_ids.contains(interaction_ref_str)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} references undeclared interaction {}", self.id, window.id, interaction_ref_str)));
                    }
                }
            }
            for mode in &self.modes {
                let mut mode_command_ids = HashSet::new();
                for command in &mode.commands {
                    if !(!command.id.trim().is_empty()) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} mode {} command id must be non-empty", self.id, mode.id)));
                    }
                    if !(mode_command_ids.insert(command.id.clone())) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} mode {} duplicate command id {}", self.id, mode.id, command.id)));
                    }
                    declared_command_ids.insert(command.id.clone());
                    validate_arg_defs(&self.id, &format!("mode {} command {}", mode.id, command.id), &command.args);
                }
                for tool_ref in &mode.tools {
                    if !(declared_tool_ids.contains(tool_ref.as_str())) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} mode {} references undeclared tool {}", self.id, mode.id, tool_ref.as_str())));
                    }
                }
            }
            let mode_referenced_tools: HashSet<&str> = self.modes.iter().flat_map(|mode| mode.tools.iter().map(|tool_ref| tool_ref.as_str())).collect();
            for tool in &self.tools {
                if !(mode_referenced_tools.contains(tool.id.as_str())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} tool {} is not referenced by any mode", self.id, tool.id)));
                }
            }
            if let Some(introduction) = &self.introduction {
                if !(!introduction.steps.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction must declare at least one step", self.id)));
                }
                let mut step_ids = HashSet::new();
                for step in &introduction.steps {
                    if !(!step.id.trim().is_empty()) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step id must be non-empty", self.id)));
                    }
                    if !(step_ids.insert(step.id.clone())) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate introduction step id {}", self.id, step.id)));
                    }
                    let validate_element_id = |id: &str, role: &str| validate_referenced_element_id(&self.id, &format!("introduction step {}", step.id), role, id, &declared_utility_ids, &panel_tab_ids, &window_kind_ids);
                    if let Some(id) = &step.introduce {
                        validate_element_id(id, "introduce").await;
                    }
                    for id in &step.show {
                        validate_element_id(id, "show").await;
                    }
                    for interaction in &step.interactions {
                        if !(!interaction.label.trim().is_empty()) {
                            return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction has an empty label", self.id, step.id)));
                        }
                        match &interaction.on {
                            IntroductionInteractionKind::Action(action_ref) => {
                                let action_ref_str = action_ref.as_str().await;
                                if !(declared_action_ids.contains(action_ref_str)) {
                                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction references undeclared action {}", self.id, step.id, action_ref_str)));
                                }
                            }
                            IntroductionInteractionKind::Utility(utility_ref) => {
                                let utility_ref_str = utility_ref.as_str().await;
                                if !(declared_utility_ids.contains(utility_ref_str)) {
                                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction references undeclared utility {}", self.id, step.id, utility_ref_str)));
                                }
                            }
                            IntroductionInteractionKind::Tool(tool_ref) => {
                                let tool_ref_str = tool_ref.as_str().await;
                                if !(declared_tool_ids.contains(tool_ref_str)) {
                                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction references undeclared tool {}", self.id, step.id, tool_ref_str)));
                                }
                            }
                            IntroductionInteractionKind::Panel(panel_tab_id) => validate_element_id(panel_tab_id, "interaction.panel").await,
                            IntroductionInteractionKind::Expand(tree_id) => validate_element_id(tree_id, "interaction.expand").await,
                            IntroductionInteractionKind::Pan(window_kind_id) | IntroductionInteractionKind::Zoom(window_kind_id) | IntroductionInteractionKind::Orbit(window_kind_id) => {
                                if !(window_kind_ids.contains(window_kind_id)) {
                                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction references undeclared window kind {}", self.id, step.id, window_kind_id)));
                                }
                            }
                        }
                    }
                }
            }
            let mut tutorial_ids = HashSet::new();
            for tutorial in &self.tutorials {
                if !(!tutorial.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} tutorial id must be non-empty", self.id)));
                }
                if !(tutorial_ids.insert(tutorial.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate tutorial id {}", self.id, tutorial.id)));
                }
                if let Err(reason) = semio_framework::validate_tutorial(tutorial).await {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} tutorial {} failed validation: {}", self.id, tutorial.id, reason)));
                }
                let owner = format!("tutorial {}", tutorial.id);
                let mut ui_changes: Vec<&semio_framework::TutorialUiChange> = Vec::new();
                for keyframe in &tutorial.tracks.ui {
                    if let semio_framework::TutorialUiSample::Delta { changes } = &keyframe.sample {
                        ui_changes.extend(changes.iter());
                    }
                }
                for change in ui_changes {
                    match change {
                        semio_framework::TutorialUiChange::ActiveUtility { utility_id: Some(utility_id), .. } => {
                            if !(declared_utility_ids.contains(utility_id)) {
                                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} references undeclared utility {}", self.id, owner, utility_id)));
                            }
                        }
                        semio_framework::TutorialUiChange::ActiveTool { id: Some(tool_id) } => {
                            if !(declared_tool_ids.contains(tool_id)) {
                                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} references undeclared tool {}", self.id, owner, tool_id)));
                            }
                        }
                        _ => {}
                    }
                }
                for utility_id in tutorial.base.ui.active_utility_by_window_id.values() {
                    if !(declared_utility_ids.contains(utility_id)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} base.ui references undeclared utility {}", self.id, owner, utility_id)));
                    }
                }
                if let Some(tool_id) = &tutorial.base.ui.active_tool_id {
                    if !(declared_tool_ids.contains(tool_id)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} base.ui references undeclared tool {}", self.id, owner, tool_id)));
                    }
                }
                for event in &tutorial.tracks.events {
                    match &event.kind {
                        semio_framework::TutorialEventKind::Action { action, .. } => {
                            if !(declared_action_ids.contains(action)) {
                                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} event references undeclared action {}", self.id, owner, action)));
                            }
                        }
                        semio_framework::TutorialEventKind::Command { command, .. } => {
                            if !(declared_command_ids.contains(command)) {
                                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} event references undeclared command {}", self.id, owner, command)));
                            }
                        }
                        semio_framework::TutorialEventKind::Key { .. } => {}
                    }
                }
                for gesture_cue in &tutorial.tracks.gestures {
                    for point in introduction_gesture_points(&gesture_cue.gesture) {
                        if let semio_framework::IntroductionPoint::Element { id, .. } = point {
                            validate_referenced_element_id(&self.id, &owner, "gesture", id, &declared_utility_ids, &panel_tab_ids, &window_kind_ids).await;
                        }
                    }
                }
            }
            let mut dialog_ids = HashSet::new();
            for dialog in &self.dialogs {
                if !(!dialog.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} dialog id must be non-empty", self.id)));
                }
                if !(dialog_ids.insert(dialog.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate dialog id {}", self.id, dialog.id)));
                }
                if !(declared_action_ids.contains(dialog.submit_action.as_str().await)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} dialog {} submit_action references undeclared action {}", self.id, dialog.id, dialog.submit_action.as_str())));
                }
                if let Some(cancel_action) = &dialog.cancel_action {
                    if !(declared_action_ids.contains(cancel_action.as_str().await)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} dialog {} cancel_action references undeclared action {}", self.id, dialog.id, cancel_action.as_str())));
                    }
                }
                validate_arg_defs(&self.id, &format!("dialog {}", dialog.id), &dialog.args);
            }
            let mut media_port_ids = HashSet::new();
            for port in self.media_inputs.iter().chain(self.media_outputs.iter()) {
                if !(!port.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} media port id must be non-empty", self.id)));
                }
                if !(media_port_ids.insert(port.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate media port id {}", self.id, port.id)));
                }
            }
            for port in &self.media_inputs {
                if !(port.direction == MediaPortDirection::In) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} media input {} must declare direction In", self.id, port.id)));
                }
            }
            for port in &self.media_outputs {
                if !(port.direction == MediaPortDirection::Out) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} media output {} must declare direction Out", self.id, port.id)));
                }
                if !(!matches!(port.media_type.form, MediaForm::Any)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} media output {} must not declare MediaForm::Any (Any is only legal on inputs, see media_types_compatible)", self.id, port.id)));
                }
            }
            let (dialect, role) = semio_framework::parse_surface_app_id(&self.id).await.map_err(|error| PluginAssemblyError::new("app-definition.invalid", format!("app id {} must be a canonical surface id: {error}", self.id)))?;
            let mut definition = AppDefinition {
                id: self.id,
                role,
                dialect,
                label: self.label,
                breadcrumb: self.document,
                icon_id: self.icon_id,
                controller_id: self.controller_id,
                modes: Modes::try_from(self.modes.into_iter().map(|mode| ModeDefinition { id: mode.id, label: mode.label, icon_id: mode.icon_id, tools: mode.tools, layout_id: mode.layout_id, commands: mode.commands }).collect::<Vec<_>>())
                    .map_err(|_| PluginAssemblyError::new("app-definition.invalid", "app definition must declare at least one mode (checked above)"))?,
                default_mode_id,
                window_kinds: WindowKinds::try_from(
                    self.window_kinds
                        .into_iter()
                        .map(|window| WindowKindDefinition {
                            id: window.id,
                            label: window.label,
                            body_key: window.body_key,
                            surface_kind: window.surface_kind,
                            icon_id: window.icon_id,
                            options: WindowOptions { measures: window.measures, engagement: window.engagement.map_or(WindowEngagementSlot::None, WindowEngagementSlot::Some) },
                            actions: window.actions,
                            utilities: window.utilities,
                            interactions: window.interactions,
                            params_schema: window.params_schema,
                            artifact_snapshot_schema: window.artifact_snapshot_schema,
                            input_event_schema: window.input_event_schema,
                            output_schema: window.output_schema,
                            capabilities: window.capabilities,
                        })
                        .collect::<Vec<_>>(),
                )
                .map_err(|_| PluginAssemblyError::new("app-definition.invalid", "app definition must declare at least one window kind (checked above)"))?,
                panel_tabs: self.panel_tabs.into_iter().map(panel_tab_spec_to_definition).collect(),
                keybindings,
                utilities: self.utilities,
                interactions: self.interactions,
                tools: self.tools,
                commands: self.commands,
                named_layouts: self.named_layouts,
                default_layout: self.default_layout,
                terminologies: self.terminologies,
                terminology_breadcrumbs: self.terminology_breadcrumbs,
                introduction: self.introduction,
                tutorials: self.tutorials,
                dialogs: self.dialogs,
                media_inputs: self.media_inputs,
                media_outputs: self.media_outputs,
                artifact_kinds: self.artifact_kinds,
                config: self.config,
                command_grammar: self.command_grammar,
                io: self.io,
            };
            for action in semio_framework::interaction_action_definitions(&definition) {
                if declared_action_ids.insert(action.id.clone()) {
                    if let Some(keys) = &action.keys {
                        if bound_keys.insert(keys.clone()) {
                            definition.keybindings.push(Keybinding { keys: keys.clone(), action: ActionDescriptor { controller_id: definition.controller_id.clone(), action: action.id.clone(), args: None } });
                        }
                    }
                    for window in definition.window_kinds.iter_mut() {
                        if !window.actions.iter().any(|entry| entry.id == action.id) {
                            window.actions.push(action.clone());
                        }
                    }
                }
            }
            Ok(definition)
        }

        /// 🧷️ Panicking convenience wrapper over `try_build_definition` for callers that construct
        /// `AppDefinition`s from static, author-controlled data (the overwhelming majority) and are
        /// not yet migrated onto the fallible path — a malformed definition here is a programming
        /// error, not runtime user input, and existing tests already assert on the panic message.
        /// Plugin `plugin()` entry points that assemble an `AppDefinition` from anything that could
        /// legitimately fail at runtime should call `try_build_definition` directly and propagate the
        /// `PluginAssemblyError` via `?` instead — see `✏️s/🔌️plugins/📖️playbook/🧩️extensions/🌀️procedural/🦀️component.rs`.
        pub async fn build_definition(self) -> AppDefinition {
            self.try_build_definition().await.unwrap_or_else(|error| panic!("{error}"))
        }
    }

    //#region 🔖️PanelKit
    // 🌳️ Shared panel-tree builders — lifts the verbatim-duplicated `tree_item*`/`selection_ids` helpers
    // and the `build_document_tree`/`build_inspector_tree`/`build_catalogue_tree` skeleton found across
    // ~15 plugin crates (flow, procedural, layout, gis, puzzle, sequence, trinity, dag, …) into the SDK.

    /// 🌳️ A bare tree item — thin wrapper over `UiTreeItemNode::base`.
    pub async fn tree_item(id: impl Into<String>, label: impl Into<Label>) -> UiTreeItemNode {
        UiTreeItemNode::base(id, label).await
    }

    /// 🌳️ A tree item with a description line.
    pub async fn tree_item_desc(id: impl Into<String>, label: impl Into<Label>, description: Option<String>) -> UiTreeItemNode {
        UiTreeItemNode { description, menu: None, ..UiTreeItemNode::base(id, label).await }
    }

    /// 🌳️ A tree item that dispatches `action` on click.
    pub async fn tree_item_with_action(id: impl Into<String>, label: impl Into<Label>, description: Option<String>, action: ActionDescriptor) -> UiTreeItemNode {
        UiTreeItemNode { description, action: Some(action), menu: None, ..UiTreeItemNode::base(id, label).await }
    }

    /// 🌳️ A draggable tree item: `drag_data` is a JSON object whose entries become the item's
    /// MIME-type -> payload drag-data map (string values are used verbatim; non-string values are
    /// serialized), e.g. `json!({ "application/x-my-widget": descriptor.to_string() })`. Generalizes the
    /// single-hardcoded-MIME-key pattern duplicated per app (each app previously baked its own MIME
    /// constant into this function) — the caller now supplies the key(s) explicitly.
    pub async fn tree_item_with_action_draggable(id: impl Into<String>, label: impl Into<Label>, description: Option<String>, action: ActionDescriptor, drag_data: &Value) -> UiTreeItemNode {
        let mut item = tree_item_with_action(id, label, description, action).await;
        item.draggable = Some(true);
        item.drag_data = drag_data.as_object().map(|entries| entries.iter().map(|(key, value)| (key.clone(), value.as_str().map(str::to_string).unwrap_or_else(|| value.to_string()))).collect());
        item
    }

    /// 🎯️ Parses a selection-action's `ids` array arg into a plain `Vec<String>` — the shape used by the
    /// majority of duplicate copies (`layout`, `gis`, `presentation`, …). A handful of apps additionally
    /// fall back to a singular `id`/`nodeId`/`nodeIds` key (`puzzle`, `sequence`, `trinity`, `procedural`,
    /// `mindmap`); those apps keep their own fallback wrapper around this shared core for now.
    pub async fn selection_ids(args: Option<&Value>) -> Vec<String> {
        args.and_then(|value| value.get("ids")).and_then(|value| serde_json::from_value(value.clone()).ok()).unwrap_or_default()
    }

    /// 🌳️ Fluent builder for the `build_document_tree`/`build_inspector_tree`/`build_catalogue_tree`
    /// skeleton duplicated across plugin crates: namespaced item ids, sections (optionally substituting a
    /// single "(none)" placeholder item for the empty state), a selected/highlighted id set (stamped as
    /// item `presence` via `ui_tree_stamp_presence`), an `interaction_domain` binding, and a drop action —
    /// ending in `.build()` -> a `UiNode::Tree`.
    pub struct PanelTreeBuilder {
        namespace: String,
        sections: Vec<UiTreeSectionNode>,
        selected_ids: Option<Vec<String>>,
        highlighted_ids: Option<Vec<String>>,
        interaction_domain: Option<String>,
        drop_action: Option<ActionDescriptor>,
    }

    impl PanelTreeBuilder {
        /// 🌳️ `namespace` prefixes every id built via `.item_id()`, e.g. `"flow-play-document"`.
        pub async fn new(namespace: impl Into<String>) -> Self {
            Self { namespace: namespace.into(), sections: Vec::new(), selected_ids: None, highlighted_ids: None, interaction_domain: None, drop_action: None }
        }

        /// 🌳️ Builds a namespaced item id: `"{namespace}.{kind}.{id}"`.
        pub async fn item_id(&self, kind: &str, id: &str) -> String {
            format!("{}.{kind}.{id}", self.namespace)
        }

        /// 🌳️ Adds a section verbatim.
        pub async fn section(mut self, id: impl Into<String>, label: Option<Label>, default_open: bool, items: Vec<UiTreeItemNode>) -> Self {
            self.sections.push(UiTreeSectionNode { id: id.into(), label, default_open: Some(default_open), presence: UiPresence::default(), items });
            self
        }

        /// 🌳️ Adds a section, substituting a single "(none)"-style placeholder item when `items` is empty —
        /// the empty-state pattern duplicated in `build_document_tree`/`build_catalogue_tree` across apps.
        pub async fn section_or_placeholder(mut self, id: impl Into<String>, label: Option<Label>, default_open: bool, items: Vec<UiTreeItemNode>, placeholder_label: impl Into<Label>) -> Self {
            let id = id.into();
            let items = if items.is_empty() { vec![tree_item(format!("{id}.empty"), placeholder_label)] } else { items };
            self.sections.push(UiTreeSectionNode { id, label, default_open: Some(default_open), presence: UiPresence::default(), items });
            self
        }

        pub async fn selected(mut self, ids: Vec<String>) -> Self {
            self.selected_ids = Some(ids);
            self
        }

        pub async fn highlighted(mut self, ids: Vec<String>) -> Self {
            self.highlighted_ids = Some(ids);
            self
        }

        /// 🕹️ Binds the built tree to an app-declared `InteractionDefinition` domain id — the framework
        /// then owns this domain's selection/hover, replacing the deleted per-app `selection_change` action.
        pub async fn interaction_domain(mut self, id: impl Into<String>) -> Self {
            self.interaction_domain = Some(id.into());
            self
        }

        pub async fn drop_action(mut self, action: ActionDescriptor) -> Self {
            self.drop_action = Some(action);
            self
        }

        pub async fn build(mut self) -> UiNode {
            let selected = self.selected_ids.iter().flatten().cloned().collect::<HashSet<_>>();
            let highlighted = self.highlighted_ids.iter().flatten().cloned().collect::<HashSet<_>>();
            // 👥️ No roster/own-color context at this app-facing builder layer — `color`/`peers` stay
            // at their defaults here; `stamp_and_cache_interaction_ui` OVERWRITES this whole tree's
            // presence (including these two fields) once it is bound to a live `interaction_domain`.
            ui_tree_stamp_presence(&mut self.sections, &selected, &highlighted, None, &|_id: &str| Vec::new());
            UiNode::Tree(UiTreeNode { sections: self.sections, presence: UiPresence::default(), interaction_domain: self.interaction_domain, drop_action: self.drop_action, menu: None })
        }
    }

    #[cfg(test)]
    mod panel_kit_tests {
        use super::*;
        use ui_wgpu::wgpu::Label;

        #[semio_framework_async_macros::async_test]
        async fn tree_item_builds_a_bare_item() {
            let item = tree_item("ns.kind.a", Label::data("A").await);
            assert_eq!(item.id, "ns.kind.a");
            assert_eq!(item.label.as_str(), "A");
            assert!(item.description.is_none());
            assert!(item.action.is_none());
        }

        #[semio_framework_async_macros::async_test]
        async fn tree_item_with_action_draggable_maps_json_object_to_string_drag_data() {
            let action = ActionDescriptor { controller_id: "app".into(), action: "addWidget".into(), args: None };
            let item = tree_item_with_action_draggable("ns.kind.a", Label::data("A").await, None, action, &serde_json::json!({ "application/x-widget": "{\"kind\":\"a\"}" }));
            assert_eq!(item.draggable, Some(true));
            assert_eq!(item.drag_data.unwrap().get("application/x-widget").map(String::as_str), Some("{\"kind\":\"a\"}"));
        }

        #[semio_framework_async_macros::async_test]
        async fn selection_ids_reads_the_ids_array_arg() {
            let args = serde_json::json!({ "ids": ["a", "b"] });
            assert_eq!(selection_ids(Some(&args)), vec!["a".to_string(), "b".to_string()]);
            assert!(selection_ids(None).is_empty());
        }

        #[semio_framework_async_macros::async_test]
        async fn panel_tree_builder_produces_a_namespaced_tree_with_placeholder() {
            let builder = PanelTreeBuilder::new("ns-play-document");
            let item_id = builder.item_id("widget", "w1");
            assert_eq!(item_id, "ns-play-document.widget.w1");
            let node = builder
                .section("ns-play-document.widgets", Some(Label::data("Widgets").await), true, vec![tree_item(item_id, Label::data("W1").await)])
                .section_or_placeholder("ns-play-document.synapses", Some(Label::data("Synapses").await), false, vec![], Label::data("(none)").await)
                .selected(vec!["ns-play-document.widget.w1".into()])
                .interaction_domain("ns-play-document")
                .build();
            let UiNode::Tree(tree) = node else { panic!("expected a Tree node") };
            assert_eq!(tree.sections.len(), 2);
            assert_eq!(tree.sections[0].items.len(), 1);
            assert_eq!(tree.sections[1].items[0].label.as_str(), "(none)");
            assert!(tree.sections[0].items[0].presence.selected, "the .selected(...) id must be stamped as selected presence on its matching item");
            assert_eq!(tree.interaction_domain.as_deref(), Some("ns-play-document"));
        }
    }
    //#endregion 🔖️PanelKit

    //#region 🔖️FormKit
    // 📋️ Shared form-panel builder — lifts the `Section > labeled Field rows > submit Button` skeleton
    // (and the sibling `entity_detail` read-only `KeyValue` summary block) duplicated across plugin crates
    // that render declarative forms/detail panels, mirroring `PanelTreeBuilder`'s namespaced builder-pattern
    // shape above (`namespace` prefixes every id, method chaining ends in `.build() -> UiNode`).

    /// 📋️ Fluent builder for a `Section` of labeled `Field` rows ending in an optional submit `Button` —
    /// same namespaced-id / method-chaining shape as `PanelTreeBuilder`.
    pub struct FormPanelBuilder {
        namespace: String,
        fields: Vec<UiNode>,
        submit: Option<UiButtonNode>,
    }

    impl FormPanelBuilder {
        /// 📋️ `namespace` prefixes every field id built via `.field_id()`/`.field()`/`.from_dictionary()`.
        pub async fn new(namespace: impl Into<String>) -> Self {
            Self { namespace: namespace.into(), fields: Vec::new(), submit: None }
        }

        /// 📋️ Builds a namespaced field id: `"{namespace}.field.{id}"` — mirrors `PanelTreeBuilder::item_id`.
        pub async fn field_id(&self, id: &str) -> String {
            format!("{}.field.{id}", self.namespace)
        }

        /// 📋️ Adds one labeled field row: `control` wraps into a `UiFieldNode` via `ui_control_to_node`.
        pub async fn field(mut self, id: &str, label: impl Into<Label>, description: Option<String>, control: UiControlNode) -> Self {
            let field_id = self.field_id(id);
            self.fields.push(UiNode::Field(UiFieldNode { id: field_id.await, label: label.into(), description, required: None, error: None, child: Box::new(ui_control_to_node(control).await), presence: UiPresence::default(), menu: None }));
            self
        }

        /// 📋️ Routes the OS `form.dictionary` resource shape (see the `ArtifactKindSpec { id:
        /// "form.dictionary", source_format: "forms.dictionary", .. }` registered by `forms/plugin`'s
        /// `create_forms_app`) into a sequence of text-input field rows: each top-level entry in the
        /// `dictionary_json` array — `{ "id", "label"?, "description"?, "value"? }` — becomes one field
        /// dispatching the shared `on_change` action (its `args` are left to the caller; the emitted input's
        /// own id already carries which field changed).
        pub async fn from_dictionary(mut self, dictionary_json: &Value, on_change: ActionDescriptor) -> Self {
            let Some(entries) = dictionary_json.as_array() else { return self };
            for entry in entries {
                let Some(id) = entry.get("id").and_then(Value::as_str) else { continue };
                // 📊️ Field labels here come from a runtime `dictionary_json` resource, not a static bundle.
                let label = Label::data(entry.get("label").and_then(Value::as_str).unwrap_or(id).to_string()).await;
                let description = entry.get("description").and_then(Value::as_str).map(str::to_string);
                let value = entry.get("value").and_then(Value::as_str).unwrap_or_default().to_string();
                let field_id = self.field_id(id);
                let control = UiControlNode::Input(UiInputNode {
                    id: field_id.await,
                    input_kind: "text".into(),
                    value,
                    placeholder: None,
                    commit: None,
                    min: None,
                    max: None,
                    step: None,
                    accept: None,
                    on_change: on_change.clone(),
                    presence: UiPresence::default(),
                    menu: None,
                });
                self = self.field(id, label, description, control).await;
            }
            self
        }

        /// 📋️ Sets the trailing submit `Button` row.
        pub async fn submit(mut self, label: impl Into<Label>, action: ActionDescriptor) -> Self {
            self.submit = Some(UiButtonNode { id: Some(self.field_id("submit").await), icon_id: IconName::CircleDot, label: label.into(), action, style: None, presence: UiPresence::default(), menu: None });
            self
        }

        /// 📋️ Builds `Section > Fields > Button` — the section id is the builder's namespace.
        pub async fn build(self) -> UiNode {
            let mut children = self.fields;
            if let Some(submit) = self.submit {
                children.push(UiNode::Button(submit));
            }
            UiNode::Section(UiSectionNode { id: self.namespace, label: None, default_open: Some(true), presence: UiPresence::default(), children, menu: None })
        }
    }

    /// 📋️ A read-only entity-detail panel: `title`/`subtitle` header text, a `KeyValue` summary block built
    /// from `entries` (reusing `ui_wgpu`'s existing `UiKeyValueEntry` rather than a duplicate local type),
    /// and trailing action buttons.
    pub async fn entity_detail(title: impl Into<Label>, subtitle: Option<Label>, entries: Vec<UiKeyValueEntry>, actions: Vec<UiButtonNode>) -> UiNode {
        let mut children = vec![ui_text(title).await];
        if let Some(subtitle) = subtitle {
            children.push(ui_text(subtitle).await);
        }
        children.push(UiNode::KeyValue(UiKeyValueNode { entries, presence: UiPresence::default(), menu: None }));
        children.extend(actions.into_iter().map(UiNode::Button));
        ui_stack_vertical(children).await
    }

