    //#region 📚️ExampleSource
    /// 📚️ Value type exported by an example definition leaf (`📚️examples/<slug>/🦀️component.rs`):
    /// stable id, localized label, icon, and document/payload accessors — converts into
    /// [`ExampleDefinition`] for [`PluginManifest::examples`].
    #[derive(Clone, Debug, PartialEq)]
    pub struct ExampleSource {
        id: String,
        label: LocalizedLabel,
        icon_id: IconName,
        document_json: String,
    }

    impl ExampleSource {
        /// 🧱 Builds an example source from id, label, document payload, and icon.
        pub async fn new(id: impl Into<String>, label: impl Into<LocalizedLabel>, document_json: impl Into<String>, icon_id: impl Into<IconName>) -> Self {
            Self { id: id.into(), label: label.into(), icon_id: icon_id.into(), document_json: document_json.into() }
        }

        /// 🏷️ Stable example id (navbar picker / `setActiveExample`).
        pub async fn id(&self) -> &str {
            &self.id
        }

        /// 🗣️ Localized label sourced from the definition leaf.
        pub async fn label(&self) -> &LocalizedLabel {
            &self.label
        }

        /// 🖼️ Icon id sourced from the definition leaf.
        pub async fn icon_id(&self) -> IconName {
            self.icon_id
        }

        /// 📄️ Document JSON payload registered on the manifest.
        pub async fn document_json(&self) -> &str {
            &self.document_json
        }

        /// 📄️ Alias of [`Self::document_json`] for leaf call sites that speak in document terms.
        pub async fn document(&self) -> &str {
            &self.document_json
        }

        /// 📒️ Alias of [`Self::document_json`] for leaf call sites that speak in payload terms.
        pub async fn payload(&self) -> &str {
            &self.document_json
        }

        /// 🧬️ Converts into a manifest [`ExampleDefinition`] (`app_id` filled at plugin registration).
        pub async fn into_example_definition(self) -> ExampleDefinition {
            ExampleDefinition { id: self.id, label: self.label, icon_id: self.icon_id, artifact_json: self.document_json, app_id: String::new() }
        }
    }

    impl From<ExampleSource> for ExampleDefinition {
        fn from(source: ExampleSource) -> Self {
            source.into_example_definition()
        }
    }

    impl From<&ExampleSource> for ExampleDefinition {
        fn from(source: &ExampleSource) -> Self {
            ExampleDefinition { id: source.id.clone(), label: source.label.clone(), icon_id: source.icon_id, artifact_json: source.document_json.clone(), app_id: String::new() }
        }
    }

    impl From<&ExampleSource> for ExampleSource {
        fn from(source: &ExampleSource) -> Self {
            source.clone()
        }
    }

    #[cfg(test)]
    mod example_source_tests {
        use super::*;

        /// 🪪️ Contract §1 fixture — a canonical id built via `surface_app_id` from a fixture `Dialect`,
        /// not a hand-written pre-migration string like the retired `"puzzle2d-play"`/`"demo-play"`.
        async fn canonical_test_app_id(slug: &str) -> String {
            surface_app_id(&ArtifactDialect { artifact_kind: format!("s.test.example-source.{slug}"), standard: "1".into(), subset: "*".into() }, AppRole::Editor)
        }

        #[semio_framework_async_macros::async_test]
        async fn example_source_converts_into_example_definition_and_registers_on_app() {
            let source = ExampleSource::new("nakagin", LocalizedLabel::native("Nakagin Capsule Tower", "Nakagin-Kapselturm"), "{\"kind\":\"demo\"}", "building");
            assert_eq!(source.id(), "nakagin");
            assert_eq!(source.document(), "{\"kind\":\"demo\"}");
            assert_eq!(source.payload(), source.document_json());
            let definition = ExampleDefinition::from(&source);
            assert_eq!(definition.id, "nakagin");
            assert_eq!(definition.artifact_json, "{\"kind\":\"demo\"}");
            assert!(definition.app_id.is_empty());
            let app = App::from_builder(App::builder(canonical_test_app_id("puzzle2d-play"), LocalizedLabel::data("Puzzle").await).document(["semio", "puzzle"]).mode("edit", LocalizedLabel::data("Edit").await, "pencil").window_kind(
                "main",
                LocalizedLabel::data("Main").await,
                "puzzle.main",
                SurfaceKind::Canvas2d,
                IconName::AppWindow,
            ))
            .example_source(&source);
            assert_eq!(app.examples.len(), 1);
            assert_eq!(app.examples[0].id, "nakagin");
            assert_eq!(app.examples[0].icon_id, IconName::from("building"));
        }

        #[semio_framework_async_macros::async_test]
        async fn example_delegates_to_example_source() {
            let app = App::from_builder(App::builder(canonical_test_app_id("demo-play"), LocalizedLabel::data("Demo").await).document(["semio", "demo"]).mode("edit", LocalizedLabel::data("Edit").await, "pencil").window_kind(
                "main",
                LocalizedLabel::data("Main").await,
                "demo.main",
                SurfaceKind::Canvas2d,
                IconName::AppWindow,
            ))
            .example("default", LocalizedLabel::native("Default", "Standard"), "{}", "file");
            assert_eq!(app.examples.len(), 1);
            assert_eq!(app.examples[0].id, "default");
        }
    }
    //#endregion 📚️ExampleSource

    pub struct App {
        pub definition: AppDefinition,
        pub examples: Vec<ExampleDefinition>,
    }

    impl App {
        pub async fn builder(id: impl Into<String>, label: impl Into<LocalizedLabel>) -> AppBuilder {
            AppBuilder::new(id, label).await
        }

        /// 🗂️ Resource kinds declared via `.artifact_kind(...)` — see `AppDefinition.artifact_kinds`
        /// (round-trips through the plugin manifest; `semio_framework_os`'s artifact catalog registry
        /// consumes it from there at plugin registration time).
        pub async fn from_builder(builder: AppBuilder) -> Self {
            Self { definition: builder.build_definition().await, examples: Vec::new() }
        }

        /// 🧷️ Fallible twin of `from_builder` — see `AppBuilder::try_build_definition`.
        pub async fn try_from_builder(builder: AppBuilder) -> Result<Self, PluginAssemblyError> {
            Ok(Self { definition: builder.try_build_definition().await?, examples: Vec::new() })
        }

        /// 📚️ Registers an example from a definition-leaf [`ExampleSource`] (canonical path).
        pub async fn example_source(mut self, source: impl Into<ExampleSource>) -> Self {
            self.examples.push(ExampleDefinition::from(source.into()));
            self
        }

        /// 📚️ Registers an example by restating id/label/payload/icon.
        /// Prefer [`Self::example_source`] once the definition leaf owns those fields; kept so
        /// existing `create_*_app()` call sites keep compiling during the example-shape migration.
        pub async fn example(self, id: impl Into<String>, label: impl Into<LocalizedLabel>, document_json: impl Into<String>, icon_id: impl Into<IconName>) -> Self {
            self.example_source(ExampleSource::new(id, label, document_json, icon_id)).await
        }

        /// 🚧️ B1 stub: `WorkflowDefinition` + `PluginManifest.workflows` were deleted from framework-core
        /// (WP-0.1, concurrent) — real workflow-palette derivation moves to `register_app_io`/
        /// `workflow_palette()` in Wave 1 (`AppIo`-driven, not this free-text `yields`). Kept as a no-op
        /// so the ~50 existing `.workflow(...)` call sites across every app manifest keep compiling
        /// unchanged until their own wave touches them.
        pub async fn workflow(self, _workflow_step_id: impl Into<String>, _label: impl Into<String>, _yields: impl Into<String>) -> Self {
            self
        }
    }

    //#region 🔖️DocumentContract
    /// @emoji 🧾️ Read-only view of an app's document handed to `ArtifactApp::handle_action`/`render`:
    /// the materialized snapshot plus the history metadata (checkpoints/alternatives/undo state)
    /// derived from the owning {@link VcsArtifactApp}'s persistent {@link ArtifactStore}.
    pub struct ArtifactView<'a, P> {
        pub snapshot: &'a P,
        pub history: &'a HistoryView,
        /// 🧸️ Read access to this document's OWNED CHILDREN, each of which is its own envelope with
        /// its own `ArtifactVcs` history (never an inline subtree). See {@link ChildContentView}.
        pub children: ChildContentView,
    }

    impl<'a, P> ArtifactView<'a, P> {
        /// 🏗️ A view over a document with no composed children — the overwhelming majority, and the
        /// shape every leaf app and test uses. Prefer this over a struct literal: lane views grow
        /// over time, and a constructor absorbs that growth without touching every call site.
        pub async fn new(snapshot: &'a P, history: &'a HistoryView) -> Self {
            Self { snapshot, history, children: ChildContentView::EMPTY }
        }

        /// 🏗️ A view over a composing document, wired to its live child stores.
        pub async fn with_children(snapshot: &'a P, history: &'a HistoryView, children: ChildContentView) -> Self {
            Self { snapshot, history, children }
        }
    }

    /// @emoji 🧸️ Read-only access to a composing document's live child stores, keyed `(slot,
    /// child_id)` exactly as the parent's `ArtifactChild` handles name them.
    ///
    /// This is the seam that replaces the `thread_local!`/session `HashMap<child_id, content>`
    /// caches every composed plugin used to carry. Those caches went STALE the moment anything
    /// moved a child's history without going through `ArtifactApp::handle` — store-level undo/redo
    /// and checkout do exactly that. `new` reads every live `SpaceMember`'s pack bytes ONCE, at
    /// construction — no second copy is ever cached across dispatches — so a view built fresh
    /// immediately before each `handle`/`render` call (as every {@link VcsArtifactApp} call site
    /// does) cannot present state older than the dispatch it belongs to.
    ///
    /// 🚫️async: E1-adjacent by construction, not tagged — `M: SpaceMember` is generic on {@link
    /// Self::new} itself, NOT on this struct. `ArtifactApp::render`/`handle`/… fix their `doc`
    /// parameter's type at exactly `ArtifactView<'_, Self::Snapshot>` (no member-kind parameter),
    /// so `ChildContentView` must stay a single, non-generic, dyn-free type usable from EVERY
    /// plugin's fixed trait-method signature — the old `Box<dyn SpaceMember>` erasure existed
    /// precisely to buy that uniformity, which is no longer available once `SpaceMember` is AFIT
    /// (not object-safe). Pre-extracting each child's pack bytes at `new()` time (function-generic
    /// over the caller's concrete `M`) reproduces the same uniformity without a trait object or a
    /// fleet-wide `ArtifactApp::Members` associated-type rollout — see
    /// `📓️terra-dedyn-fw-os-spacemember-report.md` §ChildContentView for the rejected alternatives.
    /// `Default` (`EMPTY`) so a leaf app's view costs nothing and needs no ceremony.
    #[derive(Clone, Default)]
    pub struct ChildContentView {
        children: Option<HashMap<(String, String), (ArtifactDialect, Vec<u8>)>>,
    }

    impl ChildContentView {
        /// 🈳️ The view a document with no children gets.
        pub const EMPTY: Self = Self { children: None };

        /// 🏗️ Reads every live child's document pack bytes ONCE, from a live `M`-typed child-store
        /// map (built by {@link VcsArtifactApp} before each dispatch) — see this struct's own doc
        /// comment for why `M` is generic here rather than on the struct. A child whose pack read
        /// fails is silently omitted (behaves as "not adopted" from this read-only view's
        /// perspective) rather than failing construction for every sibling child too.
        pub async fn new<M: SpaceMember>(children: &HashMap<(String, String), (ArtifactDialect, M)>) -> Self {
            let mut snapshot = HashMap::with_capacity(children.len());
            for (key, (dialect, member)) in children.iter() {
                if let Ok(pack) = member.document_pack_bytes().await {
                    snapshot.insert(key.clone(), (dialect.clone(), pack));
                }
            }
            Self { children: Some(snapshot) }
        }

        /// 📦️ The child's content, pack-encoded, as of when this view was constructed.
        pub async fn pack(&self, slot: &str, child_id: &str) -> Result<Vec<u8>, Fault> {
            self.children
                .as_ref()
                .and_then(|children| children.get(&(slot.to_string(), child_id.to_string())))
                .map(|(_, pack)| pack.clone())
                .ok_or_else(|| plugin_sdk_fault(format!("no live child store for slot {slot} child {child_id}")))
        }

        /// 🧩️ {@link Self::pack} decoded as the child's snapshot type — what a composing app's
        /// `handle`/`render` actually calls.
        pub async fn typed<S: ArtifactPack>(&self, slot: &str, child_id: &str) -> Result<S, Fault> {
            S::decode_pack(&self.pack(slot, child_id).await?).await.map_err(|error| plugin_sdk_fault(error.to_string()))
        }

        /// 🎯️ The dialect a child materializes as, for a caller that must route by kind.
        pub async fn dialect(&self, slot: &str, child_id: &str) -> Option<ArtifactDialect> {
            self.children.as_ref().and_then(|children| children.get(&(slot.to_string(), child_id.to_string()))).map(|(dialect, _)| dialect.clone())
        }

        /// 📋️ Every `(slot, child_id)` currently live under this document.
        pub async fn slots(&self) -> Vec<(String, String)> {
            self.children.as_ref().map(|children| children.keys().cloned().collect()).unwrap_or_default()
        }

        /// 🈳️ Whether this document has any live children at all.
        pub async fn is_empty(&self) -> bool {
            self.children.as_ref().map(HashMap::is_empty).unwrap_or(true)
        }
    }

    /// @emoji 🧮️ Read-only view of an app's config snapshot — same role as {@link ArtifactView} for the
    /// config {@link ConfigStore} owned by {@link VcsArtifactApp}.
    pub struct ConfigView<'a, C> {
        pub snapshot: &'a C,
    }

    /// @emoji 📝️ Read-only view of an app's volatile draft snapshot — same role as {@link ConfigView}
    /// for the draft {@link store::DraftStore} (ephemeral; never checkpoints).
    pub struct DraftView<'a, D> {
        pub snapshot: &'a D,
    }

    /// @emoji 👥️ Read-only view of the PRESENCE lane: this actor's own live shared state plus every
    /// peer's, as last broadcast. Ephemeral and shared — never persisted, never undoable.
    pub struct PresenceView<'a, P> {
        /// 👤️ This actor's own presence — the value that gets broadcast.
        pub local: &'a P,
        /// 👥️ Every other peer's presence, sorted by actor id for a stable render order.
        pub peers: Vec<(&'a str, &'a P)>,
    }

    /// @emoji 🫧️ Read-only view of the TRANSIENT lane: ephemeral state local to this client that is
    /// never document content — the typed replacement for plugin `thread_local!` scratch state.
    pub struct TransientView<'a, T> {
        pub snapshot: &'a T,
    }

    //#region 🔖️InteractionView
    /// @emoji 👥️ One OTHER peer's last-adopted artifact/app-scope presence slice — the plugin-side
    /// twin of `PresencePeer`'s `color`/`surface`/`interaction` fields, keyed by actor in
    /// `VcsArtifactApp::peer_presence` (contract-freeze §C7.6). `presence_pack`'s decoded app-typed
    /// value is NOT carried here — it lands in `presence_store` instead (the existing peer-roster
    /// mechanism, unchanged), so this struct stays generic over every `ArtifactApp`.
    #[derive(Clone, Debug, Default, PartialEq)]
    pub struct PeerPresence {
        pub color: Option<u8>,
        pub surface: Option<String>,
        pub interaction: Option<protocol::PresenceInteraction>,
    }

    /// @emoji 👥️ One peer's mark on a single interaction target — `InteractionView::peers_selecting`/
    /// `peers_hovering`'s element type (contract-freeze §C7.6), sorted by actor.
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct PeerMark<'a> {
        pub actor: &'a str,
        pub color: Option<u8>,
    }

    /// 🈳️ Lazily-initialized empty fallbacks `InteractionView`'s accessors return for an undeclared or
    /// never-touched domain — one static pair shared across every instance, so the accessor methods
    /// below can return a plain `&DomainSelection`/`&DomainHover` (no `Option`, no per-call allocation)
    /// exactly like the ticket's specified signature.
    async fn empty_domain_selection() -> &'static protocol::DomainSelection {
        static EMPTY: std::sync::OnceLock<protocol::DomainSelection> = std::sync::OnceLock::new();
        EMPTY.get_or_init(protocol::DomainSelection::default)
    }

    async fn empty_domain_hover() -> &'static protocol::DomainHover {
        static EMPTY: std::sync::OnceLock<protocol::DomainHover> = std::sync::OnceLock::new();
        EMPTY.get_or_init(protocol::DomainHover::default)
    }

    /// 🕹️ Read-only view of the framework-owned INTERACTION mechanism (hover + selection + active
    /// mode/granularity per domain) — threaded into `ArtifactApp::handle`/`copy_fragment`/
    /// `cut_operations` so an app reads its own current selection/hover instead of ever storing it
    /// again itself. `state` is the persisted-local half (selection/mode/granularity, one
    /// `VcsArtifactApp::interaction_store` `ApplyInLane{lane: HistoryLane::Interaction}` dispatch away
    /// from every change); `hover` is the ephemeral-local half (`VcsArtifactApp::interaction_hover`,
    /// never persisted — see that field's own doc comment). Both are combined once per dispatch by
    /// `VcsArtifactApp::interaction_view`, never mutated through this read-only handle.
    pub struct InteractionView<'a> {
        pub(crate) state: &'a protocol::InteractionState,
        pub(crate) hover: &'a InteractionHoverState,
        /// @emoji 👥️ Every OTHER peer's last-adopted presence, keyed by actor — see
        /// `VcsArtifactApp::peer_presence`'s own doc comment. Sourced from `BTreeMap` iteration
        /// order, which is already sorted by actor.
        pub(crate) peers: &'a BTreeMap<String, PeerPresence>,
    }

    impl<'a> InteractionView<'a> {
        /// 🖱️ `domain`'s current selection — an empty `DomainSelection` (not `None`) for an undeclared
        /// or never-selected domain, so call sites never have to unwrap.
        pub async fn selection(&self, domain: &str) -> &protocol::DomainSelection {
            self.state.selection.get(domain).unwrap_or_else(|| empty_domain_selection())
        }

        /// 🐁️ `domain`'s current hover on `channel` — empty when nothing is hovered on that channel
        /// right now. `InteractionState.hover` holds exactly one live channel per domain at a time (the
        /// most recently hovered — see `next_hover`'s doc), so a `channel` mismatch also reads empty
        /// rather than returning a stale different-channel hover.
        pub async fn hover(&self, domain: &str, channel: &str) -> &protocol::DomainHover {
            match self.hover.get(domain) {
                Some(hover) if hover.channel == channel => hover,
                _ => empty_domain_hover(),
            }
        }

        /// 🪜️ `domain`'s active granularity id, `None` for an undeclared domain (never dispatched
        /// through `validate_state` yet — e.g. a registry-less test construction).
        pub async fn active_granularity(&self, domain: &str) -> Option<&str> {
            self.state.active_granularity.get(domain).map(String::as_str)
        }

        /// 🔀️ `domain`'s active `SelectionMode`, `None` for an undeclared domain.
        pub async fn active_mode(&self, domain: &str) -> Option<protocol::SelectionMode> {
            self.state.active_mode.get(domain).copied()
        }

        /// 👥️ Every OTHER peer currently selecting `id` within `domain`, sorted by actor
        /// (contract-freeze §C7.6) — `[]` for a peer with no adopted interaction, an interaction with
        /// no matching domain, or a domain where `id` is not in `selected`.
        pub async fn peers_selecting(&self, domain: &str, id: &str) -> Vec<PeerMark<'a>> {
            self.peers
                .iter()
                .filter_map(|(actor, presence)| {
                    let interaction = presence.interaction.as_ref()?;
                    let matched = interaction.domains.iter().find(|candidate| candidate.domain == domain)?;
                    matched.selected.iter().any(|selected_id| selected_id == id).then_some(PeerMark { actor: actor.as_str(), color: presence.color })
                })
                .collect()
        }

        /// 👥️ `peers_selecting`'s hover twin — every OTHER peer currently hovering `id` within
        /// `domain`, sorted by actor.
        pub async fn peers_hovering(&self, domain: &str, id: &str) -> Vec<PeerMark<'a>> {
            self.peers
                .iter()
                .filter_map(|(actor, presence)| {
                    let interaction = presence.interaction.as_ref()?;
                    let matched = interaction.domains.iter().find(|candidate| candidate.domain == domain)?;
                    matched.hovered.iter().any(|hovered_id| hovered_id == id).then_some(PeerMark { actor: actor.as_str(), color: presence.color })
                })
                .collect()
        }
    }
    //#endregion 🔖️InteractionView

    //#region 🔖️NoConfig
    /// @emoji 🧮️ Default `ArtifactApp::Config` for apps with no config artifact yet.
    #[derive(Clone, Debug, PartialEq, Default, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub struct NoConfig {}

    impl store::ArtifactDsl for NoConfig {
        const EXTENSION: &'static str = "nocfg";
        async fn parse_dsl(text: &str) -> Result<Self, store::TextError> {
            if text.trim().is_empty() {
                return Ok(Self::default());
            }
            Err(store::TextError::new("no config", store::TextSpan::at(1, 1)))
        }
        async fn print_dsl(&self) -> String {
            String::new()
        }
    }

    impl ArtifactPack for NoConfig {
        async fn encode_pack_with(&self, _options: &store::PackEncodeOptions) -> Result<Vec<u8>, store::PackError> {
            Ok(Vec::new())
        }
        async fn decode_pack_with(_bytes: &[u8], _options: &store::PackDecodeOptions) -> Result<Self, store::PackError> {
            Ok(Self::default())
        }
    }

    impl store::ConfigRecord for NoConfig {}

    impl ::protocol::MutationDiff<NoConfig> for NoConfig {
        async fn apply(&self, base: &NoConfig) -> protocol::MutationApplyResult<NoConfig> {
            Ok(base.clone())
        }
        async fn absorb(&mut self, _other: Self) {}
    }

    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize, dsl::DslOps)]
    #[serde(rename_all = "camelCase")]
    pub enum NoConfigMutation {
        Noop,
    }

    impl ::protocol::Mutation<NoConfig> for NoConfigMutation {
        type Diff = NoConfig;

        async fn diff(&self, _base: &NoConfig) -> ::protocol::MutationOutcome<NoConfig> {
            ::protocol::MutationOutcome::new(NoConfig::default()).await
        }

        async fn inverse(&self, _base: &NoConfig) -> Vec<Self> {
            vec![NoConfigMutation::Noop]
        }
    }

    impl ::protocol::OpText for NoConfigMutation {
        async fn parse_op(line: &str) -> Result<Self, ::store::TextError> {
            let variants = <Self as ::dsl::DslVariants>::variants();
            for (keyword, spec_fn) in &variants {
                let probe = format!("{keyword} ");
                if line == keyword.as_str() || line.starts_with(&probe) {
                    let body = if line.len() > keyword.len() { line[keyword.len()..].trim_start() } else { "" };
                    let record = ::dsl::parse(body, &spec_fn(), &::dsl::ParseOptions { limits: ::dsl::Limits::default(), mode: ::dsl::SourceMode::Inline }).await?;
                    return <Self as ::dsl::DslVariants>::from_named_record(keyword, &record).await;
                }
            }
            Err(::dsl::__rt::field_error(format!("unknown operation line '{line}'")))
        }
        async fn print_op(&self) -> String {
            let (keyword, record) = <Self as ::dsl::DslVariants>::to_named_record(self).await;
            let variants = <Self as ::dsl::DslVariants>::variants();
            let spec_fn = variants.iter().find(|(k, _)| k == &keyword).map(|(_, s)| *s).expect("variant spec must exist for its own keyword");
            let body = ::dsl::print(&record, &spec_fn(), ::dsl::JoinMode::Inline);
            if body.await.is_empty() {
                keyword
            } else {
                format!("{keyword} {body}")
            }
        }
    }

    impl ::protocol::OpBinary for NoConfigMutation {
        async fn encode_op(&self) -> Result<Vec<u8>, ::protocol::ProtocolError> {
            ::dsl::variants_binary::encode_op(self).await
        }
        async fn decode_op(bytes: &[u8]) -> Result<Self, ::protocol::ProtocolError> {
            ::dsl::variants_binary::decode_op(bytes).await
        }
    }
    //#endregion 🔖️NoConfig

