    /// 🎞️ WIT `consume-media` glue — decodes the incoming `media-artifact` (`descriptor-json` + `data`)
    /// and dispatches to `PluginApp::consume_media`.
    pub async fn plugin_consume_media(instance_id: u32, port_id: &str, descriptor_json: &str, data: Vec<u8>) -> Result<(), Fault> {
        let descriptor: MediaArtifactDescriptor = serde_json::from_str(descriptor_json).map_err(|error| plugin_internal_fault(error.to_string()))?;
        let artifact = MediaArtifact { descriptor, data };
        with_instances_mut(|list| {
            let instance = find_instance(list, instance_id)?;
            resolve_ready(instance.app.consume_media(port_id, artifact)).map_err(|error| plugin_internal_fault(error.to_string()))
        }).await
    }

    /// 🎞️ WIT `produce-media` glue — dispatches to `PluginApp::produce_media` and encodes the result back
    /// into `(descriptor-json, data)` for the `media-artifact` WIT record. `_request_json` is reserved for
    /// future parameterized requests; unused by the SDK default (see `PluginApp::produce_media`).
    pub async fn plugin_produce_media(instance_id: u32, port_id: &str, _request_json: &str) -> Result<(String, Vec<u8>), Fault> {
        let artifact = with_instances_mut(|list| {
            let instance = find_instance(list, instance_id)?;
            resolve_ready(instance.app.produce_media(port_id)).map_err(|error| plugin_internal_fault(error.to_string()))
        }).await?;
        let descriptor_json = serde_json::to_string(&artifact.descriptor).map_err(|error| plugin_internal_fault(error.to_string()))?;
        Ok((descriptor_json, artifact.data))
    }

    pub async fn plugin_render(instance_id: u32, body_key: &str, view_state_json: &str) -> Result<UiNode, Fault> {
        plugin_render_with_document(instance_id, body_key, None, view_state_json).await
    }

    pub async fn plugin_render_with_document(instance_id: u32, body_key: &str, snapshot_override_json: Option<&str>, view_state_json: &str) -> Result<UiNode, Fault> {
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct WindowRenderInput {
            #[serde(default)]
            body_key: String,
            view_state: ViewModel,
            #[serde(default)]
            document_json: Option<String>,
        }
        let (resolved_body_key, view_state, override_snapshot) = if body_key.is_empty() {
            let input: WindowRenderInput = serde_json::from_str(view_state_json).map_err(|error| plugin_internal_fault(error.to_string()))?;
            (input.body_key, input.view_state, input.document_json)
        } else if let Ok(input) = serde_json::from_str::<WindowRenderInput>(view_state_json) {
            let key = if input.body_key.is_empty() { body_key.to_string() } else { input.body_key };
            (key, input.view_state, input.document_json.or_else(|| snapshot_override_json.map(str::to_string)))
        } else {
            let view_state: ViewModel = serde_json::from_str(view_state_json).map_err(|error| plugin_internal_fault(error.to_string()))?;
            (body_key.to_string(), view_state, snapshot_override_json.map(str::to_string))
        };
        with_instances_mut(|list| {
            let instance = find_instance(list, instance_id)?;
            resolve_ready(instance.app.render(&resolved_body_key, override_snapshot.as_deref(), &view_state))
        }).await
    }

    //#region 🔖️RefreshUi
    /// 🐢️ The raw fnv1a-64 core — a tiny non-cryptographic hash for cheap "did this section's content
    /// change" checks, not a security boundary, just change detection, so speed over collision-resistance
    /// is the right tradeoff (mirrors the identical pattern already used for `cached_fixture_json` in
    /// puzzle's plugin). Used by `ui_refresh_fnv1a_hash` below (`plugin_refresh_ui`'s legacy JSON
    /// `refreshUi` wire, unrelated to channel v12's binary `AppCommand`/`AppFrame`).
    async fn fnv1a64(bytes: &[u8]) -> u64 {
        let mut hash: u64 = 0xcbf29ce484222325;
        for byte in bytes {
            hash ^= u64::from(*byte);
            hash = hash.wrapping_mul(0x100000001b3);
        }
        hash
    }

    /// 🐢️ A tiny non-cryptographic hash (fnv1a-64) for cheap "did this section's content change" checks —
    /// not a security boundary, just change detection, so speed over collision-resistance is the right
    /// tradeoff (mirrors the identical pattern already used for `cached_fixture_json` in puzzle's plugin).
    async fn ui_refresh_fnv1a_hash(bytes: &[u8]) -> String {
        format!("{:016x}", fnv1a64(bytes))
    }

    /// 🐢️ Hashes `value`'s canonical JSON serialization and returns `(hash, Some(value))` when it differs
    /// from `known_hash`, or `(hash, None)` when unchanged — the response omits the payload either way the
    /// caller doesn't need it, keeping the wire payload proportional to what actually changed.
    async fn ui_refresh_section<T: Serialize>(value: &T, known_hash: Option<&str>) -> (String, Option<Value>) {
        let wire = serde_json::to_string(value).unwrap_or_default();
        let hash = ui_refresh_fnv1a_hash(wire.as_bytes()).await;
        if known_hash == Some(hash.as_str()) {
            (hash, None)
        } else {
            let payload = serde_json::from_str(&wire).unwrap_or(Value::Null);
            (hash, Some(payload))
        }
    }

    /// 🐢️ Batched, hash-conditional UI refresh: replaces the individual
    /// `render`/`windowEngagements`/`windowMeasures`/`appLabels` WASM round trips a full `refreshUi` used
    /// to make with **one** call. `request_json` lists every section the host wants (windows/panels by
    /// `{key, bodyKey, hash}`, engagements/measures/labels each `{hash}`); the response includes a payload
    /// only for sections whose hash differs from what the host already holds. Utility bars are no longer a
    /// plugin section — the renderer derives them from the utility registry via `derive_utility_nodes`.
    pub async fn plugin_refresh_ui(instance_id: u32, request_json: &str) -> Result<String, String> {
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct SectionRequest {
            key: String,
            #[serde(default)]
            body_key: String,
            #[serde(default)]
            hash: Option<String>,
        }
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct SingleRequest {
            #[serde(default)]
            hash: Option<String>,
        }
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct RefreshRequest {
            view_state: ViewModel,
            #[serde(default)]
            windows: Vec<SectionRequest>,
            #[serde(default)]
            panels: Vec<SectionRequest>,
            #[serde(default)]
            utilities: Vec<SectionRequest>,
            #[serde(default)]
            engagements: Option<SingleRequest>,
            #[serde(default)]
            measures: Option<SingleRequest>,
            #[serde(default)]
            tools: Option<SingleRequest>,
            #[serde(default)]
            labels: Option<SingleRequest>,
        }
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct SectionResponse {
            key: String,
            hash: String,
            #[serde(skip_serializing_if = "Option::is_none")]
            value: Option<Value>,
        }
        #[derive(Serialize, Default)]
        #[serde(rename_all = "camelCase")]
        struct RefreshResponse {
            #[serde(skip_serializing_if = "Vec::is_empty")]
            windows: Vec<SectionResponse>,
            #[serde(skip_serializing_if = "Vec::is_empty")]
            panels: Vec<SectionResponse>,
            #[serde(skip_serializing_if = "Vec::is_empty")]
            utilities: Vec<SectionResponse>,
            #[serde(skip_serializing_if = "Option::is_none")]
            engagements: Option<SectionResponse>,
            #[serde(skip_serializing_if = "Option::is_none")]
            measures: Option<SectionResponse>,
            #[serde(skip_serializing_if = "Option::is_none")]
            tools: Option<SectionResponse>,
            #[serde(skip_serializing_if = "Option::is_none")]
            labels: Option<SectionResponse>,
            /// ⏱️ See `ArtifactApp::pending_effects` — e.g. a `flowEvalTick` chain resuming after this refresh.
            #[serde(skip_serializing_if = "Vec::is_empty")]
            requested_effects: Vec<Effect>,
        }

        let request: RefreshRequest = serde_json::from_str(request_json).map_err(|error| error.to_string())?;

        with_instances_mut(|list| {
            let instance = find_instance(list, instance_id)?;

            let mut response = RefreshResponse::default();
            // ⏱️ Arm/advance background work BEFORE rendering below, not after — e.g. a `flowEvalTick`
            // chain's `computing_json` must be fresh by the time this same pass renders the graph, or a
            // cold-start load would render one full refresh cycle behind (nothing flagged as computing
            // until the *next* refresh).
            response.requested_effects = resolve_ready(instance.app.pending_effects());

            for entry in &request.windows {
                // 🪟️ Stamp this window's instance id and its own active utility into the view state before
                // rendering, so a `ArtifactApp` can key per-window options and utility-driven scene state off
                // `view_state.window_id` / `view_state.active_utility_id` and never off the focused window alone.
                let active_utility_id = request.view_state.active_utility_by_window_id.get(&entry.key).cloned().or_else(|| request.view_state.active_utility_id.clone());
                let window_view_state = ViewModel { window_id: Some(entry.key.clone()), active_utility_id, ..request.view_state.clone() };
                let node = resolve_ready(instance.app.render(&entry.body_key, None, &window_view_state))?;
                let (hash, value) = ui_refresh_section(&node, entry.hash.as_deref());
                response.windows.push(SectionResponse { key: entry.key.clone(), hash, value });
            }
            for entry in &request.panels {
                let node = resolve_ready(instance.app.render(&entry.body_key, None, &request.view_state))?;
                let (hash, value) = ui_refresh_section(&node, entry.hash.as_deref());
                response.panels.push(SectionResponse { key: entry.key.clone(), hash, value });
            }
            // 🚧️ `utilities` intentionally unhandled here: `PluginApp`/`ArtifactApp` currently expose no
            // object-safe `utilities()` accessor (mid-refactor elsewhere toward a declarative window-kind
            // utility builder — unrelated to this ticket; see `tools`/`tool_measures` above for the analogous
            // mode-level mechanism that IS wired up). No puzzle2d scope ever requests `utilities: true` (it
            // uses static window-kind-scoped utilities only), so `request.utilities` is always empty in
            // practice; wire this up once the utilities API refactor lands.
            let _ = &request.utilities;
            if let Some(requested) = &request.engagements {
                let engagements = resolve_ready(instance.app.window_engagements());
                let (hash, value) = ui_refresh_section(&engagements, requested.hash.as_deref());
                response.engagements = Some(SectionResponse { key: "engagements".into(), hash, value });
            }
            if let Some(requested) = &request.measures {
                let measures = resolve_ready(instance.app.window_measures());
                let (hash, value) = ui_refresh_section(&measures, requested.hash.as_deref());
                response.measures = Some(SectionResponse { key: "measures".into(), hash, value });
            }
            if let Some(requested) = &request.tools {
                let tool_measures = resolve_ready(instance.app.tool_measures());
                let (hash, value) = ui_refresh_section(&tool_measures, requested.hash.as_deref());
                response.tools = Some(SectionResponse { key: "tools".into(), hash, value });
            }
            // 🗣️ Labels no longer need a runtime overlay round-trip: the manifest itself now carries a full
            // `LocalizedLabel` matrix per field, resolved shell-side from the active locale/terminology —
            // see ticket 26/08/03/COMPILE-TIME-CHECKED-UI-LABELS-ACROSS-LOCALE-TERMINOLOGY-AND-BRAND. A
            // `labels` refresh request now always comes back empty; kept accepting it (rather than erroring)
            // so an unupdated shell doesn't break.
            let _ = &request.labels;

            Ok(serde_json::to_string(&response).unwrap_or_else(|_| "{}".into()))
        })
        .await.map_err(|fault| fault.message)
    }
    //#endregion 🔖️RefreshUi

    //#region 🔖️ContextMenu
    /// 🖱️ Wire shape for an on-demand context-menu request — mirrors TS `PluginContextMenuRequest` minus
    /// `viewState` (B1 dropped `ViewModel` from `ArtifactApp::context_menu` entirely, so this struct no
    /// longer parses-and-discards a field it never forwards). Module-scoped (not nested in
    /// `plugin_context_menu`) so `plugin_exchange`'s `AppCommand::ContextMenu` arm below can decode the
    /// same typed shape directly off the binary wire instead of round-tripping through JSON strings.
    #[derive(Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct ContextMenuWireRequest {
        menu: UiMenuRef,
        #[serde(default)]
        surface: Option<ContextMenuSurfaceTarget>,
        #[serde(default)]
        window_instance_id: Option<String>,
        #[serde(default)]
        point: Option<ContextMenuPoint>,
    }

    impl From<ContextMenuWireRequest> for ContextMenuRequest {
        fn from(wire: ContextMenuWireRequest) -> Self {
            ContextMenuRequest { menu: wire.menu, surface: wire.surface, window_instance_id: wire.window_instance_id, point: wire.point }
        }
    }

    /// 🖱️ On-demand context-menu computation (WIT `context-menu` export's SDK entry point) — never
    /// cached, never part of `refresh_ui`. String-in/string-out JSON entry point for the WIT boundary.
    pub async fn plugin_context_menu(instance_id: u32, request_json: &str) -> Result<String, String> {
        let wire: ContextMenuWireRequest = serde_json::from_str(request_json).map_err(|error| error.to_string())?;
        let request: ContextMenuRequest = wire.into();
        with_instances_mut(|list| {
            let instance = find_instance(list, instance_id)?;
            let items = resolve_ready(instance.app.context_menu(&request));
            Ok(serde_json::to_string(&ContextMenuResponse { items }).unwrap_or_else(|_| r#"{"items":[]}"#.into()))
        })
        .await.map_err(|fault| fault.message)
    }
    //#endregion 🔖️ContextMenu

    //#region 🔖️Exchange
    /// 🎯️ `AppCommand::ArtifactCommand`'s Wave 1 mapping — the same magic action-name strings
    /// `VcsArtifactApp::dispatch_action` already intercepts for `store::ArtifactCommand` verbs (duplicated
    /// here rather than imported since `app`'s `HISTORY_ACTION_IDS` const is private — see
    /// `plugin_exchange`'s doc for why this frame is scoped to history verbs only in Wave 1).
    const DOCUMENT_COMMAND_ACTION_IDS: [&str; 6] = ["undo", "redo", "commitCheckpoint", "createAlternative", "switchAlternative", "checkoutCheckpoint"];

    /// 📤️ Collects `result`'s side-channel effects/events as wire-encoded bytes — channel v12 (A4)
    /// dropped `AppFrame::Effects`/`AppFrame::Events`, since effects/events now travel straight into
    /// `TurnResult` (design-abi.md §2/§4) instead of being wrapped as a frame; `PluginExchangeOutput`
    /// carries them alongside `frames`. Shared by `AppCommand::Command`'s and
    /// `AppCommand::ArtifactCommand`'s handling below.
    async fn push_invocation_side_frames(effects: &mut Vec<Vec<u8>>, events: &mut Vec<Vec<u8>>, result: &InvocationResult) {
        for effect in result.requested_effects.iter() {
            effects.push(encode_wire_serialized(effect).await);
        }
        for event in result.events.iter() {
            events.push(encode_wire_serialized(event).await);
        }
    }

    //#region 🔖️OpeningCommandRelay
    async fn opening_role(role: u8) -> Result<semio_framework::AppRole, Fault> {
        match role {
            0 => Ok(semio_framework::AppRole::Viewer),
            1 => Ok(semio_framework::AppRole::Editor),
            value => Err(Fault::new(FaultOrigin::Os, FaultCode::new("opening.invalid-role"), format!("opening role {value} must be 0 (viewer) or 1 (editor)"))),
        }
    }

    async fn opening_dialect(artifact_kind: String, standard: String, subset: String) -> Result<semio_framework::ArtifactDialect, Fault> {
        for (field, value) in [("artifact_kind", &artifact_kind), ("standard", &standard), ("subset", &subset)] {
            if value.trim().is_empty() {
                return Err(Fault::new(FaultOrigin::Os, FaultCode::new("opening.invalid-dialect"), format!("opening {field} must be non-empty")));
            }
        }
        let dialect = semio_framework::ArtifactDialect { artifact_kind, standard, subset };
        semio_framework::ArtifactDialect::parse_coordinate(&dialect.to_coordinate()).await.map_err(|error| Fault::new(FaultOrigin::Os, FaultCode::new("opening.invalid-dialect"), error))?;
        Ok(dialect)
    }

    async fn relay_opening_command(action_id: &'static str, arguments: Value) -> Result<Effect, Fault> {
        Ok(Effect::ReplayShellCommand { action_id: action_id.into(), args: Some(to_dsl_value(&arguments).map_err(plugin_internal_fault)?) })
    }

    async fn relay_open_artifact(artifact_ref: String, role_wire: u8, plugin_id: String, app_id: String) -> Result<Effect, Fault> {
        let role = opening_role(role_wire).await?;
        let (dialect, artifact_role) = semio_framework::parse_surface_app_id(&artifact_ref).await.map_err(|error| Fault::new(FaultOrigin::Os, FaultCode::new("opening.invalid-artifact-ref"), error))?;
        if role != artifact_role {
            return Err(Fault::new(FaultOrigin::Os, FaultCode::new("opening.role-mismatch"), format!("artifact ref {artifact_ref} declares {} but command declares {}", artifact_role.as_str(), role.as_str())));
        }
        match (plugin_id.trim().is_empty(), app_id.trim().is_empty()) {
            (true, true) => {}
            (false, false) => {
                let (app_dialect, app_role) = semio_framework::parse_surface_app_id(&app_id).await.map_err(|error| Fault::new(FaultOrigin::Os, FaultCode::new("opening.invalid-app-ref"), error))?;
                if app_dialect != dialect || app_role != role {
                    return Err(Fault::new(FaultOrigin::Os, FaultCode::new("opening.app-mismatch"), format!("explicit app {app_id} does not serve {}#{}", dialect.to_coordinate(), role.as_str())));
                }
            }
            _ => return Err(Fault::new(FaultOrigin::Os, FaultCode::new("opening.partial-app-ref"), "plugin_id and app_id must either both be empty or both be set")),
        }
        relay_opening_command("os.open-artifact", serde_json::json!({ "artifactRef": artifact_ref, "role": role_wire, "pluginId": plugin_id, "appId": app_id })).await
    }

    async fn relay_set_default_app(artifact_kind: String, standard: String, subset: String, role_wire: u8, plugin_id: String, app_id: String) -> Result<Effect, Fault> {
        let dialect = opening_dialect(artifact_kind.clone(), standard.clone(), subset.clone()).await?;
        let role = opening_role(role_wire).await?;
        if plugin_id.trim().is_empty() {
            return Err(Fault::new(FaultOrigin::Os, FaultCode::new("opening.invalid-app-ref"), "plugin_id must be non-empty when setting a default app"));
        }
        let (app_dialect, app_role) = semio_framework::parse_surface_app_id(&app_id).await.map_err(|error| Fault::new(FaultOrigin::Os, FaultCode::new("opening.invalid-app-ref"), error))?;
        if app_dialect != dialect || app_role != role {
            return Err(Fault::new(FaultOrigin::Os, FaultCode::new("opening.app-mismatch"), format!("default app {app_id} does not serve {}#{}", dialect.to_coordinate(), role.as_str())));
        }
        relay_opening_command("os.set-default-app", serde_json::json!({ "artifactKind": artifact_kind, "standard": standard, "subset": subset, "role": role_wire, "pluginId": plugin_id, "appId": app_id })).await
    }

    async fn relay_clear_default_app(artifact_kind: String, standard: String, subset: String, role_wire: u8) -> Result<Effect, Fault> {
        opening_dialect(artifact_kind.clone(), standard.clone(), subset.clone()).await?;
        opening_role(role_wire).await?;
        relay_opening_command("os.clear-default-app", serde_json::json!({ "artifactKind": artifact_kind, "standard": standard, "subset": subset, "role": role_wire })).await
    }
    //#endregion 🔖️OpeningCommandRelay

    //#region 🧪️OpeningCommandRelayTests
    #[cfg(test)]
    mod opening_command_relay_tests {
        use super::*;

        async fn replay(effect: Effect) -> (String, Value) {
            let Effect::ReplayShellCommand { action_id, args: Some(args) } = effect else { panic!("expected a shell command relay") };
            (action_id, from_dsl_value(args).expect("relay arguments decode"))
        }

        #[semio_framework_async_macros::async_test]
        async fn open_artifact_relays_an_exactly_matched_surface() {
            let (action_id, args) = replay(relay_open_artifact("s.test.document@1/*#editor".into(), 1, "test-plugin".into(), "s.test.document@1/*#editor".into()).expect("matching surface relays"));
            assert_eq!(action_id, "os.open-artifact");
            assert_eq!(args, serde_json::json!({ "artifactRef": "s.test.document@1/*#editor", "role": 1, "pluginId": "test-plugin", "appId": "s.test.document@1/*#editor" }));
        }

        #[semio_framework_async_macros::async_test]
        async fn default_app_commands_relay_the_validated_wire_coordinates() {
            let (set_action_id, set_args) = replay(relay_set_default_app("s.test.document".into(), "1".into(), "*".into(), 0, "test-plugin".into(), "s.test.document@1/*#viewer".into()).expect("matching default surface relays"));
            assert_eq!(set_action_id, "os.set-default-app");
            assert_eq!(set_args, serde_json::json!({ "artifactKind": "s.test.document", "standard": "1", "subset": "*", "role": 0, "pluginId": "test-plugin", "appId": "s.test.document@1/*#viewer" }));

            let (clear_action_id, clear_args) = replay(relay_clear_default_app("s.test.document".into(), "1".into(), "*".into(), 1).expect("valid clear relays"));
            assert_eq!(clear_action_id, "os.clear-default-app");
            assert_eq!(clear_args, serde_json::json!({ "artifactKind": "s.test.document", "standard": "1", "subset": "*", "role": 1 }));
        }

        #[semio_framework_async_macros::async_test]
        async fn opening_relays_reject_invalid_or_inconsistent_addresses() {
            let invalid_role = relay_open_artifact("s.test.document@1/*#viewer".into(), 7, String::new(), String::new()).expect_err("unknown role must fail");
            assert_eq!(invalid_role.code.0, "opening.invalid-role");

            let partial_app = relay_open_artifact("s.test.document@1/*#viewer".into(), 0, "test-plugin".into(), String::new()).expect_err("partial app reference must fail");
            assert_eq!(partial_app.code.0, "opening.partial-app-ref");

            let mismatched_app = relay_set_default_app("s.test.document".into(), "1".into(), "*".into(), 0, "test-plugin".into(), "s.test.other@1/*#viewer".into()).expect_err("app dialect must match default coordinate");
            assert_eq!(mismatched_app.code.0, "opening.app-mismatch");
        }
    }
    //#endregion 🧪️OpeningCommandRelayTests

    /// 🔀️ Frames a `TransactionProposalDraft` (contract §5.1) as `AppFrame::TransactionProposal`,
    /// wire-encoding each foreign step via `encode_wire_serialized` (contract §2's per-element
    /// `ForeignStep` encoding note) and minting a proposal id scoped to this dispatch
    /// (`"<instance_id>:<seq>"`, unique enough for one instance's own in-flight proposals — all a
    /// single-command dispatch ever needs).
    async fn transaction_proposal_frame(instance_id: u32, seq: u64, proposal: TransactionProposalDraft) -> protocol::AppFrame {
        let mut foreign = Vec::with_capacity(proposal.foreign.len());
        for step in proposal.foreign.iter() {
            foreign.push(encode_wire_serialized(step).await);
        }
        protocol::AppFrame::TransactionProposal {
            in_reply_to: seq,
            proposal_id: format!("{instance_id}:{seq}"),
            local_ops: proposal.local_ops,
            description: proposal.description,
            coalesce_key: proposal.coalesce_key,
            foreign,
        }
    }

    /// 🔀️ `PluginExchangeOutput` — `plugin_exchange`'s return shape. `frames` still carries the
    /// surviving `protocol::AppFrame` wire encodings (routed through `route_app_frame` by the
    /// reactor's `poll`); `effects`/`events` are wire-encoded `kernel::Effect`/`kernel::AppEvent`
    /// bytes collected directly — channel v12 (A4) removed `AppFrame::Effects`/`AppFrame::Events`,
    /// since design-abi.md §2/§4 has effects/events travel straight into `TurnResult`, never wrapped
    /// as a frame.
    pub struct PluginExchangeOutput {
        pub frames: Vec<Vec<u8>>,
        pub effects: Vec<Vec<u8>>,
        pub events: Vec<Vec<u8>>,
    }

    /// 🧵️ MICROKERNEL-POOLED-ACTOR-PLUGIN-RUNTIME (design-abi.md §4): erased `AsyncTask` resolution
    /// input for `plugin_resume_task` — mirrors `⚛️reactor`'s own (private) `TaskResumeOutcome`
    /// minus its `Fault` case (a task that itself resolved `Err` never reaches `plugin_runtime` at
    /// all — `⚛️reactor::drain_task_resumes` frames that straight to the shell). Kept as a SEPARATE
    /// type, not a shared one, so the dependency direction stays what it already is everywhere else
    /// in this file: `plugin_runtime` never imports `reactor`; `reactor` imports `plugin_runtime`.
    pub enum TaskResumeInput {
        Command(Vec<u8>),
        Emit { artifact_ops: Vec<u8>, config_ops: Vec<u8>, draft_ops: Vec<u8> },
    }

    /// 🧵️ MICROKERNEL-POOLED-ACTOR-PLUGIN-RUNTIME (design-abi.md §4): resumes ONE `AsyncTask`
    /// follow-up against `instance_id`'s live `dyn PluginApp` — `Command` re-enters through
    /// `PluginApp::handle_command_frame` (the SAME typed-command path a fresh command uses,
    /// against CURRENT state — Elm's Msg-from-Cmd), `Emit` through `PluginApp::resume_task_emit`
    /// (decode + `dispatch_emit` directly, no re-entry into `handle`). Frames the result EXACTLY
    /// like `AppCommand::PureCommand` does (`AppFrame::Emit`, carrying the SAME
    /// `take_last_emit_wire()` triple `dispatch_emit` always captures) rather than
    /// `AppFrame::Invocation` — a task follow-up is a guest-applied store-authority mutation, not a
    /// live client's reply; `in_reply_to: 0` marks it unsolicited (no seq is awaiting it). An
    /// app-level `Err` becomes an `Error` frame, exactly like every other dispatch path in this
    /// module — this function itself never fails. Returns the SAME `(frames, effects, events)`
    /// shape `PluginExchangeOutput` carries so the caller (`⚛️reactor::drain_task_resumes`) feeds
    /// `frames` through the SAME `route_app_frame` a live turn's command frames go through.
    pub async fn plugin_resume_task(instance_id: u32, meta: &ActionMeta, input: TaskResumeInput) -> PluginExchangeOutput {
        let mut frames: Vec<protocol::AppFrame> = Vec::new();
        let mut effect_bytes: Vec<Vec<u8>> = Vec::new();
        let mut event_bytes: Vec<Vec<u8>> = Vec::new();

        let dispatched = match input {
            TaskResumeInput::Command(bytes) => with_instances_mut(|list| {
                let instance = find_instance(list, instance_id)?;
                resolve_ready(instance.app.handle_command_frame(&bytes, meta))
            }).await,
            TaskResumeInput::Emit { artifact_ops, config_ops, draft_ops } => with_instances_mut(|list| {
                let instance = find_instance(list, instance_id)?;
                resolve_ready(instance.app.resume_task_emit(artifact_ops, config_ops, draft_ops, meta))
            }).await,
        };

        match dispatched {
            Ok(result) => {
                let emit_wire = with_instances_mut(|list| {
                    let instance = find_instance(list, instance_id)?;
                    Ok(resolve_ready(instance.app.take_last_emit_wire()).unwrap_or_default())
                })
                .await.unwrap_or_default();
                let (document_ops, config_ops, draft_ops) = emit_wire;
                frames.push(protocol::AppFrame::Emit {
                    in_reply_to: 0,
                    document_ops,
                    config_ops,
                    draft_ops,
                    output: encode_wire_serialized(&result.output).await,
                    diagnostics: encode_wire_serialized(&result.diagnostics).await,
                });
                push_invocation_side_frames(&mut effect_bytes, &mut event_bytes, &result).await;
            }
            Err(fault) => push_app_fault(&mut frames, None, fault).await,
        }

        PluginExchangeOutput { frames: frames.iter().map(protocol::encode_app_frame).collect(), effects: effect_bytes, events: event_bytes }
    }

    /// 🔀️ The single bidirectional entry point behind WIT `exchange` (see `📜️wit/📜️world.wit`'s
    /// `interface plugin` doc) — decodes each `protocol::AppCommand` in `commands`, dispatches it
    /// against `instance_id`, and returns every produced `protocol::AppFrame`/effect/event.
    ///
    /// 🚧️ Wave 1 scope — documented here rather than silently: `AppCommand::CommandText` is stubbed
    /// (`Error{code:"unsupported"}`, a later wave wires real headless op-text scripts);
    /// `AppCommand::ArtifactCommand` only accepts the six history verbs (`DOCUMENT_COMMAND_ACTION_IDS`),
    /// mapped onto the existing magic action-name interception rather than a real typed
    /// `store::ArtifactCommand` wire codec; the unsolicited outbox (backbone-driven
    /// `AppFrame::DocumentChanged`, a persistent per-instance frame queue surviving across calls) is
    /// NOT implemented — only `pending_effects` is drained, once, at the end of the batch, whenever a
    /// dispatched command mutated the document, mirroring exactly where `plugin_refresh_ui` already
    /// calls it.
    ///
    /// 🧬️ Channel v12 (A4) retired `AppCommand::{Hello, RefreshUi, AttachBackbone, DetachBackbone,
    /// Bye}` — lifecycle is now `Event::InstanceOpen`/`InstanceClose` at the reactor level, surface
    /// rendering is driven by `surface-visible`/`hidden` instead of `RefreshUi` probes, and the
    /// backbone attach/detach commands are gone with no replacement command in this wave. Those arms
    /// are deleted here rather than adapted (design-abi.md §4).
    pub async fn plugin_exchange(instance_id: u32, commands: &[Vec<u8>]) -> Result<PluginExchangeOutput, Fault> {
        let mut frames: Vec<protocol::AppFrame> = Vec::new();
        let mut effect_bytes: Vec<Vec<u8>> = Vec::new();
        let mut event_bytes: Vec<Vec<u8>> = Vec::new();
        let mut mutated = false;

        for bytes in commands {
            let command = protocol::decode_app_command(bytes).await.map_err(|error| error.into_fault())?;
            match command {
                protocol::AppCommand::Presence { seq, own_color, peers } => {
                    // 👥️ The ONLY plugin ingress for the peer roster (contract-freeze §C7.6): decode
                    // each wire `PresencePeer` and hand the WHOLE roster to `adopt_presence`, which is
                    // documented as the roster's single source of truth (absent actors are dropped by
                    // the callee, so this must not be treated as a diff). A peer entry that fails to
                    // decode is skipped rather than failing the batch — one malformed peer must not
                    // cost the actor its whole roster update.
                    let mut decoded: Vec<protocol::PresencePeer> = Vec::with_capacity(peers.len());
                    for bytes in peers.iter() {
                        if let Ok(peer) = protocol::decode_presence_peer(bytes).await {
                            decoded.push(peer);
                        }
                    }
                    let now_ms = crate::host::now_ms();
                    let adopted = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.adopt_presence(own_color, &decoded, now_ms))
                    });
                    match adopted.await {
                        Ok(()) => frames.push(protocol::AppFrame::Done { in_reply_to: seq }),
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::ConfigCommand { seq, command } => {
                    // 🧮️ B1: `command` is a binary-encoded `store::ArtifactCommand<A::ConfigMutation>` —
                    // real dispatch against the config store (replaces the deleted `apply_config_bytes`
                    // whole-record-replace legacy path); undo/redo/checkpoint all work on config now.
                    let meta = ActionMeta { actor: instance_actor(instance_id).await, instance_id };
                    let dispatched = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.dispatch_config_command(&command, &meta))
                    });
                    match dispatched.await {
                        Ok(result) => {
                            mutated = true;
                            frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                            push_invocation_side_frames(&mut effect_bytes, &mut event_bytes, &result).await;
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::Command { seq, command, view_state } => {
                    let meta = ActionMeta { actor: instance_actor(instance_id).await, instance_id };
                    with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.begin_dispatch_report());
                        Ok(())
                    }).await?;
                    let dispatched = match decode_wire_serialized::<ManifestActionInvocation>(&command).await {
                        Ok(invocation) => {
                            let active_mode_id = decode_view_state(&view_state).await.active_mode_id;
                            let owner_matches = PLUGIN.with(|slot| slot.borrow().as_ref().is_some_and(|program| program.manifest.plugin_id == invocation.address.plugin_id));
                            if !owner_matches {
                                Err(plugin_internal_fault(format!("action plugin owner {} does not match the active program", invocation.address.plugin_id)))
                            } else {
                                with_instances_mut(|list| {
                                    let instance = find_instance(list, instance_id)?;
                                    resolve_ready(instance.app.handle_action_invocation(&invocation, active_mode_id.as_deref(), &meta))
                                }).await
                            }
                        }
                        Err(_) => match decode_wire_serialized::<ManifestCommandInvocation>(&command).await {
                            Ok(invocation) => {
                                let active_mode_id = decode_view_state(&view_state).await.active_mode_id;
                                match &invocation.address.owner {
                                    ManifestCommandOwnerAddress::Os => Err(plugin_internal_fault("os commands must be dispatched by the os host")),
                                    ManifestCommandOwnerAddress::Plugin { .. } => PLUGIN.with(|slot| {
                                        let program = slot.borrow();
                                        program.as_ref().ok_or_else(|| plugin_internal_fault("plugin not initialized"))?.handle_plugin_command(&invocation, &meta)
                                    }).await,
                                    ManifestCommandOwnerAddress::App { plugin_id, .. } | ManifestCommandOwnerAddress::Mode { plugin_id, .. } => {
                                        let owner_matches = PLUGIN.with(|slot| slot.borrow().as_ref().is_some_and(|program| program.manifest.plugin_id == *plugin_id));
                                        if !owner_matches {
                                            Err(plugin_internal_fault(format!("command plugin owner {plugin_id} does not match the active program")))
                                        } else {
                                            with_instances_mut(|list| {
                                                let instance = find_instance(list, instance_id)?;
                                                resolve_ready(instance.app.handle_command(&invocation, active_mode_id.as_deref(), &meta))
                                            }).await
                                        }
                                    }
                                }
                            }
                            Err(_) => with_instances_mut(|list| {
                                let instance = find_instance(list, instance_id)?;
                                resolve_ready(instance.app.handle_command_frame(&command, &meta))
                            }).await,
                        },
                    };
                    match dispatched {
                        Ok(result) => {
                            // 🔀️ Contract §5.1: a gesture whose mutations carried foreign steps
                            // applied nothing (`dispatch_emit` stashed a proposal instead) — frame
                            // `AppFrame::TransactionProposal` in place of the ordinary
                            // `Invocation` frame whenever one is pending.
                            let (proposal, report) = with_instances_mut(|list| {
                                let instance = find_instance(list, instance_id)?;
                                Ok((resolve_ready(instance.app.take_pending_transaction_proposal()), resolve_ready(instance.app.dispatch_report()).clone()))
                            }).await?;
                            if let Some(proposal) = proposal {
                                frames.push(transaction_proposal_frame(instance_id, seq, proposal).await);
                            } else {
                                mutated = true;
                                let output = encode_wire_serialized(&result.output).await;
                                let diagnostics = encode_wire_serialized(&result.diagnostics).await;
                                frames.push(protocol::AppFrame::Invocation {
                                    in_reply_to: seq,
                                    output,
                                    diagnostics,
                                    ui_scope: encode_wire_serialized(&result.ui_scope).await,
                                    history_patch: encode_wire_serialized(&result.history_patch).await,
                                    messages: encode_wire_serialized(&report).await,
                                });
                            }
                            push_invocation_side_frames(&mut effect_bytes, &mut event_bytes, &result).await;
                        }
                        Err(fault) => {
                            let report = with_instances_mut(|list| {
                                let instance = find_instance(list, instance_id)?;
                                Ok(resolve_ready(instance.app.dispatch_report()).clone())
                            }).await?;
                            push_dispatch_fault(&mut frames, seq, fault, &report);
                        }
                    }
                }
                protocol::AppCommand::CommandText { seq, line: _ } => {
                    // 🚧️ Wave 1 stub — see this function's doc comment.
                    push_os_fault(&mut frames, Some(seq), "unsupported", "CommandText not yet wired".into());
                }
                protocol::AppCommand::ContextMenu { seq, request } => {
                    // 🗂️ Decodes straight into the typed wire shape and encodes the typed response straight
                    // back out — no intermediate `Value`/JSON-string hop through `plugin_context_menu`
                    // (which stays as the separate string-in/string-out entry point the WIT boundary needs).
                    match decode_wire_serialized::<ContextMenuWireRequest>(&request).await {
                        Ok(wire) => {
                            let request: ContextMenuRequest = wire.into();
                            let outcome = with_instances_mut(|list| {
                                let instance = find_instance(list, instance_id)?;
                                Ok(resolve_ready(instance.app.context_menu(&request)))
                            });
                            match outcome.await {
                                Ok(items) => frames.push(protocol::AppFrame::ContextMenu { in_reply_to: seq, items: encode_wire_serialized(&items).await }),
                                Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                            }
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::ArtifactCommand { seq, command } => {
                    let envelope: Value = decode_wire_serialized_or(&command, Value::Null).await;
                    let action = envelope.get("action").and_then(Value::as_str).unwrap_or("").to_string();
                    let args = envelope.get("args").cloned();
                    if !DOCUMENT_COMMAND_ACTION_IDS.contains(&action.as_str()) {
                        push_os_fault(&mut frames, Some(seq), "unsupported", format!("ArtifactCommand action {action:?} not supported (Wave 1: history verbs only)"));
                        continue;
                    }
                    let meta = ActionMeta { actor: instance_actor(instance_id).await, instance_id };
                    let dispatched = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.handle_action(&action, args.as_ref(), &meta))
                    });
                    match dispatched.await {
                        Ok(result) => {
                            // 🔀️ Same proposal check as `AppCommand::Command` above — the six
                            // history verbs never carry foreign steps in practice, but
                            // `dispatch_emit` is the shared choke point, so this arm is covered too.
                            let proposal = with_instances_mut(|list| {
                                let instance = find_instance(list, instance_id)?;
                                Ok(resolve_ready(instance.app.take_pending_transaction_proposal()))
                            })
                            .await.unwrap_or(None);
                            if let Some(proposal) = proposal {
                                frames.push(transaction_proposal_frame(instance_id, seq, proposal).await);
                            } else {
                                mutated = true;
                                frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                            }
                            push_invocation_side_frames(&mut effect_bytes, &mut event_bytes, &result).await;
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::ApplyEnvelopes { seq, envelopes } => {
                    let encoded = protocol::encode_envelopes(&envelopes);
                    match plugin_ingest_operations(instance_id, &encoded).await {
                        Ok(reports) => {
                            mutated = true;
                            frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                            // ⚔️ Pushed unsolicited after every ingest, next to `DocumentChanged`
                            // (contract §C8): one `MergeReport` per ingested envelope, then the
                            // authoritative open-conflict projection once the whole batch has landed.
                            for report in &reports {
                                frames.push(protocol::AppFrame::MergeReport { in_reply_to: None, report: encode_wire_serialized(report).await });
                            }
                            if !reports.is_empty() {
                                let open: Vec<protocol::Conflict> = with_instances_mut(|list| {
                                    let instance = find_instance(list, instance_id)?;
                                    Ok(resolve_ready(instance.app.open_conflicts()))
                                }).await?;
                                frames.push(protocol::AppFrame::Conflicts { in_reply_to: None, conflicts: encode_wire_serialized(&open).await });
                            }
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::LoadDocument { seq, pack, spr } => {
                    let files = store::ArtifactPackFiles { pack, spr, ops: String::new() };
                    match plugin_load_document_pack(instance_id, &files).await {
                        Ok(()) => {
                            mutated = true;
                            frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::ReadDocument { seq } => match plugin_document_pack(instance_id).await {
                    Ok(files) => frames.push(protocol::AppFrame::Document { in_reply_to: seq, pack: files.pack, spr: files.spr, ops: files.ops }),
                    Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                },
                // 🧸️ Composed children are their own envelopes with their own histories, so they
                // need their own load/read pair — a parent's `LoadDocument`/`Document` carries none
                // of them, and before this existed a genesis child lived only until the process
                // ended.
                protocol::AppCommand::LoadChildren { seq, entries } => {
                    let loaded = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        for entry in &entries {
                            // 🌉️ `with_instances_mut`'s callback is deliberately sync (single-threaded
                            // `RefCell::borrow_mut` reentrancy guard, see its own doc comment) —
                            // bridged via `resolve_ready` exactly like `media_fingerprint` above.
                            let dialect = resolve_ready(store::os_io::ArtifactDialect::parse_coordinate(&entry.dialect)).map_err(|error| Fault::new(FaultOrigin::Plugin, FaultCode::new("plugin.internal"), error))?;
                            resolve_ready(instance.app.load_child_pack(&entry.slot, &entry.child_id, dialect, &entry.envelope_pack))?;
                        }
                        Ok(())
                    });
                    match loaded.await {
                        Ok(()) => {
                            mutated = true;
                            frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::ReadChildren { seq } => {
                    let read = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.child_packs())
                    });
                    match read.await {
                        Ok(entries) => frames.push(protocol::AppFrame::Children { in_reply_to: seq, entries }),
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::ReadHistory { seq } => {
                    let snapshot = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.history_snapshot())
                    });
                    match snapshot.await {
                        Ok(history_patch) => frames.push(protocol::AppFrame::HistorySnapshot { in_reply_to: seq, history_patch: encode_wire_serialized(&history_patch).await }),
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::LoadConfig { seq, pack, spr } => {
                    // 🧮️ B1: real work — loads straight into the config `ArtifactStore` (was routed
                    // through the deleted `apply_config_bytes` whole-record-replace legacy path).
                    let applied = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.load_config_pack(&store::ArtifactPackFiles { pack, spr, ops: String::new() }))
                    });
                    match applied.await {
                        Ok(()) => frames.push(protocol::AppFrame::Done { in_reply_to: seq }),
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::ReadConfig { seq } => {
                    // 🧮️ B1: real work — the config store's current pack+spr+ops (was a stub always
                    // returning empty bytes).
                    let read = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.config_pack())
                    });
                    match read.await {
                        Ok(files) => frames.push(protocol::AppFrame::Config { in_reply_to: seq, pack: files.pack, spr: files.spr, ops: files.ops }),
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::MediaIn { seq, port, descriptor, data } => {
                    let descriptor_value: Value = decode_wire_serialized_or(&descriptor, Value::Null).await;
                    let descriptor_json = serde_json::to_string(&descriptor_value).unwrap_or_else(|_| "{}".into());
                    match plugin_consume_media(instance_id, &port, &descriptor_json, data).await {
                        Ok(()) => {
                            mutated = true;
                            frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::MediaOut { seq, port, request: _ } => match plugin_produce_media(instance_id, &port, "").await {
                    Ok((descriptor_json, data)) => {
                        let descriptor_value: Value = serde_json::from_str(&descriptor_json).unwrap_or(Value::Null);
                        frames.push(protocol::AppFrame::Media { in_reply_to: seq, port, descriptor: encode_wire_serialized(&descriptor_value).await, data });
                    }
                    Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                },
                protocol::AppCommand::MediaFingerprint { seq, port } => {
                    let fingerprint = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.media_fingerprint(&port)).map_err(|error| plugin_internal_fault(error.to_string()))
                    });
                    match fingerprint.await {
                        Ok(fingerprint) => {
                            let value = serde_json::to_value(&fingerprint).unwrap_or_default();
                            frames.push(protocol::AppFrame::MediaFingerprint { in_reply_to: seq, port, fingerprint: encode_wire_serialized(&value).await });
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::PureCommand { seq, command, document, document_spr, config, config_spr, draft, draft_spr } => {
                    let meta = ActionMeta { actor: instance_actor(instance_id).await, instance_id };
                    let dispatched = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.hydrate_document_lane(&document, &document_spr))?;
                        resolve_ready(instance.app.hydrate_config_lane(&config, &config_spr))?;
                        resolve_ready(instance.app.hydrate_draft_lane(&draft, &draft_spr))?;
                        let result = resolve_ready(instance.app.handle_command_frame(&command, &meta))?;
                        let emit_wire = resolve_ready(instance.app.take_last_emit_wire()).unwrap_or_default();
                        Ok((result, emit_wire))
                    });
                    match dispatched.await {
                        Ok((result, (document_ops, config_ops, draft_ops))) => {
                            mutated = true;
                            let output = encode_wire_serialized(&result.output).await;
                            let diagnostics = encode_wire_serialized(&result.diagnostics).await;
                            frames.push(protocol::AppFrame::Emit { in_reply_to: seq, document_ops, config_ops, draft_ops, output, diagnostics });
                            push_invocation_side_frames(&mut effect_bytes, &mut event_bytes, &result).await;
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                // 🔀️ Member state machine (contract §5.3-§5.10) — see `📓️w1-b-report.md` for the
                // full frame/rejection-code table.
                protocol::AppCommand::TransactionPrepare { seq, txn_id, mutation_id, payload, prepared_ops, label, origin } => {
                    let decoded_origin = if origin.is_empty() {
                        None
                    } else {
                        match decode_wire_serialized::<protocol::MutationOrigin>(&origin).await {
                            Ok(value) => Some(value),
                            Err(fault) => {
                                push_app_fault(&mut frames, Some(seq), fault);
                                continue;
                            }
                        }
                    };
                    let outcome = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        Ok(resolve_ready(instance.app.transaction_prepare(&txn_id, &mutation_id, &payload, &prepared_ops, &label, decoded_origin)))
                    });
                    match outcome.await {
                        Ok(outcome) => {
                            let mut foreign = Vec::with_capacity(outcome.foreign.len());
                            for step in outcome.foreign.iter() {
                                foreign.push(encode_wire_serialized(step).await);
                            }
                            let rejection = match outcome.rejection {
                                Some(fault) => encode_wire_serialized(&fault).await,
                                None => Vec::new(),
                            };
                            frames.push(protocol::AppFrame::TransactionPrepared { txn_id, foreign, rejection });
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::TransactionCommit { seq, txn_id } => {
                    let meta = ActionMeta { actor: instance_actor(instance_id).await, instance_id };
                    let outcome = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.transaction_commit(&txn_id, &meta))
                    });
                    match outcome.await {
                        Ok(edit_id) => {
                            mutated = true;
                            frames.push(protocol::AppFrame::TransactionCommitted { txn_id, edit_id });
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::TransactionRollback { seq, txn_id } => {
                    let outcome = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.transaction_rollback(&txn_id))
                    });
                    match outcome.await {
                        Ok(()) => frames.push(protocol::AppFrame::TransactionRolledBack { txn_id }),
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::TransactionUndo { seq, group_id } => {
                    let outcome = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.transaction_undo(&group_id))
                    });
                    match outcome.await {
                        Ok(()) => {
                            mutated = true;
                            frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::TransactionRedo { seq, group_id } => {
                    let outcome = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(instance.app.transaction_redo(&group_id))
                    });
                    match outcome.await {
                        Ok(()) => {
                            mutated = true;
                            frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::OpenArtifact { seq, artifact_ref, role, plugin_id, app_id } => match relay_open_artifact(artifact_ref, role, plugin_id, app_id).await {
                    Ok(effect) => {
                        frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                        effect_bytes.push(encode_wire_serialized(&effect).await);
                    }
                    Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                },
                protocol::AppCommand::SetDefaultApp { seq, artifact_kind, standard, subset, role, plugin_id, app_id } => match relay_set_default_app(artifact_kind, standard, subset, role, plugin_id, app_id).await {
                    Ok(effect) => {
                        frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                        effect_bytes.push(encode_wire_serialized(&effect).await);
                    }
                    Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                },
                protocol::AppCommand::ClearDefaultApp { seq, artifact_kind, standard, subset, role } => match relay_clear_default_app(artifact_kind, standard, subset, role).await {
                    Ok(effect) => {
                        frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                        effect_bytes.push(encode_wire_serialized(&effect).await);
                    }
                    Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                },
                protocol::AppCommand::SetMergePolicy { seq, policy } => {
                    let outcome = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(set_merge_policy_frames(instance.app.as_mut(), seq, policy))
                    });
                    match outcome.await {
                        Ok(outcome) => frames.extend(outcome),
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::ResolveConflict { seq, conflict_id, resolution } => {
                    let outcome = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        resolve_ready(resolve_conflict_frames(instance.app.as_mut(), seq, conflict_id, resolution))
                    });
                    match outcome.await {
                        Ok(outcome) => frames.extend(outcome),
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
                protocol::AppCommand::ReadConflicts { seq } => {
                    let outcome = with_instances_mut(|list| {
                        let instance = find_instance(list, instance_id)?;
                        Ok(resolve_ready(read_conflicts_frames(instance.app.as_ref(), seq)))
                    });
                    match outcome.await {
                        Ok(outcome) => frames.extend(outcome),
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
                }
            }
        }

        if mutated {
            let effects = with_instances_mut(|list| {
                let instance = find_instance(list, instance_id)?;
                Ok(resolve_ready(instance.app.pending_effects()))
            })
            .await.unwrap_or_default();
            for effect in effects.iter() {
                effect_bytes.push(encode_wire_serialized(effect).await);
            }
        }

        let ephemeral = with_instances_mut(|list| {
            let instance = find_instance(list, instance_id)?;
            Ok(resolve_ready(instance.app.ephemeral_snapshot()))
        });
        if let Ok(EphemeralSnapshot { presence, presence_generation, transient_generation, interaction }) = ephemeral.await {
            frames.push(protocol::AppFrame::Ephemeral { presence, presence_generation, transient_generation, interaction });
        }

        Ok(PluginExchangeOutput { frames: frames.iter().map(protocol::encode_app_frame).collect(), effects: effect_bytes, events: event_bytes })
    }
    //#endregion 🔖️Exchange

    #[macro_export]
    macro_rules! plugin_exports {
        ($bundle_fn:expr) => {
            // 🚫️async: E4 fn-pointer slot — this fn's VALUE is stored in `PLUGIN_BUNDLE_INSTALLER:
            // OnceLock<fn()>` via `register_plugin_bundle_installer`, so it can never itself be
            // `async fn`; bridged to the still-async `install_plugin_bundle_result` via `resolve_ready`
            // (the builder never truly suspends).
            fn __semio_install_plugin_bundle() {
                $crate::app::resolve_ready($crate::plugin_runtime::install_plugin_bundle_result(($bundle_fn)()));
            }

            #[doc(hidden)]
            #[unsafe(no_mangle)]
            pub extern "C" fn semio_plugin_bundle_installer_link_shim() {
                $crate::plugin_runtime::register_plugin_bundle_installer(__semio_install_plugin_bundle);
            }

            #[doc(hidden)]
            #[unsafe(no_mangle)]
            pub extern "C" fn semio_plugin_install_bundle() {
                __semio_install_plugin_bundle();
            }

            #[cfg(all(target_arch = "wasm32", target_env = "p2"))]
            #[used]
            static _SEMIO_PLUGIN_COMPONENT_LINK: fn() = $crate::component_export_anchor;

            // 🛂️ E1-describe (`📓️design-abi.md` §3), path corrected by E2-builder-descriptor: freshness
            // without wasm in the loop — natively installs the bundle (bypassing
            // `ensure_plugin_initialized`'s `component-guest`-gated weak-linkage shim, which only
            // fires on a real wasm build) and byte-compares `describe::describe_plugin()`'s packed
            // output against the crate's checked-in `<owner>/🛂️descriptor.semio`. Registrar ruling
            // (`📌️important.md`, this ticket): descriptors live at the plugin/extension OWNER ROOT,
            // sibling of the tracked `🛂️manifest.json` — NOT under `🤖️generated/`, which is globally
            // gitignored (`.gitignore` 87-88) and would mean this checked-in file could never survive
            // a commit; `📓️design-abi.md` §3's `🤖️generated` path is superseded.
            //
            // 🚦️ D0-descriptor-plumbing ratchet: a missing committed descriptor is a HARD failure only
            // for a plugin explicitly named in `DESCRIPTOR_MIGRATED_PLUGINS` below — this is the
            // "explicit opt-in, visible per plugin" gate `important.md` calls for, so the fleet does not
            // go red before each plugin's own emission packet lands. Extend this list from a plugin's
            // D-packet report the moment its `🛂️descriptor.semio` + `🔣️descriptor.json` are committed —
            // never remove a name once added (that would be silently re-hiding a regression). The
            // repo-wide ratchet metric this ladder climbs against is `📇️registry:check`'s own
            // "descriptor gate: N/<total> crates have a 🔣️descriptor.json" census line — that count is
            // the thing that should trend toward `<total>` as this list grows, never this test alone.
            #[cfg(test)]
            #[semio_framework_async_macros::async_test]
            async fn descriptor_is_fresh() {
                __semio_install_plugin_bundle();
                let plugin_id = $crate::plugin_runtime::plugin_manifest().plugin_id;
                let assembled = $crate::describe::describe_plugin();
                let expected_path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../🛂️descriptor.semio");
                const DESCRIPTOR_MIGRATED_PLUGINS: &[&str] = &["note", "sequence", "vcs", "forms", "sourcing", "dag", "mathematical", "writer", "reasoning-mindmap", "animate", "draw", "energy", "layout"];
                match std::fs::read(expected_path) {
                    Ok(expected) => {
                        if let (Some(assembled), Some(expected)) = ($crate::plugin_runtime::descriptor_bytes_with_blank_hashes(&assembled), $crate::plugin_runtime::descriptor_bytes_with_blank_hashes(&expected)) {
                            assert_eq!(assembled, expected, "{expected_path} is stale — re-run `describe` (📓️design-abi.md §3) and commit the refreshed 🛂️descriptor.semio + 🔣️descriptor.json");
                        }
                    }
                    Err(_) => {
                        assert!(!DESCRIPTOR_MIGRATED_PLUGINS.contains(&plugin_id.as_str()), "{expected_path} is missing but {plugin_id:?} is listed in DESCRIPTOR_MIGRATED_PLUGINS — run `describe` and commit 🛂️descriptor.semio + 🔣️descriptor.json");
                    }
                }
            }
        };
    }

    //#region 🧩️Extension
    /// 🧩️ Extension guest bundle — no apps; contributes + invoke handlers.
    pub struct ExtensionBundle {
        pub manifest: ExtensionManifest,
        handlers: HashMap<String, Box<dyn Fn(&[u8]) -> Result<Vec<u8>, Fault> + Send + 'static>>,
    }

    /// 📦️ Manifest for a runtime-installable extension (WIT `extension::manifest` payload).
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub struct ExtensionManifest {
        pub extension_id: String,
        pub label: String,
        pub version: String,
        pub extends: String,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        pub capabilities: Vec<CapabilityRequirement>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        pub topic_contributions: Vec<TopicContribution>,
        /// 🔗️ Direct plugin dependencies this extension requires — contract freeze §3/§4: `extends`
        /// MUST equal `dependencies[0].plugin_id`; `.extends`/`.depends_on` both assert this on every
        /// call that could violate it. Real `semio_framework::PluginDependency` (not a local mirror —
        /// `semio-framework-plugin` already depends on `semio-framework`, unlike the `.sxt` package
        /// format's own `ExtensionPackageManifest`).
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        pub dependencies: Vec<semio_framework::PluginDependency>,
        /// 🗂️ Artifact-kind contributions this extension contributes onto artifact kinds it depends on.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        pub contributions: Vec<semio_framework::ArtifactContributionDescriptor>,
        /// 🚦️ `📓️design-abi.md` §5 — how this extension's actor runs relative to its host plugin.
        /// Default `Isolated` (`ExecutionMode::default()`), set via `ExtensionBundle::mode(..)`.
        #[serde(default)]
        pub execution: ExecutionMode,
        /// 🙏️ Capability asks the broker resolves at install/link/runtime, set via
        /// `ExtensionBundle::requests(..)` — the NEW broker-scoped `kernel::CapabilityRequest`, not
        /// the older kernel-level `CapabilityRequirement` `capabilities` above carries (see that
        /// field's own doc for why both exist).
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        pub capability_requests: Vec<CapabilityRequest>,
    }

    impl ExtensionBundle {
        /// 🧩️ Starts an extension bundle with identity + version.
        pub async fn new(extension_id: impl Into<String>, label: impl Into<String>, version: impl Into<String>) -> Self {
            Self {
                manifest: ExtensionManifest {
                    extension_id: extension_id.into(),
                    label: label.into(),
                    version: version.into(),
                    extends: String::new(),
                    capabilities: Vec::new(),
                    topic_contributions: Vec::new(),
                    dependencies: Vec::new(),
                    contributions: Vec::new(),
                    execution: ExecutionMode::default(),
                    capability_requests: Vec::new(),
                },
                handlers: HashMap::new(),
            }
        }

        /// 🔗 Declares the host app/plugin this extension extends.
        pub async fn extends(mut self, extends: impl Into<String>) -> Self {
            self.manifest.extends = extends.into();
            self.assert_extends_matches_primary_dependency();
            self
        }

        /// 🔗️ Declares a direct plugin dependency — contract freeze §3/§4: the FIRST dependency
        /// declared (in call order) must be the same plugin `.extends(...)` names.
        pub async fn depends_on(mut self, plugin_id: impl Into<String>, version: semio_framework::VersionReq) -> Self {
            self.manifest.dependencies.push(semio_framework::PluginDependency::new(plugin_id, version).await);
            self.assert_extends_matches_primary_dependency();
            self
        }

        /// 🚨️ Contract freeze §3/§4: `extends == dependencies[0].plugin_id`. Panics on violation — the
        /// same misuse-reporting idiom `Plugin::plugin_command`'s `assert!`s already use elsewhere in
        /// this file, since every `ExtensionBundle` builder method is infallible (`-> Self`, never
        /// `Result`). Called from both `.extends`/`.depends_on` so the check holds regardless of call
        /// order; a no-op until both fields are non-empty.
        async fn assert_extends_matches_primary_dependency(&self) {
            if self.manifest.extends.is_empty() {
                return;
            }
            if let Some(primary) = self.manifest.dependencies.first() {
                assert_eq!(
                    primary.plugin_id, self.manifest.extends,
                    "extension {:?} declares extends={:?} but its first dependency is {:?} — contract freeze §3/§4 requires extends == dependencies[0].plugin_id",
                    self.manifest.extension_id, self.manifest.extends, primary.plugin_id
                );
            }
        }

        /// 🔒️ Declares a capability requirement for the extension.
        pub async fn capability(mut self, capability: CapabilityRequirement) -> Self {
            if !self.manifest.capabilities.contains(&capability) {
                self.manifest.capabilities.push(capability);
            }
            self
        }

        /// 🗂️ Adds an open topic contribution to the extension manifest; `topic` reuses this crate's
        /// own `contributes`/`consumes` metadata vocabulary (e.g. `"cad.computer"`).
        pub async fn contributes_topic(mut self, topic: impl Into<String>, payload: Value) -> Self {
            self.manifest.topic_contributions.push(TopicContribution::new(topic, payload).await);
            self
        }

        /// 🗂️ Declares one contribution of mutations/inferences onto an artifact kind owned by a
        /// dependency. Resolved IMMEDIATELY (unlike `PluginBuilder::contributes`, an extension's own id
        /// is already known at `ExtensionBundle::new()`): gate-checked via
        /// `crate::app::register_contributions` and committed to the same process-global runtime
        /// registries `PluginBuilder::try_build` commits to. Panics on a gate violation — same idiom as
        /// `.extends`/`.depends_on` above.
        pub async fn contributes(mut self, contribution: crate::app::ArtifactContribution) -> Self {
            let contributor = self.manifest.extension_id.clone();
            let (descriptor, inference_services, mutation_runtime) = contribution.resolve(&contributor).await;
            crate::app::register_contributions(&contributor, &self.manifest.dependencies, std::slice::from_ref(&descriptor)).await.unwrap_or_else(|error| panic!("extension {contributor:?} contribution rejected: {error}"));
            crate::app::preflight_artifact_inference_services(&inference_services).await.unwrap_or_else(|error| panic!("extension {contributor:?} contributed inference service conflict: {error}"));
            crate::app::register_artifact_inference_services(inference_services).await.unwrap_or_else(|error| panic!("extension {contributor:?} contributed inference service registration failed: {error}"));
            crate::app::commit_contributed_mutation_services(mutation_runtime).await.unwrap_or_else(|error| panic!("extension {contributor:?} contributed mutation registration failed: {error}"));
            self.manifest.contributions.push(descriptor);
            self
        }

        /// 🔀️ Registers a capability handler invoked via WIT `extension::invoke`.
        pub async fn handler(mut self, capability: impl Into<String>, handler: impl Fn(&[u8]) -> Result<Vec<u8>, Fault> + Send + 'static) -> Self {
            self.handlers.insert(capability.into(), Box::new(handler));
            self
        }

        /// 🚦️ Sets how this extension's actor runs relative to its host plugin — default `Isolated`
        /// (`📓️design-abi.md` §5).
        pub async fn mode(mut self, mode: ExecutionMode) -> Self {
            self.manifest.execution = mode;
            self
        }

        /// 🙏️ Declares one capability ask the broker resolves at install/link/runtime
        /// (`📓️design-abi.md` §5). Repeatable; idempotent for a byte-identical ask.
        pub async fn requests(mut self, request: CapabilityRequest) -> Self {
            if !self.manifest.capability_requests.contains(&request) {
                self.manifest.capability_requests.push(request);
            }
            self
        }
    }

    #[cfg(test)]
    mod extension_bundle_dependency_tests {
        use super::*;

        #[semio_framework_async_macros::async_test]
        async fn extends_mismatching_the_first_dependency_panics() {
            let result = std::panic::catch_unwind(|| ExtensionBundle::new("ext-mismatch", "Ext Mismatch", "0.1.0").depends_on("primary-dep", semio_framework::VersionReq::Any).extends("someone-else"));
            assert!(result.is_err(), "extends != dependencies[0].plugin_id must panic");
        }

        #[semio_framework_async_macros::async_test]
        async fn extends_set_before_a_mismatching_dependency_also_panics() {
            let result = std::panic::catch_unwind(|| ExtensionBundle::new("ext-mismatch-2", "Ext Mismatch 2", "0.1.0").extends("primary-dep").depends_on("someone-else", semio_framework::VersionReq::Any));
            assert!(result.is_err(), "extends != dependencies[0].plugin_id must panic regardless of call order");
        }

        #[semio_framework_async_macros::async_test]
        async fn extends_matching_the_first_dependency_is_accepted_regardless_of_call_order() {
            let bundle = ExtensionBundle::new("ext-ok", "Ext Ok", "0.1.0").extends("primary-dep").depends_on("primary-dep", semio_framework::VersionReq::Any).depends_on("secondary-dep", semio_framework::VersionReq::Any);
            assert_eq!(bundle.manifest.dependencies[0].plugin_id, "primary-dep");
            assert_eq!(bundle.manifest.dependencies[1].plugin_id, "secondary-dep");
            assert_eq!(bundle.manifest.extends, "primary-dep");
        }
    }

    thread_local! {
        static EXTENSION_BUNDLE: RefCell<Option<ExtensionBundle>> = const { RefCell::new(None) };
        static EXTENSION_ACTIVE: Cell<bool> = const { Cell::new(false) };
    }

    /// 📤️ Installs the process-local extension bundle (from `extension_exports!`).
    pub async fn install_extension_bundle(bundle: ExtensionBundle) {
        EXTENSION_BUNDLE.with(|slot| {
            *slot.borrow_mut() = Some(bundle);
        });
        EXTENSION_ACTIVE.with(|slot| slot.set(false));
    }

    // 🚫️async: E4 fn-pointer slot
    static EXTENSION_BUNDLE_INSTALLER: std::sync::OnceLock<fn()> = std::sync::OnceLock::new();

    /// 🧩️ Registers the embedding extension crate's bundle installer (expanded from `extension_exports!`).
    pub async fn register_extension_bundle_installer(install: fn()) {
        let _ = EXTENSION_BUNDLE_INSTALLER.set(install);
    }

    /// 🔗️ Weak default mirroring `semio_plugin_bundle_installer_link_shim` (see that symbol's own
    /// doc comment): lets an intermediate link succeed before the embedding extension crate's
    /// `extension_exports!` provides the strong override. Without this default AND the explicit call
    /// below, `EXTENSION_BUNDLE_INSTALLER` is never populated — no code path ever invoked this
    /// symbol, so `register_extension_bundle_installer` was silently never called and every real
    /// extension's `manifest()`/`activate()` observed only the empty-default `ExtensionBundle`.
    #[cfg(feature = "component-extension-guest")]
    #[unsafe(no_mangle)]
    #[linkage = "weak"]
    pub extern "C" fn semio_extension_bundle_installer_link_shim() {}

    /// Ensures the embedding extension crate's bundle installer ran before any WIT export is served
    /// — mirrors `ensure_plugin_initialized`'s explicit weak/strong-linkage shim call.
    async fn ensure_extension_initialized() {
        EXTENSION_BUNDLE.with(|slot| {
            if slot.borrow().is_none() {
                #[cfg(feature = "component-extension-guest")]
                unsafe {
                    semio_extension_bundle_installer_link_shim();
                }
                if let Some(install) = EXTENSION_BUNDLE_INSTALLER.get() {
                    install();
                }
            }
        });
    }

    /// 📦️ Returns the installed extension manifest (empty defaults when unset).
    pub async fn extension_manifest() -> ExtensionManifest {
        ensure_extension_initialized();
        EXTENSION_BUNDLE.with(|slot| {
            slot.borrow().as_ref().map(|bundle| bundle.manifest.clone()).unwrap_or_else(|| ExtensionManifest {
                extension_id: String::new(),
                label: String::new(),
                version: String::new(),
                extends: String::new(),
                capabilities: Vec::new(),
                topic_contributions: Vec::new(),
                dependencies: Vec::new(),
                contributions: Vec::new(),
                execution: ExecutionMode::default(),
                capability_requests: Vec::new(),
            })
        })
    }

    /// 🚨️ Marks the extension active for subsequent `extension_invoke` calls.
    pub async fn extension_activate() -> Result<(), Fault> {
        ensure_extension_initialized();
        let ready = EXTENSION_BUNDLE.with(|slot| slot.borrow().is_some());
        if !ready {
            return Err(Fault::new(FaultOrigin::Plugin, FaultCode::new("extension.missing"), "extension bundle not installed"));
        }
        EXTENSION_ACTIVE.with(|slot| slot.set(true));
        Ok(())
    }

    /// 🛑 Clears the active flag without dropping handlers.
    pub async fn extension_deactivate() {
        EXTENSION_ACTIVE.with(|slot| slot.set(false));
    }

    /// 🔀️ Dispatches `capability` to the registered handler with wire-encoded `request` bytes.
    pub async fn extension_invoke(capability: &str, request: &[u8]) -> Result<Vec<u8>, Fault> {
        ensure_extension_initialized();
        if !EXTENSION_ACTIVE.with(|slot| slot.get()) {
            return Err(Fault::new(FaultOrigin::Plugin, FaultCode::new("extension.inactive"), "extension not activated"));
        }
        EXTENSION_BUNDLE.with(|slot| {
            let bundle = slot.borrow();
            let Some(bundle) = bundle.as_ref() else {
                return Err(Fault::new(FaultOrigin::Plugin, FaultCode::new("extension.missing"), "extension bundle not installed"));
            };
            let Some(handler) = bundle.handlers.get(capability) else {
                return Err(Fault::new(FaultOrigin::Plugin, FaultCode::new("extension.unknown-capability"), format!("unknown extension capability '{capability}'")));
            };
            handler(request)
        })
    }

    /// 🚧️ PLACEHOLDER for W1-A. PLUGIN-DEPENDENCIES-ARTIFACT-CONTRIBUTIONS-AND-COMPOSITE-MUTATIONS
    /// (§6): `extension-world` now exports `contributor` alongside `extension`, but no extension has
    /// ever wired inference services — this is a deterministic EMPTY roster
    /// (`store::pack_rt::encode_wire_value` of an empty list) until W1-A adds real extension-side
    /// inference wiring (mirroring `crate::app::wire_list_artifact_inference_services`, plugin-side).
    pub async fn extension_wire_list_artifact_inferences() -> Vec<u8> {
        store::pack_rt::encode_wire_value(&dsl::DslValue::Array(Vec::new())).await
    }

    /// 🚧️ PLACEHOLDER for W1-A. Companion to `extension_wire_list_artifact_inferences` — since the
    /// roster above is always empty, this can never legitimately be called; it exists only so
    /// `contributor.artifact-infer` type-checks on `extension-world`. Always returns a typed `Fault`.
    pub async fn extension_wire_artifact_infer() -> Fault {
        plugin_internal_fault("artifact-infer not implemented for extensions (W1-A placeholder)")
    }

    /// 🧩️ Installs an extension crate's bundle builder into TLS for WIT guest exports.
    #[macro_export]
    macro_rules! extension_exports {
        ($bundle_fn:expr) => {
            // 🚫️async: E4 fn-pointer slot — see `plugin_exports!`'s `__semio_install_plugin_bundle` doc.
            fn __semio_install_extension_bundle() {
                $crate::app::resolve_ready($crate::plugin_runtime::install_extension_bundle(($bundle_fn)()));
            }

            #[doc(hidden)]
            #[unsafe(no_mangle)]
            pub extern "C" fn semio_extension_bundle_installer_link_shim() {
                $crate::plugin_runtime::register_extension_bundle_installer(__semio_install_extension_bundle);
            }

            #[doc(hidden)]
            #[unsafe(no_mangle)]
            pub extern "C" fn semio_extension_install_bundle() {
                __semio_install_extension_bundle();
            }

            // 🧬️ A2 (design-abi.md §1): one `world actor` for both roles now — extensions link the
            // SAME `component_export_anchor` a plugin does (the old separate `extension-world`
            // component/anchor is deleted, see `important.md`'s "Replace, never wrap" list).
            #[cfg(all(target_arch = "wasm32", target_env = "p2"))]
            #[used]
            static _SEMIO_EXTENSION_COMPONENT_LINK: fn() = $crate::component_export_anchor;

            // 🛂️ E1-describe (`📓️design-abi.md` §3) — see `plugin_exports!`'s identical test for the
            // full rationale (native install, no wasm) and for E2-builder-descriptor's path correction
            // (owner root, not `🤖️generated/` — that's gitignored, see the registrar ruling quoted
            // there). `describe::describe_extension()` is this macro's own counterpart of
            // `describe_plugin()`.
            //
            // 🚦️ D0-descriptor-plumbing ratchet — see `plugin_exports!`'s identical test for the full
            // rationale. `DESCRIPTOR_MIGRATED_EXTENSIONS` starts empty: no extension has committed a
            // descriptor yet as of this packet; extend it, never shrink it, as each extension's own
            // emission packet lands.
            #[cfg(test)]
            #[semio_framework_async_macros::async_test]
            async fn descriptor_is_fresh() {
                __semio_install_extension_bundle();
                let extension_id = $crate::plugin_runtime::extension_manifest().extension_id;
                let assembled = $crate::describe::describe_extension();
                let expected_path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../🛂️descriptor.semio");
                const DESCRIPTOR_MIGRATED_EXTENSIONS: &[&str] = &[];
                match std::fs::read(expected_path) {
                    Ok(expected) => {
                        if let (Some(assembled), Some(expected)) = ($crate::plugin_runtime::descriptor_bytes_with_blank_hashes(&assembled), $crate::plugin_runtime::descriptor_bytes_with_blank_hashes(&expected)) {
                            assert_eq!(assembled, expected, "{expected_path} is stale — re-run `describe` (📓️design-abi.md §3) and commit the refreshed 🛂️descriptor.semio + 🔣️descriptor.json");
                        }
                    }
                    Err(_) => {
                        assert!(!DESCRIPTOR_MIGRATED_EXTENSIONS.contains(&extension_id.as_str()), "{expected_path} is missing but {extension_id:?} is listed in DESCRIPTOR_MIGRATED_EXTENSIONS — run `describe` and commit 🛂️descriptor.semio + 🔣️descriptor.json");
                    }
                }
            }
        };
    }
    //#endregion 🧩️Extension

